def decide(trace):
    if not trace:
        return (None, None, 'no observed state for declared module-identity probe')
    for row in trace:
        value = row.get('outputs', {}).get('i2c_master_bit_ctrl')
        if value != 1:
            return (False, row.get('edge'), 'declared i2c_master_bit_ctrl module-identity probe is not asserted')
    return (True, None, 'declared i2c_master_bit_ctrl module-identity probe is asserted in every observed state')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    def holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    supported = [
        {'cmd': 1, 'ena': 1},
        {'cmd': 2, 'ena': 1},
        {'cmd': 4, 'ena': 1},
        {'cmd': 8, 'ena': 1},
    ]
    opens = lambda row: any(holds(condition)(row) for condition in supported)
    closes = holds({'cmd_ack': 1})
    aborts = lambda row: any(holds(condition)(row) for condition in [
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    changed = edges(trace, 'scl_oen', 'change')
    windows = after(trace, opens, until=closes, aborts=aborts)
    return worst([
        eventually(
            window,
            lambda row: row['edge'] in changed,
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def rising(name, predicate=None):
        result = []
        previous = False
        for i, row in enumerate(trace):
            now = bool(out(row, name))
            if predicate is not None:
                now = now and predicate(row)
            if now and not previous:
                result.append(i)
            previous = now
        return result

    def first_index(start, predicate):
        for i in range(start, len(trace)):
            if predicate(trace[i]):
                return i
        return None

    def command_window(start, probe):
        end = len(trace)
        for i in range(start + 1, len(trace)):
            if not out(trace[i], probe):
                end = i
                break
        return start, end

    def fail(row, text):
        return (False, row.get('edge'), text)

    checked = False
    failures = []

    # START: release both lines, pull SDA low while SCL is released,
    # then pull SCL low, followed by completion acknowledgement.
    for start in rising('start_sequence'):
        checked = True
        lo, hi = command_window(start, 'start_sequence')
        i = first_index(lo, lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1)
        j = first_index((i if i is not None else lo),
                        lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 0)
        k = first_index((j if j is not None else lo),
                        lambda r: out(r, 'scl_oen') == 0)
        ack = first_index(lo, lambda r: out(r, 'cmd_ack') == 1)
        if i is None or j is None or k is None or not (i <= j <= k):
            failures.append(fail(trace[lo], 'START did not release both lines, pull SDA low while SCL was released, then drive SCL low'))
        elif ack is None:
            failures.append(fail(trace[lo], 'START sequence completed without cmd_ack'))
        elif trace[ack].get('held', 1) != 1:
            failures.append(fail(trace[ack], 'START cmd_ack was not a one-edge pulse'))

    # STOP: drive SDA low, release SCL, then release SDA while SCL is high.
    for start in rising('stop_sequence'):
        checked = True
        lo, hi = command_window(start, 'stop_sequence')
        i = first_index(lo, lambda r: out(r, 'sda_oen') == 0)
        j = first_index((i if i is not None else lo),
                        lambda r: out(r, 'sda_oen') == 0 and out(r, 'scl_oen') == 1)
        k = first_index((j if j is not None else lo),
                        lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1)
        ack = first_index(lo, lambda r: out(r, 'cmd_ack') == 1)
        if i is None or j is None or k is None or not (i <= j <= k):
            failures.append(fail(trace[lo], 'STOP did not drive SDA low, release SCL, then release SDA while SCL was high'))
        elif ack is None:
            failures.append(fail(trace[lo], 'STOP sequence completed without cmd_ack'))
        elif trace[ack].get('held', 1) != 1:
            failures.append(fail(trace[ack], 'STOP cmd_ack was not a one-edge pulse'))

    # WRITE: SDA ownership follows din, SCL is released for the high phase,
    # then driven low and acknowledged. An arbitration abort is exempt from
    # the completion requirement because the operation is no longer owed.
    for start in rising('write_sequence'):
        checked = True
        lo, hi = command_window(start, 'write_sequence')
        din = trace[lo].get('inputs', {}).get('din')
        expected_sda_oen = 1 if din else 0
        sda = first_index(lo, lambda r: out(r, 'sda_oen') == expected_sda_oen)
        scl_hi = first_index((sda if sda is not None else lo),
                             lambda r: out(r, 'scl_oen') == 1)
        scl_lo = first_index((scl_hi if scl_hi is not None else lo),
                             lambda r: out(r, 'scl_oen') == 0)
        lost = first_index(lo, lambda r: out(r, 'al') == 1)
        ack = first_index(lo, lambda r: out(r, 'cmd_ack') == 1)
        if sda is None or scl_hi is None or scl_lo is None or not (sda <= scl_hi <= scl_lo):
            failures.append(fail(trace[lo], 'WRITE did not set SDA from din, release SCL, then drive SCL low'))
        elif lost is not None and (ack is None or lost < ack):
            pass
        elif ack is None:
            failures.append(fail(trace[lo], 'WRITE sequence completed without cmd_ack'))
        elif trace[ack].get('held', 1) != 1:
            failures.append(fail(trace[ack], 'WRITE cmd_ack was not a one-edge pulse'))

    # READ: SDA is released, SCL is released for the read phase, then driven
    # low and completed. At a filtered SCL rising signature, dout must equal
    # the filtered SDA value visible in the declared probe.
    for start in rising('read_sequence'):
        checked = True
        lo, hi = command_window(start, 'read_sequence')
        sda = first_index(lo, lambda r: out(r, 'sda_oen') == 1)
        scl_hi = first_index((sda if sda is not None else lo),
                             lambda r: out(r, 'scl_oen') == 1)
        scl_lo = first_index((scl_hi if scl_hi is not None else lo),
                             lambda r: out(r, 'scl_oen') == 0)
        ack = first_index(lo, lambda r: out(r, 'cmd_ack') == 1)
        if sda is None or scl_hi is None or scl_lo is None or not (sda <= scl_hi <= scl_lo):
            failures.append(fail(trace[lo], 'READ did not release SDA, release SCL, then drive SCL low'))
        elif ack is None:
            failures.append(fail(trace[lo], 'READ sequence completed without cmd_ack'))
        elif trace[ack].get('held', 1) != 1:
            failures.append(fail(trace[ack], 'READ cmd_ack was not a one-edge pulse'))
        for i in range(lo, hi):
            if out(trace[i], 'filtered_scl_rising'):
                if out(trace[i], 'dout') != out(trace[i], 'ssda'):
                    failures.append(fail(trace[i], 'READ dout did not capture the filtered SDA value'))

    # Bus-busy detection is represented by filtered START and STOP condition
    # probes; only the corresponding status transition is asserted.
    for start in rising('sta_condition'):
        checked = True
        i = first_index(start, lambda r: out(r, 'busy') == 1)
        if i is None:
            failures.append(fail(trace[start], 'busy did not rise after a filtered START condition'))
    for start in rising('sto_condition'):
        checked = True
        i = first_index(start, lambda r: out(r, 'busy') == 0)
        if i is None:
            failures.append(fail(trace[start], 'busy did not clear after a filtered STOP condition'))

    # Arbitration loss is required only when the declared arbitration-check
    # phase is active and the filtered SDA line contradicts a released SDA.
    for start in rising('sda_chk', lambda r: out(r, 'sda_oen') == 1 and out(r, 'ssda') == 0):
        checked = True
        i = first_index(start, lambda r: out(r, 'al') == 1)
        if i is None:
            failures.append(fail(trace[start], 'arbitration loss was not asserted during a lost SDA arbitration'))

    if failures:
        return failures[0]
    if not checked:
        return (None, None, 'no supported command or scoped bus-condition signature occurred in this trace')
    return (True, None, 'all exercised START, STOP, WRITE, READ, busy, and arbitration output effects satisfied')

def decide(trace):
    if not trace:
        return (None, None, 'the external SCL and SDA line-control interface was not sampled')

    required = ('scl_o', 'scl_oen', 'sda_o', 'sda_oen')
    for row in trace:
        outputs = row.get('outputs', {})
        edge = row.get('edge')
        for port in required:
            if port not in outputs:
                return (False, edge, f'{port} is absent from the declared output interface')

        for drive_port in ('scl_o', 'sda_o'):
            if outputs[drive_port] != 0:
                return (
                    False,
                    edge,
                    f'{drive_port} is {outputs[drive_port]!r}; open-drain control must never drive high'
                )

        for enable_port in ('scl_oen', 'sda_oen'):
            if outputs[enable_port] not in (0, 1):
                return (
                    False,
                    edge,
                    f'{enable_port} is {outputs[enable_port]!r}; the active-low drive/release control must be 0 or 1'
                )

    return (
        True,
        None,
        'scl_o and sda_o stayed low for both active-low enable states: 0 drives low and 1 releases'
    )

def decide(trace):
    if not trace:
        return (None, None, 'the module-operating trace contains no observations')

    for row in trace:
        outputs = row.get('outputs', {})
        edge = row.get('edge')

        for port in ('scl_o', 'sda_o'):
            value = outputs.get(port)
            if value != 0:
                return (False, edge,
                        f'{port} is not constantly low; expected 0')

        for port in ('scl_oen', 'sda_oen'):
            value = outputs.get(port)
            if value not in (0, 1):
                return (False, edge,
                        f'{port} is not a valid active-low output-enable control; expected 0 or 1')

    return (True, None,
            'scl_o and sda_o are constantly 0, and scl_oen and sda_oen use active-low 0/1 control values throughout the module-operating trace')

def decide(trace):
    if not trace:
        return (None, None, 'no states to evaluate the output-enable controls')

    saw_control = False
    for row in trace:
        outputs = row.get('outputs', {})
        scl_oen = outputs.get('scl_oen')
        sda_oen = outputs.get('sda_oen')
        scl_o = outputs.get('scl_o')
        sda_o = outputs.get('sda_o')

        if scl_oen in (0, 1):
            saw_control = True
        else:
            return (False, row.get('edge'),
                    f'scl_oen has non-binary value {scl_oen!r}; expected active-low control 0 or release control 1')
        if sda_oen in (0, 1):
            saw_control = True
        else:
            return (False, row.get('edge'),
                    f'sda_oen has non-binary value {sda_oen!r}; expected active-low control 0 or release control 1')

        if scl_oen == 0 and scl_o != 0:
            return (False, row.get('edge'),
                    'scl_oen is low but the corresponding open-drain drive value scl_o is not low')
        if sda_oen == 0 and sda_o != 0:
            return (False, row.get('edge'),
                    'sda_oen is low but the corresponding open-drain drive value sda_o is not low')

    if not saw_control:
        return (None, None, 'no output-enable control state occurred')
    return (True, None,
            'active-low output-enable controls were observed; low enables constant-low drive and high represents release for the external pull-up')

def decide(trace):
    supported = {1, 2, 4, 8}
    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def in_sequence(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (inputs.get('cmd') in supported
                and any(outputs.get(p) == 1 for p in sequence_probes))

    windows = []
    i = 0
    while i < len(trace):
        if not in_sequence(trace[i]):
            i += 1
            continue
        start = i
        while i < len(trace) and in_sequence(trace[i]):
            i += 1
        windows.append((start, i))

    if not windows:
        return (None, None,
                'no supported command was observed while a declared command sequence was active')

    for start, end in windows:
        for j in range(start, end):
            outputs = trace[j].get('outputs', {})
            if outputs.get('scl_o') != 0:
                return (False, trace[j].get('edge'),
                        'scl_o must provide the constant low open-drain SCL drive value')
            if outputs.get('sda_o') != 0:
                return (False, trace[j].get('edge'),
                        'sda_o must provide the constant low open-drain SDA drive value')

        control_changed = False
        first = start
        if first > 0:
            before = trace[first - 1].get('outputs', {})
            current = trace[first].get('outputs', {})
            control_changed = (
                before.get('scl_oen') != current.get('scl_oen')
                or before.get('sda_oen') != current.get('sda_oen')
            )
        for j in range(start + 1, end):
            previous = trace[j - 1].get('outputs', {})
            current = trace[j].get('outputs', {})
            if (previous.get('scl_oen') != current.get('scl_oen')
                    or previous.get('sda_oen') != current.get('sda_oen')):
                control_changed = True
                break

        if not control_changed:
            return (False, trace[start].get('edge'),
                    'the supported command sequence produced no SCL or SDA output-enable control transition')

    return (True, None,
            'supported command sequences expose constant-low open-drain drives and output-enable control transitions')

def decide(trace):
    from specflow.refmodel.temporal import after, sequence, worst

    def out(row, port):
        return row.get('outputs', {}).get(port)

    def state(scl_oen, sda_oen):
        return lambda row: (
            out(row, 'scl_oen') == scl_oen
            and out(row, 'sda_oen') == sda_oen
        )

    def reset(row):
        return (
            row.get('inputs', {}).get('nReset') == 0
            or row.get('inputs', {}).get('rst') == 1
        )

    def windows_for(command, probe):
        return after(
            trace,
            lambda row: (
                row.get('inputs', {}).get('ena') == 1
                and row.get('inputs', {}).get('cmd') == command
                and out(row, probe) == 1
            ),
            until=lambda row: out(row, 'cmd_ack') == 1,
            aborts=reset,
        )

    verdicts = []

    for window in windows_for(1, 'start_sequence'):
        verdicts.append(sequence(
            window,
            state(1, 0),
            state(0, 0),
            strong=True,
            after_activation=True,
        ))

    for window in windows_for(2, 'stop_sequence'):
        verdicts.append(sequence(
            window,
            state(0, 0),
            state(1, 0),
            state(1, 1),
            strong=True,
            after_activation=True,
        ))

    for window in windows_for(8, 'read_sequence'):
        verdicts.append(sequence(
            window,
            state(1, 1),
            state(0, 1),
            strong=True,
            after_activation=True,
        ))

    for window in windows_for(4, 'write_sequence'):
        if window.value('din') == 0:
            released_sda = state(1, 0)
            low_scl = state(0, 0)
        else:
            released_sda = state(1, 1)
            low_scl = state(0, 1)
        verdicts.append(sequence(
            window,
            released_sda,
            low_scl,
            strong=True,
            after_activation=True,
        ))

    return worst(verdicts)

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def reset_active(row):
        return row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1

    # Find completed command transactions: a command was active and the FSM
    # subsequently returned to idle.  A return accompanied by arbitration loss
    # is an abort, not a completion.
    transactions = []
    active_start = None
    for i, row in enumerate(trace):
        if reset_active(row):
            active_start = None
            continue
        if out(row, 'fsm_active'):
            if active_start is None:
                active_start = i
        elif active_start is not None and out(row, 'idle'):
            aborted = any(out(trace[j], 'al') for j in range(active_start, i + 1))
            if not aborted:
                transactions.append((active_start, i))
            active_start = None

    if not transactions:
        return (None, None, 'no supported command completion was observed')

    for start, end in transactions:
        # Include the terminal transition and search until the next distinct
        # command activity; no fixed response latency is assumed.
        stop = len(trace)
        for j in range(end + 1, len(trace)):
            if reset_active(trace[j]) or out(trace[j], 'fsm_active'):
                stop = j
                break

        ack_rows = [
            trace[j] for j in range(end, stop)
            if out(trace[j], 'cmd_ack') == 1
        ]
        if not ack_rows:
            return (False, trace[end].get('edge'),
                    'completed command had no cmd_ack pulse')
        if len(ack_rows) != 1:
            return (False, ack_rows[0].get('edge'),
                    'command completion produced more than one cmd_ack state')
        ack = ack_rows[0]
        if ack.get('held') != 1:
            return (False, ack.get('edge'),
                    f"cmd_ack was held for {ack.get('held')} clock edges, expected exactly one")

    return (True, None, 'each observed command completion had one stable one-clock cmd_ack pulse')

def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        before = trace[i - 1].get('outputs', {})
        now = trace[i].get('outputs', {})
        if before.get('fsm_active') == 1 and now.get('idle') == 1:
            completions.append(i)

    if not completions:
        return (None, None, 'no fsm_active-to-idle command-completion state was observed')

    evidence = []
    for start in completions:
        i = start
        while i < len(trace):
            row = trace[i]
            outputs = row.get('outputs', {})
            if i != start and outputs.get('idle') != 1:
                break
            if outputs.get('cmd_ack') == 1:
                evidence.append((i, row))
                break
            i += 1

    if not evidence:
        return (None, None, 'command completion was observed, but no cmd_ack update was present to assess')

    for i, row in evidence:
        held = row.get('held', 1)
        if held != 1:
            return (False, row.get('edge'), f'cmd_ack was not confined to one rising-edge state; sampled state held for {held} edges')

    return (True, evidence[0][1].get('edge'), 'cmd_ack assertion was stable for exactly one sampled rising-edge state after command completion')

def decide(trace):
    reset_rows = [
        row for row in trace
        if row.get('inputs', {}).get('rst') == 1
    ]
    if not reset_rows:
        return (None, None, 'rst was never asserted high in this trace')

    for row in reset_rows:
        outputs = row.get('outputs', {})
        if outputs.get('busy') != 0 or outputs.get('al') != 0:
            bad = []
            if outputs.get('busy') != 0:
                bad.append('busy is not reset low')
            if outputs.get('al') != 0:
                bad.append('al is not reset low')
            return (False, row.get('edge'), 'synchronous reset requires ' + ' and '.join(bad) + ' when rst is high')

    return (True, reset_rows[0].get('edge'), 'busy and al are reset low while rst is high')

from specflow.refmodel.temporal import after, edges, throughout, worst


def decide(trace):
    falling = edges(trace, 'nReset', 'fall')

    def reset_activation(row):
        initial_reset = row.get('index') == 0 and row['inputs'].get('nReset') == 0
        asserted_edge = row.get('edge') in falling and row['inputs'].get('nReset') == 0
        return initial_reset or asserted_edge

    def reset_released(row):
        return row['inputs'].get('nReset') != 0

    windows = after(trace, reset_activation, until=reset_released)
    verdicts = [
        throughout(
            window,
            lambda row: row['outputs'].get('scl_oen') == 1,
            after_activation=False,
        )
        for window in windows
    ]
    return worst(verdicts)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def active(row):
        return (out(row, 'fsm_active') == 1 and
                row.get('inputs', {}).get('nReset') == 1 and
                row.get('inputs', {}).get('rst') == 0)

    starts = []
    for i, row in enumerate(trace):
        if not active(row):
            continue
        if i == 0 or not active(trace[i - 1]):
            starts.append(i)

    if not starts:
        return (None, None, 'the declared fsm_active state never occurred')

    for start in starts:
        ena = trace[start].get('inputs', {}).get('ena')
        end = None
        for j in range(start + 1, len(trace)):
            if out(trace[j], 'idle') == 1:
                end = j
                break
            if (trace[j].get('inputs', {}).get('nReset') != 1 or
                    trace[j].get('inputs', {}).get('rst') == 1):
                end = None
                break

        if end is None:
            return (None, trace[start].get('edge'),
                    'the active command did not reach a completed idle state in the trace')

        rows = trace[start:end + 1]
        ack_rows = []
        for k, row in enumerate(rows):
            previous = 0 if k == 0 else out(rows[k - 1], 'cmd_ack')
            if out(row, 'cmd_ack') == 1 and previous != 1:
                ack_rows.append((start + k, row))

        if ena == 1:
            if len(ack_rows) != 1:
                return (False, trace[end].get('edge'),
                        'with ena high, the active command completed without exactly one cmd_ack pulse')
            ack_i, ack_row = ack_rows[0]
            if ack_row.get('held') != 1:
                return (False, ack_row.get('edge'),
                        'with ena high, cmd_ack was not high for exactly one clock')
        elif ena == 0 and ack_rows:
            return (False, ack_rows[0][1].get('edge'),
                    'with ena low, cmd_ack pulsed during the active observation window')

    return (True, None, 'the active command observation matched the ena-qualified cmd_ack route')

def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    verdicts = []
    cmd_activation = False
    cmd_completion_seen = False

    i = 0
    while i < len(trace):
        row = trace[i]
        if (inp(row, 'ena') == 0
                and out(row, 'fsm_active', 0) == 1):
            cmd_activation = True
            j = i
            while j < len(trace):
                r = trace[j]
                if inp(r, 'rst', 0) == 1 or inp(r, 'nReset', 1) == 0:
                    break
                if inp(r, 'ena') != 0 or out(r, 'fsm_active', 0) != 1:
                    break
                if out(r, 'cmd_ack', 0) == 1:
                    verdicts.append(
                        (False, r.get('edge'),
                         'cmd_ack pulsed while ena was low during an accepted command'))
                    break
                j += 1

            if not any(v[0] is False for v in verdicts):
                k = j
                while k < len(trace):
                    r = trace[k]
                    if inp(r, 'rst', 0) == 1 or inp(r, 'nReset', 1) == 0:
                        break
                    if out(r, 'al', 0) == 1:
                        break
                    if inp(r, 'ena') == 0:
                        k += 1
                        continue
                    if out(r, 'cmd_ack', 0) == 1:
                        cmd_completion_seen = True
                        verdicts.append(
                            (True, r.get('edge'),
                             'cmd_ack remained suppressed while ena was low and completed after ena was re-enabled'))
                        break
                    k += 1
            i = max(j, i + 1)
        else:
            i += 1

    busy_activation = False
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if (inp(prev, 'sda_i') == 1 and inp(row, 'sda_i') == 0
                and inp(row, 'ena') == 0
                and out(row, 'sscl', 0) == 1
                and out(prev, 'busy', 0) == 0
                and out(row, 'busy', 0) == 0):
            busy_activation = True
            j = i
            while j < len(trace):
                r = trace[j]
