    def value(row, port):
        if port in row.get('outputs', {}):
            return row['outputs'][port]
        return row.get('inputs', {}).get(port)

    def holds(conditions):
        return lambda row: all(value(row, port) == expected
                               for port, expected in conditions.items())

    starts = after(
        trace,
        holds({'sta_condition': 1}),
        until=holds({'sto_condition': 1}),
        aborts=lambda row: value(row, 'nReset') == 0 or value(row, 'rst') == 1
    )

    verdicts = []
    for window in starts:
        start_pos = next(
            (i for i, row in enumerate(trace) if row.get('edge') == window.edge),
            None
        )
        if start_pos is None:
            verdicts.append((None, window.edge, 'START activation could not be located'))
            continue

        stop_pos = next(
            (i for i in range(start_pos + 1, len(trace))
             if value(trace[i], 'sto_condition') == 1),
            None
        )

        # A STOP closes the transaction.  If no STOP was observed, the
        # transaction is incomplete and its later evidence is unknown.
        end_pos = stop_pos if stop_pos is not None else len(trace)
        high_pos = next(
            (i for i in range(start_pos + 1, end_pos + 1)
             if value(trace[i], 'busy') == 1),
            None
        )

        if high_pos is None:
            if stop_pos is None:
                verdicts.append((None, window.edge,
                                 'busy was not observed high before the incomplete START transaction ended'))
            else:
                verdicts.append((False, trace[stop_pos]['edge'],
                                 'busy did not become high after START before STOP was detected'))
            continue

        dropped_before_stop = next(
            (i for i in range(high_pos + 1, end_pos)
             if value(trace[i], 'busy') != 1),
            None
        )
        if dropped_before_stop is not None:
            verdicts.append((False, trace[dropped_before_stop]['edge'],
                             'busy cleared before the STOP condition was detected'))
            continue

        if stop_pos is None:
            verdicts.append((None, trace[high_pos]['edge'],
                             'busy became high, but no STOP condition completed the transaction'))
            continue

        low_pos = next(
            (i for i in range(stop_pos + 1, len(trace))
             if value(trace[i], 'busy') == 0),
            None
        )
        if low_pos is None:
            verdicts.append((False, trace[stop_pos]['edge'],
                             'busy did not clear after the STOP condition was detected'))
        else:
            verdicts.append((True, trace[low_pos]['edge'],
                             'busy became high after START, remained set through STOP, and cleared afterward'))

    return worst(verdicts)

