    # high. Reconstruct the three-sample histories in trace order.
    if not any(row.get('outputs', {}).get('sscl') == 1 for row in trace):
        return (None, None, 'sscl never reached the filtering state')

    hist_scl = [1, 1, 1]
    hist_sda = [1, 1, 1]
