    for in_port, filt_port, line in checks:
        for i in range(1, len(trace)):
            before = trace[i - 1]
            start = trace[i]

            # A change in the input opens a candidate glitch window.
            if start["inputs"].get(in_port) == before["inputs"].get(in_port):
                continue
            if start["inputs"].get(in_port) is None:
                continue

            # Do not decide across reset, and require that the filtered value
            # was not already changing when the candidate began.
            if before["inputs"].get("nReset") == 0 or before["inputs"].get("rst") == 1:
                continue
            if start["inputs"].get("nReset") == 0 or start["inputs"].get("rst") == 1:
                continue
            if start["outputs"].get(filt_port) != before["outputs"].get(filt_port):
                continue

            original = before["inputs"][in_port]
            filtered_value = start["outputs"].get(filt_port)
            returned = False
            aborted = False

            for j in range(i + 1, len(trace)):
                row = trace[j]
                if row["inputs"].get("nReset") == 0 or row["inputs"].get("rst") == 1:
                    aborted = True
                    break

                if row["outputs"].get(filt_port) != filtered_value:
                    return (False, row["edge"],
                            f"{line} short glitch changed filtered {filt_port}; "
                            "the obligation says short glitches reduce their effect")

                if row["inputs"].get(in_port) == original:
                    returned = True
                    exercised.append((start["edge"], line))
                    break

            if aborted or not returned:
                continue

    if not exercised:
        return (None, None,
                "no complete short-glitch excursion was exercised before reset or trace end")
    return (True, exercised[0][0],
            "short input glitch excursions returned without changing their filtered signal")

