    # declared situation, not an inferred internal signal.
    starts = []
    for i, row in enumerate(trace):
        active = out(row, 'write_sequence') == 1 and inp(row, 'ena') == 1
        prior = (i > 0 and out(trace[i - 1], 'write_sequence') == 1 and
                 inp(trace[i - 1], 'ena') == 1)
        if active and not prior and not invalid(row):
            starts.append(i)

    if not starts:
        return (None, None, 'no enabled, non-aborted WRITE timing transaction occurred')

    for start in starts:
        high_transition = None
        low_transition = None
        aborted = False

        for i in range(start, len(trace)):
            row = trace[i]
            if invalid(row):
                aborted = True
                break

            if i == start:
                continue
            previous = trace[i - 1]
            old = out(previous, 'scl_oen')
            new = out(row, 'scl_oen')

            if high_transition is None and old != 1 and new == 1:
                high_transition = i
                timing_seen = (out(row, 'clk_en') == 1 or
                                out(previous, 'clk_en') == 1)
                if not timing_seen:
                    return (False, row.get('edge'),
                            'scl_oen entered the WRITE released-SCL phase without a corresponding clk_en timing event')

            elif high_transition is not None and old == 1 and new != 1:
                low_transition = i
                timing_seen = (out(row, 'clk_en') == 1 or
                                out(previous, 'clk_en') == 1)
                if not timing_seen:
                    return (False, row.get('edge'),
                            'scl_oen returned to the WRITE SCL-low phase without a corresponding clk_en timing event')
                break

        if not aborted and high_transition is not None and low_transition is not None:
            return (True, None,
                    'WRITE SCL phase boundaries were reached only with declared clk_en timing, consistent with bit-level timing generated by cnt')

    return (None, None,
