        name = commands[cmd]
        start_scl = value(trace[start], 'scl_oen')

        if cmd == 0:
            # Keep this check within the idle/no-op extent.  A later command
            # or scenario must not be attributed to the no-op activation.
            previous = start_scl
            for j in range(start + 1, len(trace)):
                row = trace[j]
                if value(row, 'idle') != 1 or value(row, 'cmd') != 0:
                    break
                current = value(row, 'scl_oen')
                if previous != 0 and current == 0:
                    return (False, row.get('edge'),
                            'cmd=0 was decoded as no operation, but scl_oen began a command sequence')
                previous = current
            continue

