    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_of(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # Use the declared STOP-sequence probe as the command signature.  The
    # numeric cmd encoding is not authoritative in the contract.
    opens = lambda row: (
        row['outputs'].get('stop_sequence') == 1
        and row['inputs'].get('ena') == 1
    )
    closes = any_of([{'cmd_ack': 1}])
    aborts = any_of([{'nReset': 0}, {'rst': 1}])

    windows = after(trace, opens, until=closes, aborts=aborts)
    results = []
    release_edges = {
        row['edge'] for index, row in enumerate(trace)
        if index > 0
        and trace[index - 1]['outputs'].get('scl_oen') != 1
        and row['outputs'].get('scl_oen') == 1
    }

    for window in windows:
        if getattr(window, 'aborted', False):
            results.append((None, None, 'STOP sequence was aborted by reset'))
            continue

        # effect_follows is true: evaluate after the activation state.
        rows = window.rows[1:]
        if not rows:
            results.append((None, window.edge, 'STOP sequence has no post-activation state'))
            continue

        low_indices = [
            index for index, row in enumerate(rows)
            if row['outputs'].get('sda_oen') == 0
        ]
        release_indices = [
            index for index, row in enumerate(rows)
            if row['edge'] in release_edges
        ]

        first_low = low_indices[0] if low_indices else None
        first_release = release_indices[0] if release_indices else None

        if first_release is not None and (first_low is None or first_release <= first_low):
            row = rows[first_release]
            results.append((
                False,
                row['edge'],
                'SCL was released before SDA was driven low; required order is '
                '"first ensures SDA is low, then releases SCL high"'
            ))
        elif first_low is not None and first_release is not None:
            row = rows[first_release]
            results.append((
                True,
                row['edge'],
                'SDA was driven low before SCL was released high'
            ))
        elif getattr(window, 'closed', False):
            results.append((
                False,
                rows[-1]['edge'],
                'STOP completed without the required ordered SDA-low then SCL-release sequence'
            ))
        else:
            results.append((
                None,
                rows[-1]['edge'],
                'STOP sequence window ended before the required ordering could be decided'
            ))

    return worst(results)

