    # A STOP completion is the SDA-release transition while SCL is already
    # released, immediately following the declared STOP sequence.
    completions = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        if (prev['outputs'].get('sda_oen') != 1
                and row['outputs'].get('sda_oen') == 1
                and row['outputs'].get('scl_oen') == 1
                and prev['outputs'].get('stop_sequence') == 1
                and row['inputs'].get('ena') == 1):
            completions.append(i)

    if not completions:
        return (None, None, 'STOP completion was not exercised in this trace')

    for i in completions:
        row = trace[i]
        edge = row['edge']

        if row['outputs'].get('idle') != 1:
            return (False, edge, 'FSM did not return to idle after STOP completion')

        if row['outputs'].get('cmd_ack') != 1:
            return (False, edge, 'cmd_ack was not high at STOP completion')

        if i > 0 and trace[i - 1]['outputs'].get('cmd_ack') == 1:
            return (False, edge, 'cmd_ack was already high before STOP completion')

        remaining = row['held']
        j = i + 1
        while j < len(trace) and trace[j]['outputs'].get('cmd_ack') == 1:
            remaining += trace[j]['held']
            j += 1
        if remaining != 1:
            return (False, edge, f'cmd_ack pulse lasted {remaining} edges, expected exactly 1')

    return (True, None, f'{len(completions)} STOP completion(s) returned idle and pulsed cmd_ack')

