def decide(trace):
    from specflow.refmodel.temporal import after, sequence, worst

    def any_condition(alternatives):
        def predicate(row):
            for condition in alternatives:
                if all(
                    row.get('outputs', {}).get(port,
                        row.get('inputs', {}).get(port)) == value
                    for port, value in condition.items()
                ):
                    return True
            return False
        return predicate

    activation = any_condition([
        {'cmd': 1, 'ena': 1},
        {'cmd': 2, 'ena': 1},
        {'cmd': 4, 'ena': 1},
        {'cmd': 8, 'ena': 1},
    ])
    closes = any_condition([{'cmd_ack': 1}])
    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(trace, activation, until=closes, aborts=aborts)
    verdicts = []

    for window in windows:
        command = window.value('cmd')
        din = window.value('din')

        def state(**values):
            return lambda row: all(
                row.get('outputs', {}).get(port) == value
                for port, value in values.items()
            )

        if command == 1:  # START: release both, drive SDA low, then drive SCL low
            phases = [
                state(scl_oen=1, sda_oen=1),
                state(scl_oen=1, sda_oen=0),
                state(scl_oen=0, sda_oen=0),
            ]
            description = 'START control sequence: release both lines, drive SDA low, then drive SCL low'
        elif command == 2:  # STOP: drive both low, release SCL, then release SDA
            phases = [
                state(scl_oen=0, sda_oen=0),
                state(scl_oen=1, sda_oen=0),
                state(scl_oen=1, sda_oen=1),
            ]
            description = 'STOP control sequence: drive both lines low, release SCL, then release SDA'
        elif command == 4:  # WRITE: set SDA from din, release SCL, then drive SCL low
            phases = [
                state(scl_oen=1, sda_oen=din),
                state(scl_oen=0, sda_oen=din),
            ]
            description = 'WRITE control sequence: set SDA from din, release SCL, then drive SCL low'
        elif command == 8:  # READ: release SDA and SCL, then drive SCL low
            phases = [
                state(scl_oen=1, sda_oen=1),
                state(scl_oen=0, sda_oen=1),
            ]
            description = 'READ control sequence: release SDA and SCL, then drive SCL low'
        else:
            continue

        verdicts.append(sequence(
            window,
            *phases,
            strong=True,
            after_activation=True,
        ))

    return worst(verdicts)

