            now = bool(value(row, name))
            if now and not previous:
                result.append(i)
            previous = now
        return result

    def changed_into(name, target, start, stop=None):
        end = len(trace) if stop is None else stop
        for i in range(max(1, start + 1), end):
            before = value(trace[i - 1], name)
            now = value(trace[i], name)
            if before != target and now == target:
                return i
        return None

    def first_after(predicate, start, stop=None):
        end = len(trace) if stop is None else stop
        for i in range(start, end):
