    def reset_row(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    def transaction_end(start, probe):
        for i in range(start + 1, len(trace)):
            if reset_row(trace[i]):
                return i, 'reset'
            if value(trace[i], 'al') == 1 and probe != 'stop_sequence':
                return i, 'arbitration loss'
            if not value(trace[i], probe):
                return i, 'sequence ended'
        return len(trace), 'trace ended'

