                failures.append((False, trace[start].get('edge'), text))

    # A READ capture is checked after the filtered SCL rising-edge signature;
    # no exact response edge is imposed.
    for start in rising_rows('read_sequence'):
        end, why = transaction_end(start, 'read_sequence')
        if why in ('reset', 'arbitration loss'):
            continue
        for i in range(start, end):
            if value(trace[i], 'filtered_scl_rising'):
                exercised = True
                sampled = value(trace[i], 'ssda')
                captured = first_after(lambda r: value(r, 'dout') == sampled,
                                       i + 1, end)
                if captured is None and end != len(trace):
                    failures.append((False, trace[i].get('edge'),
                                     'READ did not expose the filtered SDA value on dout after the filtered SCL rising event'))

    if failures:
        return failures[0]
    if not exercised:
        return (None, None, 'no supported command sequence or scoped filtered bus condition occurred')
    return (True, None, 'all exercised supported command and bus-condition effects satisfied')

def decide(trace):
    def out(row, port):
        return row.get('outputs', {}).get(port)

    def reset(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    def rises(probe):
        result = []
        for i in range(1, len(trace)):
            if (not reset(trace[i - 1]) and not reset(trace[i]) and
                    out(trace[i - 1], probe) != 1 and
                    out(trace[i], probe) == 1):
                result.append(i)
        return result

    def sequence_end(start, probe):
        for i in range(start + 1, len(trace)):
            if reset(trace[i]):
                return i, 'reset'
            if probe != 'stop_sequence' and out(trace[i], 'al') == 1:
                return i, 'arbitration loss'
            if out(trace[i], probe) != 1:
                return i, 'sequence ended'
        return len(trace), 'trace ended'

    def first_level(start, end, port, value):
        for i in range(start, end):
            if out(trace[i], port) == value:
                return i
        return None

    failures = []
    exercised = False

    for probe in ('start_sequence', 'stop_sequence', 'write_sequence', 'read_sequence'):
        for start in rises(probe):
            exercised = True
            end, why = sequence_end(start, probe)

            if probe == 'start_sequence':
                # Generating START requires the controller to drive SDA low.
                target = 0
                description = 'START sequence never drove SDA low'
            elif probe == 'stop_sequence':
                # Generating STOP requires the controller to release SDA.
                target = 1
                description = 'STOP sequence never released SDA'
            elif probe == 'read_sequence':
                # READ requires SDA to be released for the external device.
                target = 1
                description = 'READ sequence never released SDA'
            else:
                # A WRITE drives SDA for din=0 and releases it for din=1.
                din = trace[start].get('inputs', {}).get('din')
                target = 1 if din else 0
                description = ('WRITE sequence did not set SDA ownership for '
                               + ('din=1' if din else 'din=0'))

            if first_level(start, end, 'sda_oen', target) is not None:
                continue

            if why in ('reset', 'arbitration loss', 'trace ended'):
                continue
            failures.append((False, trace[start].get('edge'), description))

    if failures:
        return failures[0]
    if not exercised:
        return (None, None, 'no START, STOP, WRITE, or READ sequence occurred')
    return (True, None, 'all exercised command sequences reached their required SDA ownership state')

def decide(trace):
    def value(row, port):
        return row.get('outputs', {}).get(port)

    def reset(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    sequence_probes = ('start_sequence', 'stop_sequence',
                       'write_sequence', 'read_sequence')

    def active(row, probe):
        return value(row, probe) == 1

    def starts(probe):
        result = []
        for i, row in enumerate(trace):
            if reset(row) or not active(row, probe):
                continue
            previous_active = i > 0 and active(trace[i - 1], probe)
            if not previous_active:
                result.append(i)
        return result

    def next_sequence_start(start):
        later = []
        for probe in sequence_probes:
            later.extend(i for i in starts(probe) if i > start)
        return min(later) if later else len(trace)

    failures = []
    exercised = False

    for probe in sequence_probes:
        for start in starts(probe):
            exercised = True
            end = len(trace)
            aborted = False
            normal_end = False

            for i in range(start + 1, len(trace)):
                row = trace[i]
                if reset(row):
                    end = i
                    aborted = True
                    break
                if probe != 'stop_sequence' and value(row, 'al') == 1:
                    end = i
                    aborted = True
                    break
                if not active(row, probe):
                    end = i
                    normal_end = True
                    break

            boundary = min(end, next_sequence_start(start))
            ack_rows = [i for i in range(start, boundary)
                        if value(trace[i], 'cmd_ack') == 1]

            if not aborted:
                if len(ack_rows) == 0:
                    if normal_end:
                        failures.append((False, trace[end].get('edge'),
                                         probe + ' completed without the required one-clock cmd_ack pulse'))
                    # An active operation that reaches the trace boundary is
                    # incomplete evidence, not a design failure.
                else:
                    ack = ack_rows[0]
                    if trace[ack].get('held') != 1:
                        failures.append((False, trace[ack].get('edge'),
                                         probe + ' produced cmd_ack for '
                                         + str(trace[ack].get('held'))
                                         + ' edges; the command-complete pulse must be one clock'))
                    elif len(ack_rows) != 1:
                        failures.append((False, trace[ack].get('edge'),
                                         probe + ' produced more than one cmd_ack pulse'))

            if aborted:
                continue

            target = None
            description = ''
            if probe == 'start_sequence':
                target = 0
                description = 'START sequence never drove SDA low'
            elif probe == 'stop_sequence':
                target = 1
                description = 'STOP sequence never released SDA'
            elif probe == 'read_sequence':
                target = 1
                description = 'READ sequence never released SDA'
            else:
                din = trace[start].get('inputs', {}).get('din')
                target = 1 if din == 1 else 0
                description = ('WRITE sequence did not set SDA ownership for '
                               + ('din=1' if din == 1 else 'din=0'))

            target_rows = [i for i in range(start, end)
                           if value(trace[i], 'sda_oen') == target]
            if not target_rows:
                if normal_end:
                    failures.append((False, trace[end].get('edge'), description))
                # If the sequence is still active at trace end, the required
                # later phase was not observed and remains undecided.

    if failures:
        return failures[0]
    if not exercised:
        return (None, None,
                'no START, STOP, WRITE, or READ command sequence occurred')
    return (True, None,
            'all observed command sequences produced their required SDA operation and one-clock cmd_ack completion')

