def decide(trace):
    supported = {1, 2, 4, 8}

    def active(row):
        return (row.get('inputs', {}).get('cmd') in supported
                and row.get('inputs', {}).get('ena') == 1
                and row.get('inputs', {}).get('nReset') == 1
                and row.get('inputs', {}).get('rst') == 0)

    windows = []
    i = 0
    while i < len(trace):
        if not active(trace[i]) or (i > 0 and active(trace[i - 1])):
            i += 1
            continue
        start = i
        i += 1
        while i < len(trace) and active(trace[i]):
            i += 1
        windows.append(trace[start:i])

    if not windows:
        return (None, None, 'no enabled, out-of-reset supported command occurred')

    for rows in windows:
        for row in rows:
            outputs = row.get('outputs', {})
            if outputs.get('scl_o') != 0:
                return (False, row.get('edge'), 'scl_o must remain the constant low open-drain drive value')
            if outputs.get('sda_o') != 0:
                return (False, row.get('edge'), 'sda_o must remain the constant low open-drain drive value')

        enable_changed = any(
            rows[j].get('outputs', {}).get('scl_oen') != rows[j - 1].get('outputs', {}).get('scl_oen')
            or rows[j].get('outputs', {}).get('sda_oen') != rows[j - 1].get('outputs', {}).get('sda_oen')
            for j in range(1, len(rows))
        )
        if not enable_changed:
            return (False, rows[0].get('edge'), 'supported command produced no SCL or SDA output-enable control activity')

    return (True, None, 'supported command windows expose constant-low open-drain drives and output-enable control activity')

