def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, edges, eventually, throughout, worst

    sequences = ("start_sequence", "stop_sequence", "read_sequence", "write_sequence")
    verdicts = []

    scl_oen_changes = edges(trace, "scl_oen", "change")
    sda_oen_changes = edges(trace, "sda_oen", "change")
    oen_changes = scl_oen_changes | sda_oen_changes

    for seq in sequences:
        windows = after(
            trace,
            lambda r, seq=seq: r["outputs"].get(seq) == 1,
            until=lambda r, seq=seq: r["outputs"].get(seq) != 1,
        )
        for w in windows:
            verdicts.append(
                throughout(
                    w,
                    lambda r: r["outputs"].get("scl_o") == 0
                    and r["outputs"].get("sda_o") == 0,
                )
            )
            verdicts.append(
                eventually(
                    w,
                    lambda r: r["edge"] in oen_changes,
                    strong=True,
                )
            )

    return worst(verdicts)

