def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def first_at_or_after(rows, start, predicate):
        for j in range(start, len(rows)):
            if predicate(rows[j]):
                return j
        return None

    def attempt(probe, kind, start):
        end = None
        for j in range(start, len(trace)):
            if trace[j].get('inputs', {}).get('nReset') == 0 or trace[j].get('inputs', {}).get('rst') == 1:
                return (None, None, 'the command attempt was aborted by reset')
            if out(trace[j], 'cmd_ack') == 1:
                end = j
                break
        if end is None:
            return (None, None, 'command sequence did not reach completion in this trace')

        rows = trace[start:end + 1]
        def find(pos, predicate):
            for k in range(pos, len(rows)):
                if predicate(rows[k]):
                    return k
            return None

        def fail(message, pos=0):
            edge = rows[min(pos, len(rows) - 1)].get('edge') if rows else None
            return (False, edge, message)

        if kind == 'START':
            sda_low = find(0, lambda r: out(r, 'sda_oen') == 0)
            if sda_low is None:
                return fail('START bit-level generation never drove sda_oen low')
            scl_low = find(sda_low, lambda r: out(r, 'scl_oen') == 0)
            if scl_low is None:
                return fail('START bit-level generation did not drive scl_oen low', sda_low)
        elif kind == 'STOP':
            sda_low = find(0, lambda r: out(r, 'sda_oen') == 0)
            if sda_low is None:
                return fail('STOP bit-level generation never drove sda_oen low')
            scl_released = find(sda_low, lambda r: out(r, 'scl_oen') == 1)
            if scl_released is None:
                return fail('STOP bit-level generation did not release scl_oen', sda_low)
            sda_released = find(scl_released, lambda r: out(r, 'sda_oen') == 1)
            if sda_released is None:
                return fail('STOP bit-level generation did not release sda_oen while SCL was released', scl_released)
        elif kind == 'READ':
            sda_released = find(0, lambda r: out(r, 'sda_oen') == 1)
            if sda_released is None:
                return fail('READ bit-level generation did not release sda_oen')
            scl_released = find(sda_released, lambda r: out(r, 'scl_oen') == 1)
            if scl_released is None:
                return fail('READ bit-level generation did not release scl_oen', sda_released)
            scl_low = find(scl_released, lambda r: out(r, 'scl_oen') == 0)
            if scl_low is None:
                return fail('READ bit-level generation did not drive scl_oen low after the read window', scl_released)
        elif kind == 'WRITE':
            din = trace[start].get('inputs', {}).get('din')
            expected_sda = 0 if din == 0 else 1
            sda_phase = find(0, lambda r: out(r, 'sda_oen') == expected_sda)
            if sda_phase is None:
                return fail('WRITE bit-level generation did not set sda_oen according to din')
            scl_released = find(sda_phase, lambda r: out(r, 'scl_oen') == 1)
            if scl_released is None:
                return fail('WRITE bit-level generation did not release scl_oen', sda_phase)
            scl_low = find(scl_released, lambda r: out(r, 'scl_oen') == 0)
            if scl_low is None:
                return fail('WRITE bit-level generation did not drive scl_oen low after the high phase', scl_released)
        return (True, rows[-1].get('edge'), kind + ' bit-level output-enable sequence completed')

    probes = [
        ('start_sequence', 'START'),
        ('stop_sequence', 'STOP'),
        ('read_sequence', 'READ'),
        ('write_sequence', 'WRITE')
    ]
    verdicts = []
    for probe, kind in probes:
        for i, row in enumerate(trace):
            active = out(row, probe) == 1
            previous = out(trace[i - 1], probe) == 1 if i else False
            if active and not previous and row.get('inputs', {}).get('ena') == 1:
                verdicts.append(attempt(probe, kind, i))

    if not verdicts:
        return (None, None, 'no supported command bit-level sequence occurred in this trace')
    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    if any(verdict[0] is True for verdict in verdicts):
        return (True, None, 'declared scl_oen and sda_oen performed the observed command bit-level signal generation')
    return (None, None, 'supported command sequence was not observed through completion')

def decide(trace):
    sequence_ports = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')
    windows = []
    for i, row in enumerate(trace):
        outputs = row.get('outputs', {})
        if not any(outputs.get(p) == 1 for p in sequence_ports):
            continue
        previous = trace[i - 1].get('outputs', {}) if i else {}
        was_active = any(previous.get(p) == 1 for p in sequence_ports)
        if was_active:
            continue
        end = None
        aborted = False
        for j in range(i, len(trace)):
            current = trace[j].get('outputs', {})
            if current.get('nReset', 1) == 0 or current.get('rst', 0) == 1:
                aborted = True
                break
            if current.get('cmd_ack') == 1:
                end = j
                break
        windows.append((i, end, aborted))

    if not windows:
        return (None, None, 'no START, STOP, READ, or WRITE bit-level sequence occurred')

    for start, end, aborted in windows:
        if aborted or end is None:
            continue
        changed = False
        change_edge = None
        for j in range(start, end + 1):
            current = trace[j].get('outputs', {})
            before = trace[j - 1].get('outputs', {}) if j else {}
            if (current.get('scl_oen') != before.get('scl_oen') or
                    current.get('sda_oen') != before.get('sda_oen')):
                changed = True
                change_edge = trace[j].get('edge')
                break
        if not changed:
            return (False, trace[start].get('edge'),
                    'the completed bit-level command produced no change on declared outputs '
                    'scl_oen or sda_oen')

    completed = [w for w in windows if w[1] is not None and not w[2]]
    if not completed:
        return (None, None, 'bit-level sequence began but no non-aborted completion was observed')
    return (True, completed[0][1] and trace[completed[0][1]].get('edge'),
            'completed bit-level command sequence showed output generation on scl_oen or sda_oen')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def reset_active(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    def command_probe(cmd, probe):
        def predicate(row):
            return (
                row['inputs'].get('ena') == 1
                and row['inputs'].get('cmd') == cmd
                and row['outputs'].get(probe) == 1
            )
        return predicate

    def command_windows(cmd, probe):
