            strong=True,
            after_activation=True,
        ))

    for w in command_windows(4, 'write_sequence'):
        expected_sda_oen = 1 if w.value('din') == 1 else 0
        verdicts.append(eventually(
            w,
            lambda r, expected=expected_sda_oen: (
                r['outputs'].get('sda_oen') == expected
            ),
