    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def holds(row, conditions):
        for port, value in conditions.items():
            values = row.get('outputs', {})
            if port not in values:
                values = row.get('inputs', {})
            if values.get(port) != value:
                return False
        return True

    def reset_or_abort(row):
        return (
            row.get('inputs', {}).get('nReset') == 0
            or row.get('inputs', {}).get('rst') == 1
            or row.get('outputs', {}).get('al') == 1
        )

    command_cases = [
        (1, 'start_sequence', {'sda_oen': 0}, 'START drives SDA low'),
        (2, 'stop_sequence', {'sda_oen': 0}, 'STOP drives SDA low'),
        (8, 'read_sequence', {'scl_oen': 0}, 'READ drives SCL low'),
        (4, 'write_sequence', {'scl_oen': 0}, 'WRITE drives SCL low'),
    ]

    verdicts = []
    for command, sequence_probe, expected, description in command_cases:
        def applies(row, command=command, sequence_probe=sequence_probe):
            return (
                row.get('inputs', {}).get('ena') == 1
                and row.get('inputs', {}).get('cmd') == command
                and row.get('outputs', {}).get(sequence_probe) == 1
            )

        windows = after(
            trace,
            applies,
            until=lambda row: row.get('outputs', {}).get('cmd_ack') == 1,
            aborts=reset_or_abort,
        )

        verdicts.extend(
            eventually(
                window,
                lambda row, expected=expected: holds(row, expected),
                strong=False,
                after_activation=True,
            )
            for window in windows
        )

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, sequence, worst

    def out(row, port):
        return row.get('outputs', {}).get(port)

    def state(scl_oen, sda_oen):
        return lambda row: (
            out(row, 'scl_oen') == scl_oen
            and out(row, 'sda_oen') == sda_oen
        )

    def reset(row):
        return (
            row.get('inputs', {}).get('nReset') == 0
            or row.get('inputs', {}).get('rst') == 1
        )

    def windows_for(command, probe):
        return after(
            trace,
            lambda row: (
                row.get('inputs', {}).get('ena') == 1
                and row.get('inputs', {}).get('cmd') == command
                and out(row, probe) == 1
            ),
            until=lambda row: out(row, 'cmd_ack') == 1,
            aborts=reset,
        )

    verdicts = []

    for window in windows_for(1, 'start_sequence'):
        verdicts.append(sequence(
            window,
            state(1, 0),
            state(0, 0),
            strong=True,
            after_activation=True,
        ))

    for window in windows_for(2, 'stop_sequence'):
        verdicts.append(sequence(
            window,
            state(0, 0),
            state(1, 0),
            state(1, 1),
            strong=True,
            after_activation=True,
        ))

    for window in windows_for(8, 'read_sequence'):
        verdicts.append(sequence(
            window,
            state(1, 1),
            state(0, 1),
            strong=True,
            after_activation=True,
        ))

    for window in windows_for(4, 'write_sequence'):
        if window.value('din') == 0:
            released_sda = state(1, 0)
            low_scl = state(0, 0)
        else:
            released_sda = state(1, 1)
            low_scl = state(0, 1)
        verdicts.append(sequence(
            window,
            released_sda,
            low_scl,
            strong=True,
            after_activation=True,
        ))

    return worst(verdicts)

