                verdicts.append(
                    (True, row.get('edge'),
                     'busy did not set for the SDA transition while ena was low and filtered SCL was high'))

    if any(v[0] is False for v in verdicts):
        return next(v for v in verdicts if v[0] is False)
    if verdicts:
        return verdicts[0]
    if cmd_activation or busy_activation:
        return (None, None,
                'ena-low gating situation occurred, but no complete observation window was available')
    return (None, None, 'ena-low timing/filter gating situation never occurred')

