    seqs = ("start_sequence", "stop_sequence", "read_sequence", "write_sequence")

    def out(row, name, default=0):
        return row.get("outputs", {}).get(name, default)

    def active_sequence(row):
        return any(out(row, name) == 1 for name in seqs)

    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if not active_sequence(prev) or active_sequence(row):
            continue
        if out(row, "idle") != 1:
            continue
        if prev.get("inputs", {}).get("ena") != 1:
            continue

        aborted = False
        j = i
        while j < len(trace):
            if out(trace[j], "al") == 1:
                aborted = True
                break
            if j > i and active_sequence(trace[j]):
                break
            if out(trace[j], "cmd_ack") == 1:
                completions.append((i, j))
                break
            j += 1
        if aborted:
            continue
        if j >= len(trace) or (j < len(trace) and out(trace[j], "cmd_ack") != 1):
            return (False, row.get("edge"),
                    "accepted supported command sequence completed without the routed cmd_ack pulse")

    if not completions:
        return (None, None, "no non-aborted supported command completion occurred in this trace")

    for start, ack in completions:
        held = trace[ack].get("held", 1)
        if held != 1:
            return (False, trace[ack].get("edge"),
                    f"cmd_ack was high for {held} clock edges; the routed command-complete indication must be one clock cycle")

