def decide(trace):
    candidates = []

    for i, row in enumerate(trace):
        out = row.get('outputs', {})
        if out.get('start_sequence') != 1:
            continue
        if i == 0 or trace[i - 1].get('outputs', {}).get('start_sequence') == 1:
            continue

        # The START sequence must follow an enabled acceptance opportunity
        # while the FSM was idle.  No numeric cmd encoding is assumed.
        accepted = False
        for k in range(i):
            prev = trace[k]
            po = prev.get('outputs', {})
            pi = prev.get('inputs', {})
            if (po.get('idle') == 1 and pi.get('ena') == 1 and
                    po.get('clk_en') == 1 and pi.get('nReset') == 1 and
                    pi.get('rst') == 0):
                accepted = True
                break
        if accepted:
            candidates.append(i)

    if not candidates:
        return (None, None, 'no declared START-sequence signature occurred after an idle command-acceptance state')

    for start in candidates:
        for j in range(start, len(trace)):
            row = trace[j]
            out = row.get('outputs', {})
            if out.get('start_sequence') != 1:
                break
            if out.get('scl_oen') != 1:
                continue
            if j > 0:
                before = trace[j - 1].get('outputs', {})
                if before.get('sda_oen') == 1 and out.get('sda_oen') == 0:
                    return (True, row.get('edge'), 'START decoding produced the required sda_oen 1-to-0 transition while scl_oen remained released')
        row = trace[start]
        return (False, row.get('edge'), 'START-sequence signature occurred, but sda_oen never transitioned from 1 to 0 while scl_oen was released')

    return (None, None, 'START-sequence signature was not decidable')

