    # start_sequence probe as the START-command signature instead of guessing
    # that START has a particular numeric cmd value.
    start_edges = edges(trace, "start_sequence", "rise")
    windows = after(
        trace,
        lambda r: r["edge"] in start_edges,
        until=TO_END,
    )

    def start_low_transition(window):
        for i, row in enumerate(window.rows):
            if i == 0:
                previous = None
            else:
                previous = window.rows[i - 1]
            if (
                previous is not None
                and previous["outputs"].get("sda_oen") == 1
                and row["outputs"].get("sda_oen") == 0
            ):
                return (True, row["edge"], "sda_oen transitioned 1 to 0 during the START phase")
        if not window.closed:
            return (None, window.edge, "START sequence began but the trace ended before the SDA-low transition")
        return (False, window.edge, "START sequence occurred without the required sda_oen 1-to-0 transition")

    return worst([start_low_transition(w) for w in windows])

