    results = []
    n = len(trace)

    for i, row in enumerate(trace):
        out = row.get('outputs', {})
        if out.get('start_sequence') != 1:
            continue
        if i > 0 and trace[i - 1].get('outputs', {}).get('start_sequence') == 1:
            continue

        found = None
        end = None
        j = i
        while j < n and trace[j].get('outputs', {}).get('start_sequence') == 1:
            current = trace[j].get('outputs', {})
            previous = trace[j - 1].get('outputs', {}) if j > 0 else {}
            if (previous.get('sda_oen') == 1 and
                    current.get('sda_oen') == 0 and
                    current.get('scl_oen') == 1):
                found = trace[j].get('edge')
                break
            j += 1

        if found is not None:
            results.append((True, found,
                            'during the declared START-sequence signature, sda_oen transitioned from 1 to 0 while scl_oen was released'))
            continue

        end = j
        if end >= n:
            results.append((None, None,
                            'the START-sequence window remained open at the end of the trace before the required sda_oen transition was decidable'))
        else:
            results.append((False, trace[i].get('edge'),
                            'the completed START-sequence signature did not produce the required sda_oen 1-to-0 transition while scl_oen was released'))

    if not results:
        return (None, None, 'the declared START-sequence signature never occurred; no START decoding situation was exercised')

