def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name)

    starts = []
    for i, row in enumerate(trace):
        active = value(row, 'write_sequence') == 1
        prior = value(trace[i - 1], 'write_sequence') == 1 if i else False
        if active and not prior:
            starts.append(i)

    if not starts:
        return (None, None, 'the WRITE command situation did not occur in this trace')

    for start in starts:
        acknowledged = None
        aborted = False
        ended = False

        for i in range(start + 1, len(trace)):
            row = trace[i]
            if value(row, 'rst') == 1 or value(row, 'nReset') == 0:
                aborted = True
                break
            if value(row, 'al') == 1:
                aborted = True
                break

            if value(row, 'cmd_ack') == 1:
                acknowledged = i
                break

            if value(row, 'write_sequence') != 1:
                ended = True
                break

        if aborted:
            continue

        if acknowledged is None:
            if ended:
                return (False, trace[start]['edge'], 'the WRITE command sequence ended without cmd_ack')
            return (None, None, 'the WRITE command was still active when the trace ended')

        high_rows = []
        j = acknowledged
        while j < len(trace) and value(trace[j], 'cmd_ack') == 1:
            high_rows.append(trace[j])
            j += 1

        width = sum(row.get('held', 1) for row in high_rows)
        if width != 1:
            return (False, trace[acknowledged]['edge'],
                    f'cmd_ack was high for {width} clock edges; expected one clock')

        if j < len(trace) and value(trace[j], 'cmd_ack') == 1:
            return (False, trace[j]['edge'], 'cmd_ack did not form a single pulse')

    return (True, None, 'each observed WRITE command completed with a one-clock cmd_ack pulse')

