def decide(trace):
    triggers = []
    for i, row in enumerate(trace):
        probe = row.get('outputs', {}).get('write_sequence')
        before = False if i == 0 else bool(trace[i - 1].get('outputs', {}).get('write_sequence'))
        if probe and not before:
            triggers.append(i)

    if not triggers:
        return (None, None, 'the WRITE command signature never occurred')

    checked = 0
    aborted = 0
    for start in triggers:
        ack_index = None
        abort_index = None
        for j in range(start + 1, len(trace)):
            inputs = trace[j].get('inputs', {})
            outputs = trace[j].get('outputs', {})
            if inputs.get('rst') == 1 or inputs.get('nReset') == 0:
                abort_index = j
                break
            if outputs.get('al') == 1:
                abort_index = j
                break
            ack = bool(outputs.get('cmd_ack'))
            previous_ack = bool(trace[j - 1].get('outputs', {}).get('cmd_ack'))
            if ack and not previous_ack:
                ack_index = j
                break

        if abort_index is not None:
            aborted += 1
            continue

        if ack_index is None:
            return (False, trace[start].get('edge'),
                    'I2C_CMD_WRITE was presented and did not complete with cmd_ack')

        checked += 1
        pulse_edges = 0
        k = ack_index
        while k < len(trace) and trace[k].get('outputs', {}).get('cmd_ack') == 1:
            pulse_edges += trace[k].get('held', 0)
            k += 1
        if pulse_edges != 1:
            return (False, trace[ack_index].get('edge'),
                    f'cmd_ack pulse lasted {pulse_edges} clock edge(s), expected exactly one')

    if checked == 0:
        return (None, None, 'all WRITE command occurrences were aborted before completion')
    return (True, None, f'{checked} supported WRITE command occurrence(s) completed with one-clock cmd_ack pulses')

def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    starts = []
    for i, row in enumerate(trace):
        active = out(row, 'write_sequence') == 1
        prior = out(trace[i - 1], 'write_sequence') == 1 if i else False
        reset_active = inp(row, 'rst') == 1 or inp(row, 'nReset') == 0
        arbitration_lost = out(row, 'al') == 1
        if active and not prior and not reset_active and not arbitration_lost:
            starts.append(i)

    if not starts:
        return (None, None, 'the WRITE command sequence did not occur in this trace')

    for start in starts:
        ack_index = None
        aborted = False

        for i in range(start + 1, len(trace)):
            row = trace[i]
            if inp(row, 'rst') == 1 or inp(row, 'nReset') == 0 or out(row, 'al') == 1:
                aborted = True
                break
            if out(row, 'cmd_ack') == 1:
                ack_index = i
                break

        if aborted:
            continue

        if ack_index is None:
            return (None, None,
                    'the WRITE command was not completed before the trace ended')

        width = 0
        j = ack_index
        while j < len(trace) and out(trace[j], 'cmd_ack') == 1:
            width += trace[j].get('held', 1)
            j += 1

        if j == len(trace):
            return (None, trace[ack_index]['edge'],
                    'cmd_ack was still high when the trace ended; its full pulse width is not observable')

        if width != 1:
            return (False, trace[ack_index]['edge'],
                    f'cmd_ack was high for {width} clock edges; expected one clock')

    return (True, None, 'each non-aborted WRITE command completed with a one-clock cmd_ack pulse')

