def decide(trace):
    unsupported = {0, 3, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15}

    def reset_active(row):
        return (row['inputs'].get('rst', 0) == 1 or
                row['inputs'].get('nReset', 1) == 0)

    def applies(row):
        return (not reset_active(row) and
                row['inputs'].get('cmd') in unsupported and
                row['outputs'].get('idle') == 1)

    seen = False
    open_at_end = False
    aborted = False
    last_closed_edge = None
    previous = False

    for i, row in enumerate(trace):
        active = applies(row)
        if not active or previous:
            previous = active
            continue

        seen = True
        j = i
        closed = False
        while j < len(trace):
            current = trace[j]
            if reset_active(current):
                aborted = True
                closed = True
                break

            if current['inputs'].get('cmd') not in unsupported:
                closed = True
                last_closed_edge = current.get('edge')
                break

            if current['outputs'].get('idle') != 1:
                return (False, current.get('edge'),
                        'unsupported or idle command was driven, but the FSM left idle')
            j += 1

        if not closed:
            open_at_end = True

        previous = active

    if not seen:
        return (None, None, 'no unsupported or idle command was observed while the FSM was idle')
    if open_at_end and last_closed_edge is None:
        return (None, None, 'unsupported or idle command remained active to the end; the requirement was not fully observed')
    if open_at_end:
        return (None, None, 'an unsupported or idle command window remained open at trace end')
    if last_closed_edge is not None:
        return (True, last_closed_edge, 'the FSM remained idle for each observed unsupported or idle command')
    if aborted:
        return (None, None, 'all observed unsupported or idle command windows were aborted by reset')
    return (None, None, 'the requirement was not fully observed')

