                row['outputs'].get('idle') == 1)

    def command_withdrawn(row):
        return row['inputs'].get('cmd') not in unsupported

    windows = after(trace, applies, until=command_withdrawn)
    return worst([
        throughout(w, lambda row: row['outputs'].get('idle') == 1)
        for w in windows
    ])

def decide(trace):
    unsupported = {0, 3, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15}
    active_cmd = None
    saw_activation = False
    last_edge = None

    for row in trace:
        cmd = row.get('inputs', {}).get('cmd')
        idle = row.get('outputs', {}).get('idle')

        if cmd not in unsupported:
            active_cmd = None
            continue

        if active_cmd != cmd:
            active_cmd = None
            if idle == 1:
                active_cmd = cmd
                saw_activation = True

        if active_cmd == cmd:
            last_edge = row.get('edge')
            if idle != 1:
                return (False, row.get('edge'),
                        'the FSM left idle while an idle or unsupported command was driven')

    if not saw_activation:
        return (None, None, 'no idle or unsupported command was observed while the FSM was idle')

    return (True, last_edge, 'the FSM remained idle for each observed idle or unsupported command occurrence')

