def decide(trace):
    from specflow.refmodel.temporal import after, throughout, TO_END, worst

    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_of(alternatives):
        predicates = [holds(cond) for cond in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # The command encoding is not taken from the normalized numeric input;
    # the declared write_sequence probe identifies the WRITE situation.
    applies = lambda row: (
        row['outputs'].get('write_sequence') == 1
        and row['inputs'].get('ena') == 1
    )
    closes = any_of([{'cmd_ack': 1}])
    aborts = any_of([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        applies,
        until=closes,
        aborts=aborts,
    )

    def transmits_din(window):
        return throughout(
            window,
            lambda row: row['outputs'].get('sda_oen') == (
                0 if row['inputs'].get('din') == 0 else 1
            ),
            after_activation=True,
        )

    return worst([transmits_din(window) for window in windows])

