from specflow.refmodel.temporal import after, throughout, TO_END, worst


def decide(trace):
    def holds(cond):
        def predicate(row):
            values = row.get("outputs", {})
            values = {**row.get("inputs", {}), **values}
            return all(values.get(port) == value for port, value in cond.items())
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    activation = lambda row: (
        holds({"cmd": 4, "ena": 1})(row)
        and row.get("outputs", {}).get("write_sequence") == 1
    )

    windows = after(
        trace,
        activation,
        until=any_condition([{"cmd_ack": 1}]),
        aborts=any_condition([
            {"al": 1},
            {"nReset": 0},
            {"rst": 1},
        ]),
    )

    def expected(row):
        din = row.get("inputs", {}).get("din")
        return row.get("outputs", {}).get("sda_oen") == din

    return worst([
        throughout(window, expected, after_activation=True)
        for window in windows
    ])

