def decide(trace):
    def out_is(port, value):
        return lambda row: row["outputs"].get(port) == value

    def any_outputs(alternatives):
        return lambda row: any(
            all(row["outputs"].get(port) == value
                for port, value in alternative.items())
            for alternative in alternatives
        )

    def write_active(row):
        return (row["outputs"].get("write_sequence") == 1
                and row["inputs"].get("ena") == 1)

    windows = after(
        trace,
        write_active,
        until=any_outputs([{ "cmd_ack": 1 }]),
        aborts=any_outputs([
            {"al": 1},
            {"nReset": 0},
            {"rst": 1}
        ])
    )

    verdicts = []
    for window in windows:
        din = window.value("din")
        expected_oen = 0 if din == 0 else 1
        verdicts.append(
            throughout(
                window,
                out_is("sda_oen", expected_oen),
                after_activation=True
            )
        )

    return worst(verdicts)

from specflow.refmodel.temporal import after, eventually, TO_END, worst


def decide(trace):
    def value(row, port):
        outputs = row.get("outputs", {})
        if port in outputs:
            return outputs.get(port)
        return row.get("inputs", {}).get(port)

    def is_write_sequence(row):
        return (
            value(row, "cmd") == 4
            and value(row, "ena") == 1
            and value(row, "write_sequence") == 1
        )

    def is_completion(row):
        return value(row, "cmd_ack") == 1

    def is_abort(row):
        return (
            value(row, "al") == 1
            or value(row, "nReset") == 0
            or value(row, "rst") == 1
        )

    windows = after(
        trace,
        is_write_sequence,
        until=is_completion,
        aborts=is_abort,
    )

    verdicts = []
    for window in windows:
        din = window.value("din")
        expected = 0 if din == 0 else 1
        verdicts.append(
            eventually(
                window,
                lambda row, expected=expected: value(row, "sda_oen") == expected,
                strong=True,
                after_activation=True,
            )
        )

    return worst(verdicts)

