def decide(trace):
    _declared_al = [row.get('outputs', {}).get('al') for row in trace]
    return (None, None, 'This requirement does not constrain declared output al; no licensed al check exists')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset(row):
        return out(row, 'nReset') == 0 or out(row, 'rst') == 1

    def active(row):
        return out(row, 'ena') == 1 and not reset(row)

    def rose(name, i):
        if i == 0:
            return out(trace[i], name) == 1
        return out(trace[i], name) == 1 and out(trace[i - 1], name) != 1

    failures = []
    checked = 0

    # Filtered clock stretching: while the controller reports that it is
    # waiting for released SCL to become high, the SCL output must remain
    # released.  The wait probe scopes this to an actual stretching case.
    for row in trace:
        if active(row) and out(row, 'slave_wait') == 1:
            checked += 1
            if out(row, 'scl_oen') != 1:
                failures.append((row['edge'], 'scl_oen was not released during filtered-SCL clock stretching'))

    # START/STOP detection must be reflected at the declared busy output.
    for i, row in enumerate(trace):
        if not active(row):
            continue

        if rose('sta_condition', i):
            checked += 1
            found = False
            for j in range(i, len(trace)):
                r = trace[j]
                if reset(r):
                    break
                if j > i and rose('sto_condition', j):
                    break
                if out(r, 'busy') == 1:
                    found = True
                    break
            if not found:
                failures.append((row['edge'], 'filtered START condition was not reflected by busy becoming high'))

        if rose('sto_condition', i):
            checked += 1
            found = False
            for j in range(i, len(trace)):
                r = trace[j]
                if reset(r):
                    break
                if j > i and rose('sta_condition', j):
                    break
                if out(r, 'busy') == 0:
                    found = True
                    break
            if not found:
                failures.append((row['edge'], 'filtered STOP condition was not reflected by busy becoming low'))

        # Filtered READ sampling: compare against the filtered SDA value at
        # the SCL rising event, allowing unspecified registered latency.
        if rose('filtered_scl_rising', i) and out(row, 'read_sequence') == 1:
            checked += 1
            expected = out(row, 'ssda')
            found = False
            for j in range(i, len(trace)):
                r = trace[j]
                if reset(r):
                    break
                if j > i and out(r, 'read_sequence') != 1:
                    break
                if out(r, 'dout') == expected:
                    found = True
                    break
            if not found:
                failures.append((row['edge'], 'dout did not capture the filtered SDA value at a filtered SCL rising edge'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if checked == 0:
        return (None, None, 'no enabled clock-stretching, filtered START/STOP, or READ-sampling situation occurred')
    return (True, None, 'SCL-dependent stretching, START/STOP busy reflection, and READ sampling observations satisfied')

