def decide(trace):
    # The activation is an enabled, non-reset sampling situation.  A raw
    # transition is the useful event; a fixed latency is not specified.
    events = []
    undecided = []

    def active(row):
        return (row['inputs'].get('ena') == 1 and
                row['inputs'].get('nReset') != 0 and
                row['inputs'].get('rst') != 1)

    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        if not active(prev) or not active(row):
            continue

        old_raw = prev['inputs'].get('sda_i')
        new_raw = row['inputs'].get('sda_i')
        if old_raw == new_raw:
            continue

        events.append(row)
        old_filtered = prev['outputs'].get('ssda')
        new_filtered = row['outputs'].get('ssda')

        # A synchronized and filtered signal cannot respond in the same
        # distinct state as the raw input transition.
        if new_filtered != old_filtered:
            return (False, row['edge'],
                    'ssda changed in the same distinct state as raw sda_i; '
                    'the input was not observed only after synchronization and filtering')

        found = False
        interrupted = False
        for j in range(i + 1, len(trace)):
            nxt = trace[j]
            if not active(nxt):
                interrupted = True
                break
            if nxt['inputs'].get('sda_i') != new_raw:
                interrupted = True
                break
            if nxt['outputs'].get('ssda') == new_raw:
                found = True
                break

        if found:
            undecided.append((row, True))
        else:
            # The trace did not provide a stable, completed observation of
            # the filtered response; no latency or filter sample count is
            # licensed by this requirement.
            undecided.append((row, False))

    if not events:
        return (None, None, 'no enabled, non-reset sda_i transition occurred')

    completed = [event for event, found in undecided if found]
    if completed:
        return (True, completed[-1]['edge'],
                'each observed stable enabled sda_i transition reached its value in ssda only in a later distinct state')

    return (None, events[0]['edge'],
            'enabled sda_i transitions occurred, but no stable transition remained observable long enough to confirm the later filtered ssda value')

def decide(trace):
    last_reset = -1
    relevant = False
    al_rises = []

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            last_reset = i
            relevant = False
            al_rises = []
            continue

        if inputs.get('ena') != 1:
            continue

        if i > 0 and out(row, 'al') == 1 and out(trace[i - 1], 'al') != 1:
            al_rises.append(i)

        arbitration_evidence = (
            out(row, 'write_sequence') == 1 and
            out(row, 'sda_chk') == 1 and
            out(row, 'ssda') == 0
        )
        stop_evidence = (
            out(row, 'fsm_active') == 1 and
            out(row, 'sto_condition') == 1
        )
        if arbitration_evidence or stop_evidence:
            relevant = True

        if al_rises:
            rise = al_rises[-1]
            evidence = False
            for j in range(last_reset + 1, rise + 1):
                r = trace[j]
                if r.get('inputs', {}).get('ena') != 1:
                    continue
                if (out(r, 'write_sequence') == 1 and
                        out(r, 'sda_chk') == 1 and
                        out(r, 'ssda') == 0):
                    evidence = True
                    break
                if (out(r, 'fsm_active') == 1 and
                        out(r, 'sto_condition') == 1):
                    evidence = True
                    break
            if not evidence:
                return (False, trace[rise].get('edge'),
                        'al asserted without preceding synchronized/filtered SDA evidence')

    if not relevant and not al_rises:
        return (None, None,
                'no enabled arbitration or active filtered-STOP situation occurred')
    return (True, None,
            'every observed al assertion had synchronized/filtered SDA evidence')

def decide(trace):
    relevant = False
    first_edge = None

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def probe(row, name):
        return out(row, name)

    for i, row in enumerate(trace):
        if inp(row, 'ena') != 1 or inp(row, 'nReset') == 0 or inp(row, 'rst') == 1:
            continue

        edge = row.get('edge')

        # A filtered SCL rising edge samples the filtered SDA value.
        if probe(row, 'filtered_scl_rising') == 1:
            relevant = True
            if first_edge is None:
                first_edge = edge
            if out(row, 'dout') != probe(row, 'ssda'):
                return (False, edge,
                        'dout did not capture the synchronized and filtered ssda value at a filtered SCL rising edge')

        if i == 0:
            continue
        prev = trace[i - 1]
        if inp(prev, 'nReset') == 0 or inp(prev, 'rst') == 1:
            continue

        # A status change attributed to START/STOP detection must use the
        # filtered SDA transition, represented by the condition probes.
        busy_changed = out(row, 'busy') != out(prev, 'busy')
        if busy_changed:
            relevant = True
            if first_edge is None:
                first_edge = edge
            start_or_stop = (probe(row, 'sta_condition') == 1 or
                              probe(row, 'sto_condition') == 1)
            if not start_or_stop:
                return (False, edge,
                        'busy changed without a filtered SDA START/STOP detection condition')
            expected = 0 if probe(row, 'sta_condition') == 1 else 1
            if probe(row, 'ssda') != expected:
                return (False, edge,
                        'busy changed on a START/STOP condition whose SDA value was not the filtered ssda value')

        # Arbitration loss must use the filtered SDA, not the raw input.
        al_rise = out(prev, 'al') != 1 and out(row, 'al') == 1
        if al_rise:
            relevant = True
            if first_edge is None:
                first_edge = edge
            write_loss = (probe(row, 'sda_chk') == 1 and probe(row, 'ssda') == 0)
            stop_loss = (probe(row, 'fsm_active') == 1 and
                         probe(row, 'sto_condition') == 1 and
                         probe(row, 'ssda') == 1)
            if not (write_loss or stop_loss):
                return (False, edge,
                        'al asserted without an arbitration condition represented by filtered ssda')

    if not relevant:
        return (None, None, 'no enabled, non-reset SDA use was observed')
    return (True, first_edge, 'SDA-dependent uses observed only through synchronized and filtered ssda')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    observations = []

    # START and STOP detection must use the corresponding filtered SDA value.
    for row in trace:
        if out(row, 'sta_condition') == 1:
            observations.append((row, out(row, 'ssda') == 0,
                                 'START detection requires filtered ssda low'))
        if out(row, 'sto_condition') == 1:
            observations.append((row, out(row, 'ssda') == 1,
                                 'STOP detection requires filtered ssda high'))

    # A newly asserted arbitration-loss indication during the declared
    # arbitration-check phase must be based on filtered SDA, not raw sda_i.
    for i, row in enumerate(trace):
        if out(row, 'sda_chk') != 1 or out(row, 'al') != 1:
            continue
        previous_al = out(trace[i - 1], 'al') if i else 0
        if previous_al != 1:
            observations.append((row, out(row, 'ssda') == 0,
                                 'arbitration loss must be indicated by filtered ssda low'))

    # At a filtered SCL rising edge in the READ sequence, dout must capture
    # the filtered SDA value sampled for that event.  No edge count is fixed;
    # accept the value on the event row or any later row in the same sequence.
    for i, row in enumerate(trace):
        if out(row, 'filtered_scl_rising') != 1:
            continue
        if out(row, 'read_sequence') != 1:
            continue
        expected = out(row, 'ssda')
        matched = False
        end_row = row
        for later in trace[i:]:
            end_row = later
            if out(later, 'dout') == expected:
                matched = True
                break
            if out(later, 'read_sequence') != 1:
                break
        if matched:
            observations.append((row, True,
                                 'dout captured the filtered ssda sample'))
        elif out(end_row, 'read_sequence') != 1:
            observations.append((row, False,
                                 'dout did not capture the filtered ssda sample before the READ sequence ended'))
        else:
            observations.append((row, None,
