            return (False, row.get('edge'), detail)

    unknown = [row for row, ok, detail in observations if ok is None]
    if unknown:
        return (None, unknown[0].get('edge'),
                'the relevant sampling situation occurred but the trace ended before its consequence could be observed')

    last = observations[-1][0]
    return (True, last.get('edge'),
            'all observed SDA consumer situations used the synchronized and filtered ssda value')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    observations = []

    # START and STOP detection must use the filtered SDA probe.
    for row in trace:
        if out(row, 'sta_condition') == 1:
            if out(row, 'ssda') != 0:
                observations.append((False, row.get('edge'),
                                     'START detection occurred with ssda != 0; the raw SDA value was not filtered before detection'))
            else:
                observations.append((True, row.get('edge'),
                                     'START detection used filtered ssda == 0'))
        if out(row, 'sto_condition') == 1:
            if out(row, 'ssda') != 1:
                observations.append((False, row.get('edge'),
                                     'STOP detection occurred with ssda != 1; the raw SDA value was not filtered before detection'))
            else:
                observations.append((True, row.get('edge'),
                                     'STOP detection used filtered ssda == 1'))

    # Arbitration loss during the declared WRITE arbitration-check phase
    # must be based on filtered SDA low.  Check only the assertion transition
    # so a sticky al flag is not repeatedly treated as a new event.
    for i, row in enumerate(trace):
        if out(row, 'sda_chk') != 1 or out(row, 'al') != 1:
            continue
        previous_al = out(trace[i - 1], 'al') if i else 0
        if previous_al == 1:
            continue
        if out(row, 'ssda') != 0:
            observations.append((False, row.get('edge'),
                                 'al asserted during SDA arbitration checking while filtered ssda was not low'))
        else:
            observations.append((True, row.get('edge'),
                                 'arbitration loss used filtered ssda == 0'))

    # At each filtered SCL rising edge in READ, dout must eventually expose
    # the filtered SDA sample.  No fixed number of states is imposed.  Stop
    # looking when the READ situation ends; an incomplete trace remains
    # unknown, while ending the READ phase without the required sample is a
    # failure.
    for i, row in enumerate(trace):
        if out(row, 'filtered_scl_rising') != 1:
            continue
        if out(row, 'read_sequence') != 1:
            continue

        expected = out(row, 'ssda')
        matched = False
        ended = False
        last = row
        for later in trace[i:]:
            last = later
            if out(later, 'dout') == expected:
                matched = True
                break
            if later is not row and (
                    out(later, 'filtered_scl_rising') == 1 or
                    out(later, 'read_sequence') != 1):
                ended = True
                break

        if matched:
            observations.append((True, row.get('edge'),
                                 'dout captured the filtered ssda value at READ sampling'))
        elif ended:
            observations.append((False, last.get('edge'),
                                 'READ sampling ended without dout capturing the filtered ssda value'))
        else:
            observations.append((None, row.get('edge'),
                                 'READ sampling occurred but the trace ended before dout could be observed'))

    if not observations:
        return (None, None,
                'no enabled START/STOP detection, arbitration-loss assertion, or READ sampling event occurred')

    for ok, edge, detail in observations:
        if ok is False:
            return (False, edge, detail)

    for ok, edge, detail in observations:
        if ok is None:
            return (None, edge, detail)

    return (True, observations[-1][1],
            'all observed SDA consumers used the synchronized and filtered ssda value')

def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name)

    seen = False

    # START and STOP detection must use the filtered SDA value, and the
    # resulting busy level must correspond to the detected condition.
    for i, row in enumerate(trace):
        sta = value(row, 'sta_condition') == 1
        sto = value(row, 'sto_condition') == 1
        if not (sta or sto):
            continue
        seen = True

        ssda = value(row, 'ssda')
        expected_ssda = 0 if sta else 1
        if ssda != expected_ssda:
            return (False, row.get('edge'),
                    f'START/STOP detection used ssda={ssda}, expected filtered ssda={expected_ssda}')

        expected_busy = 1 if sta else 0
        # A registered status may become visible in a later distinct state;
        # do not impose a cycle count.  A value already present is valid.
        for later in trace[i:]:
            if value(later, 'busy') == expected_busy:
                break
        else:
            if row.get('rst') == 1 or row.get('nReset') == 0:
                continue
            return (None, row.get('edge'),
                    f'busy did not yet show {expected_busy} for the filtered SDA condition')

    # Arbitration loss during the declared WRITE arbitration-check phase
    # must not be caused by an unfiltered high SDA value.  `al` is sticky, so
    # inspect only its assertion transition.
    for i, row in enumerate(trace):
        if value(row, 'sda_chk') != 1 or value(row, 'al') != 1:
            continue
        seen = True
        previous = value(trace[i - 1], 'al') if i else 0
        if previous == 1:
            continue
        if value(row, 'ssda') != 0:
            return (False, row.get('edge'),
                    'al asserted while arbitration checking saw filtered ssda=1')

    # At each filtered SCL rising edge in the READ sequence, dout must
    # eventually expose that filtered SDA sample.  The search is transactional
    # and ends at the next sample, the end of READ, or an abort; no edge count
    # is required.
    for i, row in enumerate(trace):
        if value(row, 'filtered_scl_rising') != 1:
            continue
        if value(row, 'read_sequence') != 1:
            continue
        seen = True
        expected = value(row, 'ssda')
        matched = False

        for later in trace[i:]:
            if value(later, 'dout') == expected:
                matched = True
                break
            if later is not row and (
                    value(later, 'filtered_scl_rising') == 1 or
                    value(later, 'read_sequence') != 1 or
                    value(later, 'rst') == 1 or
                    value(later, 'nReset') == 0):
                return (False, later.get('edge'),
                        f'dout did not capture filtered ssda={expected} at the READ sample')

        if not matched:
            return (None, row.get('edge'),
                    f'READ sampled filtered ssda={expected}, but the trace ended before dout showed it')

    if not seen:
        return (None, None,
                'no enabled START/STOP detection, arbitration-check assertion, or READ sampling event occurred')

    return (True, None,
            'all observed SDA consumers used the synchronized and filtered ssda value')

