def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def value(row, port):
        return row.get('outputs', {}).get(port)

    completions = []
    for port in sequence_ports:
        for i in range(1, len(trace)):
            if value(trace[i - 1], port) == 1 and value(trace[i], port) == 0:
                row = trace[i]
                if (row.get('inputs', {}).get('nReset') == 0 or
                        row.get('inputs', {}).get('rst') == 1 or
                        value(row, 'al') == 1):
                    continue
                completions.append(i)

    if not completions:
        return (None, None, 'no non-aborted command completion occurred in this trace')

    for i in completions:
        row = trace[i]
        edge = row.get('edge')
        if value(row, 'cmd_ack') != 1:
            return (False, edge,
                    'cmd_ack was not high when the command sequence finished')

        if i > 0 and value(trace[i - 1], 'cmd_ack') == 1:
            return (False, edge,
                    'cmd_ack was already high before the command completed')

        high_edges = row.get('held', 0)
        j = i + 1
        while j < len(trace) and value(trace[j], 'cmd_ack') == 1:
            high_edges += trace[j].get('held', 0)
            j += 1

        if high_edges != 1:
            return (False, edge,
                    f'cmd_ack was high for {high_edges} clock edges; expected exactly 1')

        if j == len(trace):
            return (None, edge,
                    'cmd_ack was high for one observed edge, but the trace ended before its pulse ended')

    return (True, trace[completions[0]].get('edge'),
            f'cmd_ack completed a one-clock-cycle pulse for {len(completions)} command completion(s)')

def decide(trace):
    sequences = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')

    def out(row, name):
        return row.get('outputs', {}).get(name, 0) == 1

    def active(row):
        return any(out(row, name) for name in sequences)

    completions = []
    for i in range(1, len(trace)):
        before = trace[i - 1]
        row = trace[i]
        if (active(before)
                and out(row, 'idle')
                and not out(before, 'rst')
                and not out(row, 'rst')
                and not out(before, 'nReset') is False
                and not out(row, 'nReset') is False
                and not out(before, 'al')
                and not out(row, 'al')):
            completions.append(i)

    if not completions:
        return (None, None, 'no non-aborted START, STOP, READ, or WRITE command completion was observed')

    for i in completions:
        j = i
        while j < len(trace) and not out(trace[j], 'cmd_ack'):
            if j > i and (out(trace[j], 'rst') or not out(trace[j], 'nReset') or out(trace[j], 'al') or active(trace[j])):
                break
            j += 1

        if j == len(trace) or not out(trace[j], 'cmd_ack'):
            return (False, trace[i]['edge'], 'command completion was observed but cmd_ack was never asserted')

        width = 0
        k = j
        while k < len(trace) and out(trace[k], 'cmd_ack'):
            width += trace[k].get('held', 1)
            k += 1
        if width != 1:
            return (False, trace[j]['edge'], f'cmd_ack was high for {width} clock cycle(s), expected exactly 1')

    return (True, trace[completions[-1]]['edge'], f'{len(completions)} completed command(s) each produced a one-clock cmd_ack pulse')

def decide(trace):
    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def active(row):
        outputs = row.get('outputs', {})
        return any(outputs.get(name, 0) == 1 for name in sequence_probes)

    completions = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        previous = trace[i - 1]
        if not active(previous) or active(row):
            continue

        inputs = row.get('inputs', {})
        previous_outputs = previous.get('outputs', {})
        outputs = row.get('outputs', {})
        reset_or_abort = (
            inputs.get('nReset') == 0 or
            inputs.get('rst') == 1 or
            previous_outputs.get('al', 0) == 1 or
            outputs.get('al', 0) == 1
        )
        if not reset_or_abort:
            completions.append(i)

    if not completions:
        return (None, None, 'no non-aborted START, STOP, READ, or WRITE command completion occurred')

    for completion in completions:
        ack_start = None
        stopped_by_new_command = False

        for j in range(completion, len(trace)):
            row = trace[j]
            outputs = row.get('outputs', {})
            inputs = row.get('inputs', {})

            if j > completion and active(row):
                stopped_by_new_command = True
                break
            if inputs.get('nReset') == 0 or inputs.get('rst') == 1 or outputs.get('al', 0) == 1:
                stopped_by_new_command = True
                break
            if outputs.get('cmd_ack') == 1:
                ack_start = j
                break

        if ack_start is None:
            if stopped_by_new_command:
                return (False, trace[completion].get('edge'),
                        'cmd_ack was not asserted before the next command or abort after command completion')
            return (False, trace[completion].get('edge'),
                    'cmd_ack was not asserted for the completed command')

        high_edges = 0
        ended = False
        end_edge = trace[ack_start].get('edge')
        for k in range(ack_start, len(trace)):
            row = trace[k]
            if row.get('outputs', {}).get('cmd_ack') != 1:
                ended = True
                end_edge = row.get('edge')
                break
            high_edges += row.get('held', 0)

        if high_edges != 1:
            return (False, trace[ack_start].get('edge'),
                    f'cmd_ack was high for {high_edges} edges at command completion; expected exactly one clock cycle')
        if not ended:
            return (None, trace[ack_start].get('edge'),
                    'cmd_ack was observed high for one edge, but the trace ended before its deassertion could be observed')

    return (True, None,
            f'cmd_ack was asserted for exactly one clock cycle at each of {len(completions)} non-aborted command completion(s)')

def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def out(row, port):
        return row.get('outputs', {}).get(port)

    def reset_or_abort(row):
        inputs = row.get('inputs', {})
        return (inputs.get('nReset') == 0 or
                inputs.get('rst') == 1 or
                out(row, 'al') == 1)

    def any_sequence_active(row):
        return any(out(row, p) == 1 for p in sequence_ports)

    completions = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        if current.get('inputs', {}).get('ena') != 1:
            continue
        if reset_or_abort(current):
            continue
        if any(out(previous, p) == 1 and out(current, p) == 0
               for p in sequence_ports):
            completions.append(i)

    if not completions:
        return (None, None,
                'no enabled non-aborted START, STOP, READ, or WRITE command finished')

    for i in completions:
        completion = trace[i]
        completion_edge = completion.get('edge')

        j = i
        ack_index = None
        while j < len(trace):
            row = trace[j]
            if reset_or_abort(row):
                break
            if j > i and any_sequence_active(row):
                break
            if out(row, 'cmd_ack') == 1:
                ack_index = j
                break
            j += 1

        if ack_index is None:
            return (False, completion_edge,
                    'cmd_ack was not asserted for the completed command')

        ack = trace[ack_index]
        if ack_index > 0 and out(trace[ack_index - 1], 'cmd_ack') == 1:
            return (False, ack.get('edge'),
                    'cmd_ack was already high before the command completion acknowledge')

        width = ack.get('held', 0)
        if width != 1:
            return (False, ack.get('edge'),
                    f'cmd_ack was asserted for {width} clock edges; the obligation requires one clk cycle')

    return (True, trace[completions[0]].get('edge'),
            f'cmd_ack was asserted for exactly one clk cycle for {len(completions)} completed command(s)')

