from specflow.refmodel.temporal import TO_END, after, runs


def decide(trace):
    def sequence_active(row):
        outputs = row['outputs']
        return any(outputs.get(name) == 1 for name in (
            'start_sequence',
            'stop_sequence',
            'read_sequence',
            'write_sequence',
        ))

    def ack(row):
        return row['outputs'].get('cmd_ack') == 1

    # The sequence probes are the declared signature of a command in progress;
    # no unstated numeric cmd encoding is assumed.
    windows = after(trace, sequence_active, until=ack)
    if not windows:
        return (None, None, 'no START, STOP, READ, or WRITE command sequence occurred')

    ack_runs = runs(trace, 'cmd_ack', value=1, at_least=1, at_most=1)
    verdicts = []

    for window in windows:
        window_edges = {row['edge'] for row in window.rows}
        matching = sorted(ack_runs.intersection(window_edges))

        if matching:
            verdicts.append((
                True,
                matching[0],
                'cmd_ack was asserted for exactly one clk cycle as required'
            ))
            continue

        observed_ack = [row for row in window.rows if ack(row)]
        if observed_ack:
            last = observed_ack[-1]
            if last is trace[-1]:
                verdicts.append((
                    None,
                    last['edge'],
                    'cmd_ack was high at trace end, but its one-clock duration could not be established'
                ))
            else:
                verdicts.append((
                    False,
                    last['edge'],
                    'cmd_ack was not asserted for exactly one clk cycle'
                ))
        else:
            verdicts.append((
                False,
                window.edge,
                'command sequence occurred but cmd_ack never completed it'
            ))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    if any(verdict[0] is None for verdict in verdicts):
        return next(verdict for verdict in verdicts if verdict[0] is None)
    return (True, verdicts[-1][1], 'every observed command completion used a one-clk cmd_ack pulse')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges

    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def out(row, port):
        return row.get('outputs', {}).get(port)

    def aborted(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1 or
                out(row, 'al') == 1)

    windows = []
    for port in sequence_ports:
        rising = edges(trace, port, 'rise')
        windows.extend(after(
            trace,
            lambda r, p=port, e=rising: (
                r.get('edge') in e and
                out(r, p) == 1 and
                r.get('inputs', {}).get('ena') == 1
            ),
            until=TO_END,
            aborts=aborted
        ))

    if not windows:
        return (None, None, 'no supported command sequence occurred in this trace')

    for w in windows:
        rows = list(w.rows)
        if not rows:
            continue

        # The completion indication is a consequence of sequence progress,
        # so do not inspect the activation row itself.
        start = 1
        ack_runs = []
        i = start
        while i < len(rows):
            if out(rows[i], 'cmd_ack') != 1:
                i += 1
                continue
            run_start = i
            duration = 0
            while i < len(rows) and out(rows[i], 'cmd_ack') == 1:
                duration += rows[i].get('held', 1)
                i += 1
            ack_runs.append((run_start, duration))

        if not ack_runs:
            last = rows[-1]
            if aborted(last):
                continue
            if any(out(r, p) == 1 for p in sequence_ports for r in rows[-2:]):
                return (False, last.get('edge'),
                        'command sequence completed or trace ended without cmd_ack; '
                        'the requirement says it is asserted when the command finishes')
            return (False, last.get('edge'),
                    'supported command sequence occurred without the required cmd_ack')

        if len(ack_runs) != 1:
            return (False, rows[ack_runs[1][0]].get('edge'),
                    'cmd_ack was asserted more than once for one command sequence; '
                    'the requirement says one clk cycle')

        ack_index, duration = ack_runs[0]
        if duration != 1:
            return (False, rows[ack_index].get('edge'),
                    f'cmd_ack was high for {duration} clk edges, expected exactly one '
                    'as stated by "asserted for one clk cycle"')

        # A trace ending while cmd_ack is high does not expose its falling edge,
        # so the exact pulse width cannot be decided from this trace alone.
        if ack_index + 1 >= len(rows):
            return (None, rows[ack_index].get('edge'),
                    'cmd_ack was observed high for one edge, but the trace ended '
                    'before its deassertion could confirm the one-cycle pulse')

        return (True, rows[ack_index].get('edge'),
                'cmd_ack asserted for exactly one clk edge when the command sequence finished')

    return (None, None, 'all command-sequence attempts were aborted before completion')

from specflow.refmodel.temporal import after, pulse, worst


def decide(trace):
