        "start_sequence",
        "stop_sequence",
        "read_sequence",
        "write_sequence",
    )

    def command_in_progress(row):
        outputs = row["outputs"]
        return any(outputs.get(port) == 1 for port in sequence_probes)

    windows = after(
        trace,
        command_in_progress,
        until=lambda row: row["outputs"].get("cmd_ack") == 1,
    )

    verdicts = []
    for window in windows:
        verdict = pulse(
            window,
            "cmd_ack",
            width=1,
            active=1,
            after_activation=True,
        )
        verdicts.append(
            (
                verdict[0],
                verdict[1],
                f"{verdict[2]}; required: cmd_ack is asserted for exactly one clk cycle when the current bit-level START, STOP, READ, or WRITE command finishes",
            )
        )

