from specflow.refmodel.temporal import after, eventually, worst


def decide(trace):
    def sequence_active(row):
        outputs = row['outputs']
        return any(outputs.get(name) == 1 for name in (
            'start_sequence',
            'stop_sequence',
            'read_sequence',
            'write_sequence',
        ))

    def ack(row):
        return row['outputs'].get('cmd_ack') == 1

    def aborted(row):
        inputs = row['inputs']
        outputs = row['outputs']
        return (inputs.get('nReset') == 0 or
                inputs.get('rst') == 1 or
                outputs.get('al') == 1)

    # The sequence probes identify the accepted command situation without
    # assuming an unstated numeric encoding for cmd.
    windows = after(trace, sequence_active, until=ack, aborts=aborted)
    if not windows:
        return (None, None, 'no START, STOP, READ, or WRITE command sequence occurred')

    verdicts = []
    for window in windows:
        # The obligation says the indication occurs when the sequence finishes,
        # so evaluate after the sequence-activation state. The obligation
        # requires the response, so an incomplete non-aborted window fails.
        completion = eventually(window, ack, strong=True, after_activation=True)
        if completion[0] is None:
            verdicts.append((None, completion[1],
                             'command sequence did not reach a witnessed completion before the trace ended or was aborted'))
            continue
        if completion[0] is False:
            verdicts.append(completion)
            continue

        start_index = window.rows[0]['index']
        candidates = [
            i for i, row in enumerate(trace)
            if row['index'] > start_index and ack(row)
        ]
        if not candidates:
            verdicts.append((None, window.edge,
                             'command completion was not observable in the remaining trace'))
            continue

        first = candidates[0]
        run_start = first
        while run_start > 0 and ack(trace[run_start - 1]):
            run_start -= 1
        if trace[run_start]['index'] <= start_index:
            verdicts.append((False, trace[first]['edge'],
                             'cmd_ack was already high before command completion'))
            continue

        duration = 0
        j = run_start
        while j < len(trace) and ack(trace[j]):
            duration += trace[j]['held']
            j += 1

        if j == len(trace):
            verdicts.append((None, trace[first]['edge'],
                             'cmd_ack remained high at trace end; its one-clock duration was not fully observable'))
        elif duration != 1:
            verdicts.append((False, trace[first]['edge'],
                             f'cmd_ack was high for {duration} clk edges, expected exactly one'))
        else:
            verdicts.append((True, trace[first]['edge'],
                             'cmd_ack was asserted for exactly one clk cycle when the command finished'))

    return worst(verdicts)

