def decide(trace):
    valid_cmds = (1, 2, 4, 8)

    def accepted(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (
            inputs.get('cmd') in valid_cmds
            and inputs.get('ena') == 1
            and outputs.get('idle') == 1
            and outputs.get('clk_en') == 1
        )

    def ack(row):
        return row.get('outputs', {}).get('cmd_ack') == 1

    windows = after(trace, accepted, until=ack)
    verdicts = []

    for window in windows:
        completion = eventually(
            window,
            ack,
            strong=True,
            after_activation=True,
        )
        if completion[0] is not True:
            verdicts.append(completion)
            continue

        ack_row = next((row for row in window.rows if ack(row)), None)
        if ack_row is None:
            verdicts.append((None, window.edge, 'cmd_ack completion was not observable after command acceptance'))
            continue

        rows = iter(trace)
        found_ack = False
        asserted_edges = 0
        ended_while_asserted = False

        for row in rows:
            if not found_ack:
                if row is not ack_row:
                    continue
                found_ack = True

            if not ack(row):
                break

            asserted_edges += row.get('held', 1)
        else:
            if found_ack:
                ended_while_asserted = True

        if asserted_edges != 1:
            verdicts.append((
                False,
                ack_row.get('edge'),
                f"cmd_ack was asserted for {asserted_edges} clk edges; the requirement states exactly one clk cycle",
            ))
        elif ended_while_asserted:
            verdicts.append((
                None,
                ack_row.get('edge'),
                'cmd_ack was high for one observed clk edge, but its deassertion was not observable before the trace ended',
            ))
        else:
            verdicts.append((
                True,
                ack_row.get('edge'),
                'cmd_ack was asserted for exactly one clk cycle when the command sequence finished',
            ))

    return worst(verdicts)

