def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

    def value(row, port):
        if port in row.get('outputs', {}):
            return row['outputs'][port]
        return row.get('inputs', {}).get(port)

    def holds(conditions):
        return lambda row: all(value(row, port) == expected
                               for port, expected in conditions.items())

    starts = after(
        trace,
        holds({'sta_condition': 1}),
        until=holds({'sto_condition': 1}),
        aborts=lambda row: value(row, 'nReset') == 0 or value(row, 'rst') == 1
    )

    verdicts = []
    for window in starts:
        # busy remains set after START until the STOP condition closes the window.
        verdicts.append(
            throughout(
                window,
                lambda row: value(row, 'busy') == 1,
                after_activation=True
            )
        )

        stop_rows = [
            row for row in window.rows
            if value(row, 'sto_condition') == 1
        ]
        if stop_rows:
            stop_index = stop_rows[0]['index']
            after_stop = after(
                trace,
                lambda row, stop_index=stop_index: row['index'] == stop_index,
                until=TO_END,
                aborts=lambda row: value(row, 'nReset') == 0 or value(row, 'rst') == 1
            )
            verdicts.extend(
                eventually(
                    stop_window,
                    lambda row: value(row, 'busy') == 0,
                    strong=True,
                    after_activation=True
                )
                for stop_window in after_stop
            )

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, throughout, worst

    def holds(cond):
        def predicate(row):
            for port, value in cond.items():
                values = row.get('outputs', {})
                if port not in values:
                    values = row.get('inputs', {})
                if values.get(port) != value:
                    return False
            return True
        return predicate

    def any_condition(conditions):
        predicates = [holds(condition) for condition in conditions]
        return lambda row: any(predicate(row) for predicate in predicates)

    starts = after(
        trace,
        any_condition([{'sta_condition': 1}]),
        until=any_condition([{'sto_condition': 1}]),
        aborts=any_condition([{'nReset': 0}, {'rst': 1}])
    )

    verdicts = []
    for window in starts:
        verdicts.append(
            throughout(
                window,
                lambda row: row.get('outputs', {}).get('busy') == 1,
                after_activation=True
            )
        )

        if not window.closed:
            continue

        start_edge = window.edge
        stop_index = None
        for index, row in enumerate(trace):
            if row.get('edge') <= start_edge:
                continue
            if row.get('outputs', {}).get('sto_condition') == 1:
                stop_index = index
                break

        if stop_index is None:
            continue

        following = trace[stop_index + 1:]
        if not following:
            verdicts.append((None, trace[stop_index].get('edge'), 'STOP was detected but no later state was observed'))
            continue

        reset_index = None
        low_row = None
        for index, row in enumerate(following):
            inputs = row.get('inputs', {})
            if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
                reset_index = index
                break
            if row.get('outputs', {}).get('busy') == 0:
                low_row = row
                break

        if low_row is not None:
            verdicts.append((True, low_row.get('edge'), 'busy cleared after the detected STOP condition'))
        elif reset_index is not None:
            verdicts.append((None, following[reset_index].get('edge'), 'reset aborted observation after STOP'))
        else:
            verdicts.append((False, following[0].get('edge'), 'busy remained high after the detected STOP condition'))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def value(row, port):
        if port in row.get('outputs', {}):
            return row['outputs'][port]
        return row.get('inputs', {}).get(port)

    def holds(conditions):
        return lambda row: all(value(row, port) == expected
                               for port, expected in conditions.items())

    starts = after(
        trace,
        holds({'sta_condition': 1}),
        until=holds({'sto_condition': 1}),
        aborts=lambda row: value(row, 'nReset') == 0 or value(row, 'rst') == 1
    )

    verdicts = []
    for window in starts:
        start_pos = next(
            (i for i, row in enumerate(trace) if row.get('edge') == window.edge),
            None
        )
        if start_pos is None:
            verdicts.append((None, window.edge, 'START activation could not be located'))
            continue

        stop_pos = next(
            (i for i in range(start_pos + 1, len(trace))
             if value(trace[i], 'sto_condition') == 1),
            None
        )

        # A STOP closes the transaction.  If no STOP was observed, the
        # transaction is incomplete and its later evidence is unknown.
        end_pos = stop_pos if stop_pos is not None else len(trace)
        high_pos = next(
            (i for i in range(start_pos + 1, end_pos + 1)
             if value(trace[i], 'busy') == 1),
            None
        )

        if high_pos is None:
            if stop_pos is None:
                verdicts.append((None, window.edge,
                                 'busy was not observed high before the incomplete START transaction ended'))
            else:
                verdicts.append((False, trace[stop_pos]['edge'],
                                 'busy did not become high after START before STOP was detected'))
            continue

        dropped_before_stop = next(
            (i for i in range(high_pos + 1, end_pos)
             if value(trace[i], 'busy') != 1),
            None
        )
        if dropped_before_stop is not None:
            verdicts.append((False, trace[dropped_before_stop]['edge'],
                             'busy cleared before the STOP condition was detected'))
            continue

        if stop_pos is None:
            verdicts.append((None, trace[high_pos]['edge'],
                             'busy became high, but no STOP condition completed the transaction'))
            continue

        low_pos = next(
            (i for i in range(stop_pos + 1, len(trace))
             if value(trace[i], 'busy') == 0),
            None
        )
        if low_pos is None:
            verdicts.append((False, trace[stop_pos]['edge'],
                             'busy did not clear after the STOP condition was detected'))
        else:
            verdicts.append((True, trace[low_pos]['edge'],
                             'busy became high after START, remained set through STOP, and cleared afterward'))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, throughout, worst

    def value(row, port):
        if port in row.get('outputs', {}):
            return row['outputs'][port]
        return row.get('inputs', {}).get(port)

    def holds(port, expected):
        return lambda row: value(row, port) == expected

    def aborted(row):
        return value(row, 'nReset') == 0 or value(row, 'rst') == 1

    start_windows = after(
        trace,
        holds('sta_condition', 1),
        until=holds('sto_condition', 1),
        aborts=aborted
    )

    verdicts = []
    for window in start_windows:
        start_pos = next(
            (i for i, row in enumerate(trace)
             if row.get('edge') == window.edge),
            None
        )
        if start_pos is None:
            verdicts.append((None, window.edge,
                             'START activation could not be located'))
            continue

        stop_pos = next(
            (i for i in range(start_pos + 1, len(trace))
             if value(trace[i], 'sto_condition') == 1),
            None
        )

        # busy must be high after START and remain high until STOP.
        if stop_pos is None:
            active_end = len(trace)
            active_rows = trace[start_pos + 1:active_end]
            if any(value(row, 'busy') != 1 for row in active_rows):
                bad = next(row for row in active_rows
                           if value(row, 'busy') != 1)
                verdicts.append((False, bad['edge'],
                                 'busy was not continuously set after START'))
            else:
                verdicts.append((None, window.edge,
                                 'START occurred but no STOP completed the transaction'))
            continue

        active_rows = trace[start_pos + 1:stop_pos]
        bad = next((row for row in active_rows
                    if value(row, 'busy') != 1), None)
        if bad is not None:
            verdicts.append((False, bad['edge'],
                             'busy was not set throughout the interval after START and before STOP'))
            continue

        # The STOP condition itself is the trigger for clearing; search only
        # distinct states after it and do not require a fixed latency.
        clear_pos = next(
            (i for i in range(stop_pos + 1, len(trace))
             if value(trace[i], 'busy') == 0),
            None
        )
        if clear_pos is None:
            if stop_pos + 1 >= len(trace):
                verdicts.append((None, trace[stop_pos]['edge'],
                                 'STOP was detected but the trace ended before busy could be observed cleared'))
            else:
                verdicts.append((False, trace[stop_pos]['edge'],
                                 'busy did not clear after STOP'))
        else:
            verdicts.append((True, trace[clear_pos]['edge'],
                             'busy was set after START, remained set until STOP, and cleared afterward'))

    return worst(verdicts)

