            verdicts.append((None, trace[stop_pos]['edge'],
                             'STOP was detected but the trace ended before busy was observed cleared'))
        else:
            verdicts.append((True, trace[clear_pos]['edge'],
                             'busy became set after START and cleared after STOP'))

    return worst(verdicts)

