def decide(trace):
    def is_reset(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    def activation(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        if inputs.get('ena') != 1 or inputs.get('cmd') not in (1, 4, 8):
            return False

        arbitration_loss = (
            outputs.get('sda_chk') == 1 and
            outputs.get('sda_oen') == 1 and
            outputs.get('ssda') == 0
        )
        unexpected_stop = (
            outputs.get('fsm_active') == 1 and
            outputs.get('sto_condition') == 1
        )
        return arbitration_loss or unexpected_stop

    attempts = []
    previous = False

    for i, row in enumerate(trace):
        current = activation(row) and not is_reset(row)
        if current and not previous:
            attempts.append(i)
        previous = current

    if not attempts:
        return (None, None, 'the arbitration-loss activation never occurred')

    saw_true = False
    for start in attempts:
        for j in range(start + 1, len(trace)):
            row = trace[j]
            if is_reset(row):
                break
            if row.get('outputs', {}).get('al') == 1:
                saw_true = True
                break
        else:
            return (
                False,
                trace[start].get('edge'),
                'arbitration loss was detected, but al did not assert afterward'
            )

    if saw_true:
        return (True, None, 'al asserted after the detected arbitration-loss condition')
    return (None, None, 'all arbitration-loss attempts were aborted by reset')

