    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def reset(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def applies(row):
        if reset(row) or inp(row, 'ena') != 1 or out(row, 'fsm_active') != 1:
            return False

        arbitration_loss = (
            out(row, 'sda_chk') == 1 and
            out(row, 'sda_oen') == 1 and
            out(row, 'ssda') == 0
        )
        unexpected_stop = (
            out(row, 'sto_condition') == 1 and
            out(row, 'stop_sequence') != 1
        )
        return arbitration_loss or unexpected_stop

    attempts = []
    previous = False
    for i, row in enumerate(trace):
        active = applies(row)
        if active and not previous:
            attempts.append(i)
        previous = active

    if not attempts:
        return (None, None, 'arbitration-loss situation never occurred')

    for start in attempts:
        for j in range(start + 1, len(trace)):
            row = trace[j]
            if reset(row):
                break
            if out(row, 'al') == 1:
                return (True, row.get('edge'), 'al asserted after the detected arbitration loss')
        else:
            return (False, trace[start].get('edge'), 'al was not asserted after the detected arbitration loss')

