            and row['inputs'].get('ena') == 1
        ]
        if not samples:
            continue

        for row in samples:
            dout = out(row, 'dout')
            received = out(row, 'ssda')
            if dout != received:
                verdicts.append(
                    (False, row['edge'],
                     f"dout={dout} at the filtered SCL rising data-sampling event; "
                     f"received filtered SDA bit was {received}")
