def decide(trace):
    activations = []
    previous = None

    for row in trace:
        outputs = row.get('outputs', {})
        ena = row.get('inputs', {}).get('ena')
        current_rising = outputs.get('filtered_scl_rising')

        if (previous is not None
                and previous == 0
                and current_rising == 1
                and ena == 1):
            activations.append(row)

        previous = current_rising

    if not activations:
        return (None, None,
                'filtered SCL never rose while ena was high; no capture event occurred')

    for row in activations:
        outputs = row.get('outputs', {})
        dout = outputs.get('dout')
        filtered_sda = outputs.get('ssda')
        if dout != filtered_sda:
            return (False, row.get('edge'),
                    f'dout was {dout} at the filtered SCL rising edge, expected filtered SDA ssda={filtered_sda}')

    return (True, activations[-1].get('edge'),
            f'dout captured filtered SDA on {len(activations)} filtered SCL rising edge(s)')

def decide(trace):
    rising_edges = set()
    for i in range(1, len(trace)):
        previous = trace[i - 1]["outputs"].get("filtered_scl_rising")
        current = trace[i]["outputs"].get("filtered_scl_rising")
        if previous == 0 and current == 1:
            rising_edges.add(trace[i]["edge"])

    events = [
        row for row in trace
        if row["inputs"].get("ena") == 1
        and row["edge"] in rising_edges
    ]

    if not events:
        return (None, None, "no filtered SCL rising edge occurred while ena was high")

    for row in events:
        dout = row["outputs"].get("dout")
        filtered_sda = row["outputs"].get("ssda")
        if dout != filtered_sda:
            return (
                False,
                row["edge"],
                f"dout was {dout}, expected the captured filtered SDA value {filtered_sda} on the filtered SCL rising edge"
            )

    return (
