def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def probe(name):
        return lambda r: r['outputs'].get(name) == 1

    def released_sda(w):
        return eventually(
            w,
            lambda r: r['outputs'].get('sda_oen') == 1,
            after_activation=False,
            strong=False,
        )

    windows = []
    for state in ('start_sequence', 'stop_sequence', 'read_sequence'):
        active = probe(state)
        windows.extend(after(
            trace,
            active,
            until=lambda r, active=active: not active(r),
        ))

    write_active = lambda r: (
        r['outputs'].get('write_sequence') == 1
        and r['inputs'].get('din') == 1
    )
    windows.extend(after(
        trace,
        write_active,
        until=lambda r: r['outputs'].get('write_sequence') != 1,
    ))

    if not windows:
        return (None, None, 'no declared command-sequence probe reached an SDA release situation')

    verdict = worst([released_sda(w) for w in windows])
    if verdict[0] is False:
        return (False, verdict[1], 'SDA was not released high during a sequence requiring the external pull-up to provide the high level')
    if verdict[0] is None:
        return (None, verdict[1], 'the released-line window was incomplete before the trace ended')
    return (True, verdict[1], 'sda_oen was high during each observed SDA release situation, allowing the external pull-up to provide the high level')

