    # not merely while the idle released value of scl_oen is present.
    stretch_rises = set()
    for i in range(1, len(trace)):
        previous = out(trace[i - 1], 'slave_wait')
        current = out(trace[i], 'slave_wait')
        if previous != 1 and current == 1:
            stretch_rises.add(trace[i]['edge'])

    def stretch_begins(row):
        return (
            row['edge'] in stretch_rises
            and inp(row, 'cmd') in (1, 2, 4, 8)
            and inp(row, 'ena') == 1
            and out(row, 'fsm_active') == 1
            and out(row, 'scl_oen') == 1
            and out(row, 'sscl') == 0
        )

    def aborted(row):
        return (
            out(row, 'al') == 1
            or inp(row, 'nReset') == 0
            or inp(row, 'rst') == 1
        )

    windows = after(
        trace,
        stretch_begins,
        until=lambda row: out(row, 'sscl') == 1,
        aborts=aborted,
    )

    if not windows:
        return (None, None, 'no active slave-clock-stretch entry was observed')

    unknown = None
    for window in windows:
        paused = throughout(
            window,
            lambda row: out(row, 'scl_oen') == 1,
            after_activation=True,
        )
        if paused[0] is False:
            return paused
        if paused[0] is None:
            unknown = paused
            continue

        last_index = window.rows[-1]['index'] if window.rows else window.rows
        release = None
        for row in trace:
            if row['index'] > last_index and out(row, 'sscl') == 1:
                release = row
                break

        if release is None:
            unknown = (
                None,
                window.edge,
                'filtered SCL release was not observed before the trace ended',
            )
            continue

        resumed = None
        for i, row in enumerate(trace):
            if row['index'] < release['index']:
                continue
            if i > 0 and out(trace[i - 1], 'scl_oen') == 1 and out(row, 'scl_oen') == 0:
                resumed = row
                break

        if resumed is None:
            unknown = (
                None,
                release['edge'],
                'stretch was paused correctly, but later scl_oen progression was not observed',
            )
        else:
            unknown = None

    if unknown is not None:
        return unknown
    return (True, None, 'scl_oen remained released during each stretch and timing progression resumed after SCL release')

