def decide(trace):
    saw_condition = False

    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        prev_outputs = prev.get('outputs', {})

        sscl_fell = (prev_outputs.get('sscl') == 1
                     and outputs.get('sscl') == 0)
        released_now = (prev_outputs.get('scl_oen') == 0
                        and outputs.get('scl_oen') == 1)

        if not sscl_fell or inputs.get('ena') != 1:
            continue

        # Require that release was an observed action in this trace, not
        # merely the initial idle/reset value of the active-low enable.
        released_before_fall = released_now or any(
            trace[j - 1].get('outputs', {}).get('scl_oen') == 0
            and trace[j].get('outputs', {}).get('scl_oen') == 1
            for j in range(1, i)
        )
        if not released_before_fall or outputs.get('scl_oen') != 1:
            continue

        saw_condition = True
        if outputs.get('scl_sync') == 1:
            return (True, row.get('edge'),
                    'scl_sync asserted when filtered SCL fell after the controller released SCL, indicating another master forced SCL low')
        return (False, row.get('edge'),
                'filtered SCL fell after the controller released SCL, but scl_sync was not asserted')

    if not saw_condition:
        return (None, None,
                'no filtered SCL falling edge occurred after an observed release of SCL while ena was high')

    return (None, None, 'the qualifying condition was not reached')

