def decide(trace):
    from specflow.refmodel.temporal import edges

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def active_enabled(row):
        return (row.get('inputs', {}).get('ena') == 1
                and out(row, 'fsm_active') == 1)

    scl_falls = edges(trace, 'scl_i', 'fall')
    scl_rises = edges(trace, 'scl_i', 'rise')
    scloen_falls = edges(trace, 'scl_oen', 'fall')

    forced = [
        i for i, row in enumerate(trace)
        if row.get('edge') in scl_falls
        and out(row, 'scl_oen') == 1
        and active_enabled(row)
    ]

    # An ordinary released-SCL phase is a scl_oen falling transition whose
    # current release interval contained no external SCL falling edge.
    ordinary = []
    for i, row in enumerate(trace):
        if row.get('edge') not in scloen_falls or not active_enabled(row):
            continue
        if row.get('inputs', {}).get('scl_i') != 1:
            continue
        j = i - 1
        saw_external_fall = False
        while j >= 0 and out(trace[j], 'scl_oen') == 1:
            if (trace[j].get('edge') in scl_falls
                    and active_enabled(trace[j])):
                saw_external_fall = True
                break
            j -= 1
        if not saw_external_fall:
            ordinary.append(i)

    if not forced:
        return (None, None,
                'no enabled active released-SCL external falling edge occurred')
    if not ordinary:
        return (None, None,
                'the trace shows the synchronized case but no ordinary released-SCL case for comparison')

    for fi in forced:
        rise_i = None
        for i in range(fi + 1, len(trace)):
            if trace[i].get('edge') in scl_rises:
                rise_i = i
                break

        if rise_i is None:
            return (None, trace[fi].get('edge'),
                    'external SCL remained low; the synchronized timing window did not close')

        # The released line must remain released during the externally forced
        # low interval; an immediate drive-low transition skips the restart.
        for i in range(fi, rise_i + 1):
            if out(trace[i], 'scl_oen') != 1:
                return (False, trace[i].get('edge'),
                        'scl_oen was not released throughout the externally forced-low interval')

        # After SCL returns high, the restarted low-period timing must permit
        # the next active phase transition, without requiring a fixed latency.
        completed = False
        for i in range(rise_i + 1, len(trace)):
            if (trace[i].get('edge') in scloen_falls
                    and active_enabled(trace[i])):
                completed = True
                break
        if not completed:
            return (False, trace[rise_i].get('edge'),
                    'scl_oen did not reach the next active phase after synchronized SCL release')

    return (True, None,
            'scl_oen remained released during the externally forced low period and then transitioned after SCL returned high; ordinary released-SCL timing was also present')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    activations = []
    for i, row in enumerate(trace):
        # A filtered falling edge is the declared situation in which another
        # master has forced a released SCL low.  Raw scl_i levels alone would
        # also match unfiltered glitches and unrelated low-level stretches.
        if (out(row, 'filtered_scl_falling') == 1
                and row.get('inputs', {}).get('ena') == 1
                and out(row, 'fsm_active') == 1
                and out(row, 'scl_oen') == 1):
            activations.append(i)

    if not activations:
        return (None, None,
                'no enabled active command had a filtered SCL falling edge while scl_oen was released')

    incomplete = None
    for start in activations:
        rise = None
        for j in range(start + 1, len(trace)):
            if out(trace[j], 'filtered_scl_rising') == 1:
                rise = j
                break

        if rise is None:
            if incomplete is None:
                incomplete = trace[start].get('edge')
            continue

        # The synchronized low-period interval must not be interrupted by
        # driving SCL low again.  No duration or cycle count is imposed.
        for j in range(start, rise):
            if out(trace[j], 'scl_oen') != 1:
                return (False, trace[j].get('edge'),
                        'scl_oen was not released throughout the synchronized low-period interval')

        # The route describes a later phase-boundary change, but the
        # specification fixes neither its latency nor the number of states.
        # Accept any later scl_oen change; an unfinished trace is unknown.
        changed = None
        old = out(trace[rise], 'scl_oen')
        for j in range(rise + 1, len(trace)):
            if out(trace[j], 'scl_oen') != old:
                changed = j
                break

        if changed is not None:
            return (True, trace[changed].get('edge'),
                    'scl_oen remained released through the filtered low period and changed after SCL rose')

        if incomplete is None:
            incomplete = trace[start].get('edge')

    return (None, incomplete,
            'the synchronized low-period interval was observed, but the later phase-boundary change was not present before the trace ended')

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst, edges, TO_END

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    falling = edges(trace, 'scl_i', 'fall')
    activations = after(
        trace,
        lambda r: (
            r.get('edge') in falling
            and inp(r, 'ena') == 1
            and out(r, 'fsm_active') == 1
            and out(r, 'scl_oen') == 1
        ),
        until=TO_END
    )

    if not activations:
        return (None, None,
                'no enabled active command observed an external SCL falling edge while scl_oen was released')

    verdicts = []
    for window in activations:
        rise_index = None
        for row in window.rows:
            if out(row, 'filtered_scl_rising') == 1:
                rise_index = row.get('index')
                break

        if rise_index is None:
            verdicts.append((None, window.edge,
                             'the synchronized low-period window did not reach a filtered SCL rising boundary before the trace ended'))
            continue

        low_window = after(
            trace,
            lambda r, edge=window.edge: r.get('edge') == edge,
            until=lambda r: out(r, 'filtered_scl_rising') == 1
        )
        if not low_window:
            verdicts.append((None, window.edge,
                             'the synchronized low-period window could not be formed'))
            continue

        held = throughout(
            low_window[0],
            lambda r: out(r, 'scl_oen') == 1
        )
        if held[0] is False:
            verdicts.append((False, held[1],
                             'scl_oen was not held released through the synchronized low-period timing'))
            continue
        if held[0] is None:
            verdicts.append(held)
            continue

        response = after(
            trace,
            lambda r, edge=rise_index: r.get('index') == edge,
            until=TO_END
        )
        changed = None
        for row in response[0].rows if response else []:
            if row.get('index') > rise_index and out(row, 'scl_oen') != 1:
                changed = row
                break

        if changed is None:
            verdicts.append((False, rise_index,
                             'scl_oen remained released after the synchronized low period instead of changing at the next SCL phase boundary'))
        else:
            verdicts.append((True, changed.get('edge'),
                             'scl_oen remained released through the synchronized low period and changed after the filtered SCL rising boundary'))

    return worst(verdicts)

