def decide(trace):
    active = lambda r: r['inputs'].get('nReset') == 1 and r['inputs'].get('rst') == 0

    rows = [r for r in trace if active(r)]
    if not rows:
        return (None, None, 'normal controller operation never occurred')

    unresolved = False
    transitions = 0

    for inp, sync in (("scl_i", "cscl"), ("sda_i", "csda")):
        previous = None
        for i, row in enumerate(rows):
            value = row['inputs'].get(inp)
            if previous is None:
                previous = value
                continue
            if value == previous:
                continue

            transitions += 1
            changed_at = row['edge']
            found = False
            j = i + 1
            while j < len(rows):
                later = rows[j]
                if later['inputs'].get(inp) != value:
                    break
                if later['outputs'].get(sync) == value:
                    found = True
                    break
                j += 1

            if not found:
                unresolved = True
            previous = value

    if transitions == 0:
        return (None, None, 'no raw scl_i or sda_i transition occurred during normal operation')
    if unresolved:
        return (None, rows[-1]['edge'], 'a raw transition occurred, but propagation to cscl/csda was not observable before the input changed or the trace ended')
    return (True, None, 'all observed raw scl_i and sda_i transitions were subsequently captured by cscl/csda')

