def decide(trace):
    # These declared probes are observable, but fscl and fsda do not expose
    # the three history samples needed to compute their majority values.
    for row in trace:
        _ = row['outputs'].get('sscl')
        _ = row['outputs'].get('ssda')
        _ = row['outputs'].get('fscl')
        _ = row['outputs'].get('fsda')
