def decide(trace):
    fscl_samples = []
    fsda_samples = []
    checked = False
    previous_filter_cnt = 0

    for row in trace:
        outputs = row.get('outputs', {})
        filter_cnt = outputs.get('filter_cnt')
        sample_event = bool(filter_cnt) and not bool(previous_filter_cnt)
        previous_filter_cnt = filter_cnt

        if not sample_event:
            continue

        fscl_samples.append(outputs.get('fscl'))
        fsda_samples.append(outputs.get('fsda'))
        if len(fscl_samples) > 3:
            fscl_samples.pop(0)
        if len(fsda_samples) > 3:
            fsda_samples.pop(0)

        if len(fscl_samples) < 3 or len(fsda_samples) < 3:
            continue

        checked = True
        expected_sscl = 1 if sum(fscl_samples) >= 2 else 0
        expected_ssda = 1 if sum(fsda_samples) >= 2 else 0
        actual_sscl = outputs.get('sscl')
        actual_ssda = outputs.get('ssda')

        if actual_sscl != expected_sscl or actual_ssda != expected_ssda:
            return (
                False,
                row.get('edge'),
                'majority mismatch: sscl=%r expected majority(fscl)=%r; '
                'ssda=%r expected majority(fsda)=%r' %
                (actual_sscl, expected_sscl, actual_ssda, expected_ssda)
            )

    if not checked:
        return (None, None, 'fewer than three declared filter samples were observed')
    return (True, None, 'sscl and ssda matched the majority of the three latest fscl and fsda samples')

def decide(trace):
    # The declared fscl/fsda probes expose the sampled history values one at
    # a time, while the specification states that the histories initialize
    # high. Reconstruct the three-sample histories in trace order.
    if not any(row.get('outputs', {}).get('sscl') == 1 for row in trace):
        return (None, None, 'sscl never reached the filtering state')

    hist_scl = [1, 1, 1]
    hist_sda = [1, 1, 1]
    started = False

    for row in trace:
        outputs = row.get('outputs', {})
        if not started:
            if outputs.get('sscl') != 1:
                continue
            started = True

        fscl = outputs.get('fscl')
        fsda = outputs.get('fsda')
        sscl = outputs.get('sscl')
        ssda = outputs.get('ssda')
        if fscl not in (0, 1) or fsda not in (0, 1):
            return (None, row.get('edge'), 'fscl/fsda history samples are unavailable')

        hist_scl = hist_scl[1:] + [fscl]
        hist_sda = hist_sda[1:] + [fsda]
        majority_scl = 1 if sum(hist_scl) >= 2 else 0
        majority_sda = 1 if sum(hist_sda) >= 2 else 0

        if sscl != majority_scl:
            return (False, row.get('edge'), f'sscl={sscl} is not the majority of fscl history {hist_scl}')
        if ssda != majority_sda:
            return (False, row.get('edge'), f'ssda={ssda} is not the majority of fsda history {hist_sda}')

    return (True, None, 'sscl and ssda match the majority of their reconstructed three-sample histories')

