    # `filter_cnt` is the declared probe for the filter-counter expiry/update
    # situation.  Treat its rising observations as sample-update events; a
    # held probe value does not represent additional history samples.
    updates = []
    previous = 0
    for i, row in enumerate(trace):
        outputs = row.get('outputs', {})
        active = outputs.get('filter_cnt') == 1
        if active and previous != 1:
            updates.append(i)
        previous = 1 if active else 0

    if not updates:
        return (None, None, 'the filter-counter update situation never occurred')

    samples_scl = []
    samples_sda = []
    intervals = []

    for n, start in enumerate(updates):
        row = trace[start]
        outputs = row.get('outputs', {})
        fscl = outputs.get('fscl')
        fsda = outputs.get('fsda')
        if fscl not in (0, 1) or fsda not in (0, 1):
            return (None, row.get('edge'), 'filter history samples are unavailable')

        samples_scl.append(fscl)
        samples_sda.append(fsda)
        if len(samples_scl) < 3:
            continue

        end = updates[n + 1] if n + 1 < len(updates) else None
        intervals.append((start, end,
                          1 if sum(samples_scl[-3:]) >= 2 else 0,
                          1 if sum(samples_sda[-3:]) >= 2 else 0))

    if not intervals:
        return (None, None, 'fewer than three filter-update samples were observed')

    for start, end, expected_scl, expected_sda in intervals:
        stop = end if end is not None else len(trace)
        matching = False
        for i in range(start, stop):
            outputs = trace[i].get('outputs', {})
            if (outputs.get('sscl') == expected_scl and
                    outputs.get('ssda') == expected_sda):
                matching = True
                break
        if not matching:
            if end is None:
                return (None, trace[start].get('edge'),
                        'the final filter interval ended before the majority value was observable')
            return (False, trace[start].get('edge'),
                    f'sscl/ssda did not reach the majority values '
                    f'{expected_scl}/{expected_sda} for the last three filter samples')

    return (True, None, 'filtered SCL and SDA reached the majority values of each observed three-sample history')

