def decide(trace):
    def out(row, port):
        return row.get('outputs', {}).get(port, row.get('inputs', {}).get(port))

    def rising(port, i):
        return out(trace[i], port) == 1 and (i == 0 or out(trace[i - 1], port) != 1)

    starts = []
    for i, row in enumerate(trace):
        if (out(row, 'ena') == 1 and
                out(row, 'nReset') != 0 and
                out(row, 'rst') != 1 and
                out(row, 'idle') == 1 and
                rising('sta_condition', i)):
            starts.append(i)

    if not starts:
        return (None, None, 'no filtered START condition while the controller was idle')

    for start in starts:
        busy_index = None
        stop_index = None

        for j in range(start + 1, len(trace)):
            if out(trace[j], 'nReset') == 0 or out(trace[j], 'rst') == 1:
                break
            if rising('sto_condition', j):
                stop_index = j
                break
            if out(trace[j], 'busy') == 1 and busy_index is None:
                busy_index = j

        if stop_index is None:
            return (None, trace[start].get('edge'),
                    'filtered START occurred, but the transaction did not reach a filtered STOP')

        if busy_index is None:
            return (False, trace[stop_index].get('edge'),
                    'busy never became high between the filtered START and STOP conditions')

        for j in range(busy_index, stop_index):
            if out(trace[j], 'busy') != 1:
                return (False, trace[j].get('edge'),
                        'busy dropped before the filtered STOP condition')

    return (True, None, 'busy became high after each filtered idle START and remained high until STOP')

