    start_edges = edges(trace, 'sta_condition', 'rise')

    def starts(row):
        return value(row, 'ena') == 1 and row.get('edge') in start_edges

    def stops(row):
        return value(row, 'sto_condition') == 1

    def reset(row):
        return (value(row, 'nReset') == 0 or
                value(row, 'rst') == 1)

    windows = after(trace, starts, until=stops, aborts=reset)
