def decide(trace):
    from specflow.refmodel.temporal import after, worst

    def value(row, port):
        if port in row.get('outputs', {}):
            return row['outputs'][port]
        return row.get('inputs', {}).get(port)

    def starts(row):
        return (value(row, 'ena') == 1 and
                value(row, 'sta_condition') == 1)

    def stops(row):
        return value(row, 'sto_condition') == 1

    def reset(row):
        return (value(row, 'nReset') == 0 or
                value(row, 'rst') == 1)

    windows = after(trace, starts, until=stops, aborts=reset)
    verdicts = []

    for window in windows:
        rows = window.rows
        stop_at = None
        for pos, row in enumerate(rows):
            if stops(row):
                stop_at = pos
                break
        end = stop_at if stop_at is not None else len(rows)

        # The registered response may appear after any number of distinct
        # states; do not accept the activation row itself as the response.
        first_high = None
        for pos in range(1, end):
            if value(rows[pos], 'busy') == 1:
                first_high = pos
                break

        if first_high is None:
            if window.closed:
                verdicts.append((False, window.edge,
                                 'busy never became high after the filtered START condition'))
            else:
                verdicts.append((None, window.edge,
                                 'busy response not observed before the trace ended'))
            continue

        bad = None
        for pos in range(first_high, end):
            if value(rows[pos], 'busy') != 1:
                bad = rows[pos]
                break

        if bad is not None:
            verdicts.append((False, bad.get('edge'),
                             'busy fell before the filtered STOP condition'))
        else:
            verdicts.append((True, None,
                             'busy became high after START and remained high until STOP'))

    return worst(verdicts)

