def decide(trace):
    from specflow.refmodel.temporal import after

    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_condition(conditions):
        predicates = [holds(condition) for condition in conditions]
        return lambda row: any(predicate(row) for predicate in predicates)

    previous = None
    read_rises = set()
    for row in trace:
        current = row['outputs'].get('read_sequence')
        if current == 1 and previous != 1:
            read_rises.add(row['edge'])
        previous = current

    windows = after(
        trace,
        lambda row: (
            row['edge'] in read_rises
            and row['inputs'].get('cmd') == 8
            and row['inputs'].get('ena') == 1
        ),
        until=holds({'cmd_ack': 1}),
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1},
        ]),
    )

    if not windows:
        return (None, None, 'dout was not exercised by a READ operation')

    for window in windows:
        if not window.closed:
            return (None, window.edge, 'READ transaction did not complete before the trace ended')

        rows = window.rows[1:]
        samples = [
            row for row in rows
            if row['outputs'].get('filtered_scl_rising') == 1
        ]
        if not samples:
            return (None, window.edge, 'no filtered SCL rising edge occurred in the READ data-sampling window')

        for row in samples:
            dout = row['outputs'].get('dout')
            filtered_sda = row['outputs'].get('ssda')
            if dout != filtered_sda:
                return (
                    False,
                    row['edge'],
                    f'dout was {dout} at the filtered SCL rising edge; expected the received filtered SDA value {filtered_sda}',
                )

    return (True, None, 'dout provided the filtered SDA value on every filtered SCL rising edge in the completed READ operation')

