    # `dout` is the declared observable for this requirement, but the
    # obligation states its purpose rather than a separately checkable effect.
    observed_dout = [row.get('outputs', {}).get('dout') for row in trace]
    if not observed_dout:
        return (None, None, 'dout was not observed; this obligation states no independently checkable effect')
    return (None, None, 'The obligation states the purpose of dout but no independently checkable output effect; filtered-SDA sampling is covered by REQ-0079.')

def decide(trace):
    from specflow.refmodel.temporal import after, edges, worst

    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_condition(conditions):
        predicates = [holds(condition) for condition in conditions]
        return lambda row: any(predicate(row) for predicate in predicates)

    read_starts = edges(trace, 'read_sequence', 'rise')
    sample_events = edges(trace, 'filtered_scl_rising', 'rise')

    windows = after(
        trace,
        lambda row: (
            row['edge'] in read_starts
            and row['inputs'].get('cmd') == 8
            and row['inputs'].get('ena') == 1
        ),
        until=holds({'cmd_ack': 1}),
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1},
        ]),
    )

    if not windows:
        return (None, None, 'no enabled READ operation occurred')

    verdicts = []
    for window in windows:
        samples = [
            row for row in window.rows[1:]
            if row['edge'] in sample_events
        ]

        if not samples:
            verdicts.append(
                (None, window.edge,
                 'no filtered SCL rising edge occurred in the READ sampling window')
            )
            continue

        mismatch = next(
            (
                row for row in samples
                if row['outputs'].get('dout') != row['outputs'].get('ssda')
            ),
            None,
        )
        if mismatch is not None:
            expected = mismatch['outputs'].get('ssda')
            actual = mismatch['outputs'].get('dout')
            verdicts.append(
                (
                    False,
                    mismatch['edge'],
                    f'dout was {actual} at the filtered SCL rising edge; expected the received filtered SDA value {expected}',
                )
            )
        elif not window.closed:
            verdicts.append(
                (None, window.edge,
                 'READ sampling was observed but the transaction did not complete before the trace ended')
            )
        else:
            verdicts.append(
                (
                    True,
                    samples[-1]['edge'],
                    'dout provided the filtered SDA value at every filtered SCL rising edge during the READ operation',
                )
            )

    return worst(verdicts)

