def decide(trace):
    from specflow.refmodel.temporal import edges

    state_ports = (
        'idle',
        'fsm_active',
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    changed_edges = set()
    for port in state_ports:
        changed_edges.update(edges(trace, port, 'change'))

    eligible = False
    previous_reset = True
    for row in trace:
        inputs = row.get('inputs', {})
        current_reset = reset_active(row)

        if inputs.get('ena') == 1 and not current_reset:
            eligible = True

        if (
            row.get('edge') in changed_edges
            and inputs.get('ena') == 1
            and not current_reset
            and not previous_reset
            and row.get('outputs', {}).get('clk_en') != 1
        ):
            return (
                False,
                row.get('edge'),
                'FSM state changed while `clk_en` was not asserted; '
                'the clause requires: "The FSM advances only when `clk_en` is asserted."'
            )

        previous_reset = current_reset

    if not eligible:
        return (None, None, 'the enabled, non-reset command-FSM situation never occurred')

    return (
        True,
        None,
        'every observed enabled, non-reset command-FSM state change occurred '
        'on a row where `clk_en` was asserted'
    )

