        'read_sequence',
        'write_sequence',
    )

    changed_edges = set()
    for port in state_ports:
        changed_edges.update(edges(trace, port, 'change'))

    enabled_transition_seen = False
    for row in trace:
        if row.get('edge') not in changed_edges:
            continue
        if row.get('inputs', {}).get('ena') != 1:
