                'the FSM advances only when `clk_en` is asserted'
            )

    if not enabled_transition_seen:
        return (None, None, 'no enabled command-FSM state transition occurred in this trace')

    return (
        True,
        None,
        'every enabled command-FSM state transition occurred while `clk_en` was asserted'
    )

