from specflow.refmodel.temporal import after, sequence, throughout, worst


def decide(trace):
    def out(row, name):
        return row['outputs'].get(name)

    def probe(name):
        return lambda row: out(row, name) == 1

    def phase(scl, sda, chk):
        return lambda row: (out(row, 'scl_oen') == scl and
                            out(row, 'sda_oen') == sda and
                            out(row, 'sda_chk') == chk)

    def any_condition(conditions):
        return lambda row: any(
            all(out(row, port) == value for port, value in condition.items())
            for condition in conditions
        )

    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    def check_window(window, phases, command, require_check=False):
        ordered = sequence(
            window,
            *[phase(scl, sda, chk) for scl, sda, chk in phases],
            strong=True,
            after_activation=True,
        )
        if require_check:
            checking = throughout(
                window,
                lambda row: (out(row, 'sda_chk') == 0 or
                             out(row, 'scl_oen') == 1),
                after_activation=True,
            )
            return worst([ordered, checking])
        quiet = throughout(
            window,
            lambda row: out(row, 'sda_chk') == 0,
            after_activation=True,
        )
        return worst([ordered, quiet])

    windows = []

    for command, sequence_probe, phases, checking in [
        (
            'START',
            'start_sequence',
            [(1, 1, 0), (1, 0, 0), (0, 0, 0)],
            False,
        ),
        (
            'STOP',
            'stop_sequence',
            [(0, 0, 0), (1, 0, 0), (1, 1, 0)],
            False,
        ),
        (
            'READ',
            'read_sequence',
            [(0, 1, 0), (1, 1, 0), (0, 1, 0)],
            False,
        ),
    ]:
        active = after(
            trace,
            probe(sequence_probe),
            until=lambda row: out(row, 'cmd_ack') == 1,
            aborts=aborts,
        )
        windows.extend(
            check_window(w, phases, command, checking) for w in active
        )

    write_windows = after(
        trace,
        probe('write_sequence'),
