def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def terminal(row):
        # These are the final output-enable signatures of the four
        # command sequences.  Sequence probes scope them to the command
        # whose terminal phase is being recognised.
        din = row.get('inputs', {}).get('din')
        return (
            (out(row, 'start_sequence') == 1 and
             out(row, 'scl_oen') == 0 and out(row, 'sda_oen') == 0) or
            (out(row, 'stop_sequence') == 1 and
             out(row, 'scl_oen') == 1 and out(row, 'sda_oen') == 1) or
            (out(row, 'read_sequence') == 1 and
             out(row, 'scl_oen') == 0 and out(row, 'sda_oen') == 1) or
            (out(row, 'write_sequence') == 1 and
             out(row, 'scl_oen') == 0 and
             out(row, 'sda_oen') == (1 if din else 0))
        )

    activations = []
    previous_terminal = False
    for row in trace:
        is_terminal = terminal(row)
        if is_terminal and not previous_terminal:
            activations.append(row['index'])
        previous_terminal = is_terminal

    if not activations:
        return (None, None, 'no supported command reached a terminal timing phase')

    results = []
    for start in activations:
        start_pos = next(i for i, r in enumerate(trace) if r['index'] == start)
        ack_row = None
        aborted = False

        for j in range(start_pos + 1, len(trace)):
            row = trace[j]
            if row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1:
                aborted = True
                break
            if out(row, 'cmd_ack') == 1:
                ack_row = j
                break

        if aborted:
            results.append((None, None, 'terminal-phase attempt was aborted by reset'))
            continue

        if ack_row is None:
            results.append((False, trace[start_pos]['edge'],
                            'cmd_ack did not assert after the terminal command phase'))
            continue

        ack = trace[ack_row]
        if out(ack, 'idle') != 1:
            results.append((False, ack['edge'],
                            'cmd_ack asserted, but the FSM was not idle'))
            continue

        if ack.get('held') != 1:
            results.append((False, ack['edge'],
                            f"cmd_ack was held for {ack.get('held')} edges, expected exactly one clock cycle"))
            continue

        if ack_row + 1 >= len(trace):
            results.append((None, ack['edge'],
                            'cmd_ack was high for one recorded edge, but its deassertion is outside the trace'))
            continue

        following = trace[ack_row + 1]
        if out(following, 'cmd_ack') == 1:
            results.append((False, following['edge'],
                            'cmd_ack remained high beyond the one-clock pulse'))
        else:
            results.append((True, ack['edge'],
                            'FSM returned to idle and cmd_ack pulsed high for exactly one clock cycle'))

    for result in results:
        if result[0] is False:
            return result
    for result in results:
        if result[0] is True:
            return result
    return (None, None, 'all terminal-phase attempts were aborted or incomplete in the trace')

