def decide(trace):
    from specflow.refmodel.temporal import after, sequence, worst

    def holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    # No command encoding table is present.  Use the declared START-sequence
    # probe as the port-level signature of the START situation instead of
    # inventing a numeric cmd encoding.
    starts = lambda row: (
        row['outputs'].get('start_sequence') == 1
        and row['inputs'].get('ena') == 1
    )

    windows = after(
        trace,
        starts,
        until=any_condition([{'cmd_ack': 1}]),
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1}
        ])
    )

    released = holds({'sda_oen': 1, 'scl_oen': 1})
    sda_low_scl_high = holds({'sda_oen': 0, 'scl_oen': 1})
    scl_low = holds({'scl_oen': 0})
    acknowledged = holds({'cmd_ack': 1})

    return worst([
        sequence(
            window,
            released,
            sda_low_scl_high,
            scl_low,
            acknowledged,
            strong=True,
            after_activation=True
        )
        for window in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import edges, worst

    def output(row, name):
        return row.get('outputs', {}).get(name)

    def any_abort(row):
        return (
            output(row, 'al') == 1 or
            row.get('inputs', {}).get('nReset') == 0 or
            row.get('inputs', {}).get('rst') == 1
        )

    start_rises = edges(trace, 'start_sequence', 'rise')
    windows = []

    for i, row in enumerate(trace):
        if row.get('edge') not in start_rises:
            continue

        rows = []
        aborted = False
        closed = False
        for later in trace[i + 1:]:
            if any_abort(later):
                aborted = True
                break
            rows.append(later)
            if output(later, 'cmd_ack') == 1:
                closed = True
                break

        if aborted:
            continue
        windows.append((row, rows, closed))

    if not windows:
        return (None, None, 'START sequence activation never occurred')

    verdicts = []
    for trigger, rows, closed in windows:
        if not rows and not closed:
            verdicts.append((None, trigger.get('edge'), 'START sequence opened but no later state was observed'))
            continue

        release_i = None
        for j, r in enumerate(rows):
            if output(r, 'sda_oen') == 1 and output(r, 'scl_oen') == 1:
                release_i = j
                break

        if release_i is None:
            if not closed:
                verdicts.append((None, trigger.get('edge'), 'START sequence ended before its released SDA/SCL phase was observed'))
            else:
                verdicts.append((False, rows[-1].get('edge'), 'START sequence did not show SDA and SCL released'))
            continue

        sda_low_i = None
        for j in range(release_i + 1, len(rows)):
            previous = rows[j - 1]
            current = rows[j]
            if (
                output(previous, 'sda_oen') != 0 and
                output(current, 'sda_oen') == 0 and
                output(current, 'scl_oen') == 1
            ):
                sda_low_i = j
                break

        if sda_low_i is None:
            if not closed:
                verdicts.append((None, rows[-1].get('edge'), 'START sequence ended before SDA was pulled low while SCL was high'))
            else:
                verdicts.append((False, rows[-1].get('edge'), 'SDA was not pulled low while SCL was high'))
            continue

        scl_low_i = None
        for j in range(sda_low_i + 1, len(rows)):
            previous = rows[j - 1]
            current = rows[j]
            if output(previous, 'scl_oen') != 0 and output(current, 'scl_oen') == 0:
                scl_low_i = j
                break

        if scl_low_i is None:
            if not closed:
                verdicts.append((None, rows[-1].get('edge'), 'START sequence ended before SCL was pulled low'))
            else:
                verdicts.append((False, rows[-1].get('edge'), 'SCL was not pulled low after the START condition'))
            continue

        ack_i = None
        for j in range(scl_low_i, len(rows)):
            if output(rows[j], 'cmd_ack') == 1:
                ack_i = j
                break

        if ack_i is None:
            if not closed:
                verdicts.append((None, rows[-1].get('edge'), 'START sequence ended before cmd_ack was observed'))
            else:
                verdicts.append((False, rows[scl_low_i].get('edge'), 'SCL was pulled low but cmd_ack was not asserted'))
        else:
            verdicts.append((True, rows[ack_i].get('edge'), 'START sequence released both lines, pulled SDA low while SCL was high, then pulled SCL low and acknowledged'))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is True:
            return verdict
    return verdicts[0]

