def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def write_active(row):
        return out(row, 'write_sequence') == 1 and row.get('inputs', {}).get('ena') == 1

    def not_write(row):
        return out(row, 'write_sequence') != 1

    def aborted(row):
        return (out(row, 'al') == 1 or
                row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    windows = after(trace, write_active, until=not_write, aborts=aborted)
    if not windows:
        return (None, None, 'the WRITE sequence never occurred')

    din = None
    for row in trace:
        if write_active(row):
            din = row.get('inputs', {}).get('din')
            break
    if din not in (0, 1):
        return (None, None, 'WRITE activation occurred without a sampled din value')

    expected_sda_oen = 0 if din == 0 else 1
    for window in windows:
        rows = window.rows[1:] if len(window.rows) > 1 else []
        if not rows or not window.closed:
            return (None, window.edge, 'WRITE sequence was not observed to finish before the trace ended')

        high_pos = None
        for i, row in enumerate(rows):
            if out(row, 'scl_oen') == 1:
                high_pos = i
                break
        if high_pos is None:
            return (False, window.edge, 'WRITE sequence never released SCL high')

        low_pos = None
        for i in range(high_pos + 1, len(rows)):
            if out(rows[i], 'scl_oen') == 0:
                low_pos = i
                break
        if low_pos is None:
            return (False, rows[high_pos].get('edge'), 'WRITE sequence did not pull SCL low after releasing it high')

        for row in rows[:low_pos + 1]:
            if out(row, 'sda_oen') != expected_sda_oen:
                return (False, row.get('edge'),
                        f'sda_oen was {out(row, "sda_oen")}, expected {expected_sda_oen} for din={din}')

        high_rows = rows[high_pos:low_pos]
        if not high_rows:
            return (False, rows[high_pos].get('edge'), 'WRITE SCL-high phase was empty')
        for row in high_rows:
            if out(row, 'sda_chk') != 1:
                return (False, row.get('edge'), 'sda_chk was not asserted throughout the SCL-high arbitration-checking phase')

