def decide(trace):
    reset_rows = [
        row for row in trace
        if row.get('inputs', {}).get('nReset') == 0
    ]

    if not reset_rows:
        return (None, None, 'asynchronous reset nReset == 0 never occurred')

    required = {
        'idle': 1,
        'scl_oen': 1,
        'sda_oen': 1,
        'cmd_ack': 0,
        'al': 0,
        'busy': 0,
        'fscl': 1,
        'fsda': 1,
        'sscl': 1,
        'ssda': 1,
    }

    for row in reset_rows:
        outputs = row.get('outputs', {})
        bad = [
            port for port, value in required.items()
            if outputs.get(port) != value
        ]
        if bad:
            details = ', '.join(
                f'{port}={outputs.get(port)!r}, expected {required[port]!r}'
                for port in bad
            )
            return (False, row.get('edge'),
                    f'while nReset == 0, reset state violated: {details}')

    return (True, None,
            'while nReset == 0, FSM is idle, output enables are high, '
            'cmd_ack/al/busy are low, and filtered SCL/SDA state is high')

