def decide(trace):
    reset_rows = []
    previous_rst = 0

    for i, row in enumerate(trace):
        rst = row.get('inputs', {}).get('rst')
        if rst == 1 and (i == 0 or previous_rst != 1):
            reset_rows.append(row)
        previous_rst = rst

    if not reset_rows:
        return (None, None, 'synchronous reset rst=1 never occurred')

    required = {
        'idle': 1,
        'scl_oen': 1,
        'sda_oen': 1,
        'cmd_ack': 0,
        'al': 0,
        'busy': 0,
        'sscl': 1,
        'ssda': 1,
    }

    for row in reset_rows:
        outputs = row.get('outputs', {})
        bad = [
            '%s=%r (expected %r)' % (port, outputs.get(port), value)
            for port, value in required.items()
            if outputs.get(port) != value
        ]
        if bad:
            return (
                False,
                row.get('edge'),
                'at the synchronous reset update edge, reset state was wrong: '
                + '; '.join(bad),
            )

    return (
        True,
        reset_rows[0].get('edge'),
        'at each synchronous reset assertion, idle and filtered SCL/SDA were high, '
        'output enables were released, and cmd_ack, al, and busy were low',
    )

