def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    reset = lambda r: inp(r, 'nReset') == 0 or inp(r, 'rst') == 1

    # The routed observation describes the contrasting non-reset active phase.
    contrasting = any(
        not reset(r)
        and out(r, 'fsm_active') == 1
        and out(r, 'scl_oen') == 0
        for r in trace
    )

    reset_rows = [r for r in trace if reset(r)]
    if not reset_rows:
        return (None, None, 'reset and initialization never occurred in this trace')
    if not contrasting:
        return (None, None, 'the routed scl_oen observation has no contrasting non-reset active-command case')

    bad = [r for r in reset_rows if out(r, 'scl_oen') != 1]
    if bad:
        return (False, bad[0].get('edge'), 'scl_oen was not initialized high during reset and initialization')

    return (True, reset_rows[0].get('edge'), 'scl_oen was initialized high during reset and initialization')

def decide(trace):
