def decide(trace):
    saw_active = False
    saw_evidence = False
    i = 0

    while i < len(trace):
        row = trace[i]
        inputs = row.get('inputs', {})

        # Reset aborts this requirement's post-reset sampling window.
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            i += 1
            continue

        saw_active = True
        target = (inputs.get('scl_i'), inputs.get('sda_i'))
        phase_start = i
        j = i

        # A phase lasts while the external bus inputs remain unchanged.
        while j < len(trace):
            r = trace[j]
            ri = r.get('inputs', {})
            if ri.get('nReset') == 0 or ri.get('rst') == 1:
                break
            if (ri.get('scl_i'), ri.get('sda_i')) != target:
                break
            j += 1

        phase_rows = trace[phase_start:j]
        matched = False
        for r in phase_rows:
            outputs = r.get('outputs', {})
            if (outputs.get('cscl'), outputs.get('csda')) == target:
                matched = True
                saw_evidence = True
                break

        # One distinct state cannot distinguish a correct synchronizer with
        # unspecified latency from a design that has not sampled yet.
        if not matched and len(phase_rows) > 1:
            return (
                False,
                phase_rows[0].get('edge'),
                'the module did not continuously sample scl_i and sda_i into cscl and csda '
                'during the sustained post-reset bus-input state'
            )

        if j == i:
            i += 1
        else:
            i = j

    if not saw_active:
        return (None, None, 'the module was never observed operating after reset')
    if not saw_evidence:
        return (None, None, 'post-reset sampling latency was not observable in this trace')
    return (True, None, 'scl_i and sda_i were observed sampled into cscl and csda after reset')

def decide(trace):
    operating = []
    segments = []
    current = []

    for row in trace:
        inputs = row['inputs']
        out_of_reset = inputs.get('nReset') != 0 and inputs.get('rst') != 1
        if out_of_reset:
            current.append(row)
        elif current:
            segments.append(current)
            current = []
    if current:
        segments.append(current)

    checked = False
    for segment in segments:
        first = segment[0]
        first_inputs = first['inputs']
        first_outputs = first['outputs']
        previous = {
            'scl_i': first_inputs.get('scl_i'),
            'sda_i': first_inputs.get('sda_i')
        }

        for port, sample in (('scl_i', 'cscl'), ('sda_i', 'csda')):
            target = previous[port]
            if first_outputs.get(sample) != target:
                checked = True
                found = None
                for later in segment:
                    if later['outputs'].get(sample) == target:
                        found = later
                        break
                if found is None:
                    return (False, first['edge'],
                            f'{sample} never sampled {port}={target} after reset')

        for i, row in enumerate(segment):
            now = row['inputs']
            for port, sample in (('scl_i', 'cscl'), ('sda_i', 'csda')):
                value = now.get(port)
                if value == previous[port]:
                    continue
                checked = True
                found = None
                for later in segment[i:]:
                    if later['outputs'].get(sample) == value:
                        found = later
                        break
                if found is None:
                    return (False, row['edge'],
                            f'{sample} never sampled changed {port}={value}')
            previous = {
                'scl_i': now.get('scl_i'),
                'sda_i': now.get('sda_i')
            }

    if not checked:
        return (None, None, 'no post-reset bus change or unsampled input value was observed')
    return (True, None, 'post-reset scl_i and sda_i values were eventually reflected in cscl and csda')

