def decide(trace):
    if not trace:
        return (None, None, 'no synchronous sampling states were observed')

    def pair(row, source):
        values = row.get(source, {})
        if source == 'inputs':
            return (values.get('scl_i'), values.get('sda_i'))
        return (values.get('cscl'), values.get('csda'))

    sampled = []
    for row in trace:
        value = pair(row, 'inputs')
        if not sampled or sampled[-1][0] != value:
            sampled.append((value, row))

    observed = [pair(row, 'outputs') for row in trace]
    search_from = 0
    matched = 0

    for value, input_row in sampled:
        found = None
        for index in range(search_from, len(observed)):
            if observed[index] == value:
                found = index
                break

        if found is None:
            return (
                False,
                input_row.get('edge'),
                'raw scl_i/sda_i state %r was never captured by cscl/csda; '
                'the requirement states that the raw signals are captured into '
                'two-stage synchronization registers on each rising edge of clk' % (value,)
            )

        matched += 1
        search_from = found

        # A later distinct raw state must be represented by a later observable
        # state. Repeated samples of the same raw pair may be represented by
        # the same held synchronized state.
        if matched < len(sampled):
            search_from = found + 1

    return (
        True,
        None,
        'all %d distinct raw scl_i/sda_i sampling state(s) appeared in order at cscl/csda'
        % matched
    )

def decide(trace):
    samples = []
    for row in trace:
        held = row.get('held', 1)
        for _ in range(max(0, held)):
            samples.append(row)

    checked = False
    for i in range(1, len(samples)):
        previous = samples[i - 1]
        current = samples[i]

        prev_inputs = previous['inputs']
        curr_inputs = current['inputs']
        prev_reset = (prev_inputs.get('nReset') == 0 or
                      prev_inputs.get('rst') == 1)
        curr_reset = (curr_inputs.get('nReset') == 0 or
                      curr_inputs.get('rst') == 1)

        # Reset initialization and the first post-reset synchronizer update
        # are outside this raw-input-to-second-stage comparison.
        if prev_reset or curr_reset:
            continue

        checked = True
        outputs = current['outputs']
        expected_scl = prev_inputs.get('scl_i')
        expected_sda = prev_inputs.get('sda_i')

        if outputs.get('cscl') != expected_scl:
            return (
                False,
                current.get('edge'),
                'cscl did not capture raw scl_i through the two-stage '
                'synchronizer on the preceding sampling edge'
            )
        if outputs.get('csda') != expected_sda:
            return (
                False,
                current.get('edge'),
                'csda did not capture raw sda_i through the two-stage '
                'synchronizer on the preceding sampling edge'
            )

    if not checked:
        return (
            None,
            None,
            'no comparable non-reset sampling interval; '
            'the raw scl_i and sda_i capture was not exercised'
        )

    return (
        True,
        None,
        'cscl and csda captured the preceding non-reset raw scl_i and sda_i samples'
    )

def decide(trace):
    active = []
    for row in trace:
        inputs = row.get('inputs', {})
        if inputs.get('nReset') == 1 and inputs.get('rst') == 0:
            active.append(row)

    if not active:
        return (None, None, 'no non-reset synchronous sampling states were observed')

    raw_scl = {row.get('inputs', {}).get('scl_i') for row in active}
    raw_sda = {row.get('inputs', {}).get('sda_i') for row in active}
    seen_cscl = {row.get('outputs', {}).get('cscl') for row in active}
    seen_csda = {row.get('outputs', {}).get('csda') for row in active}

    missing_scl = raw_scl - seen_cscl
    if missing_scl:
        value = next(iter(missing_scl))
        row = next(row for row in active
                   if row.get('inputs', {}).get('scl_i') == value)
        return (
            False,
            row.get('edge'),
            'raw scl_i value %r was never represented by the two-stage cscl '
            'synchronization observable; no edge or fixed latency is assumed' % value
        )

    missing_sda = raw_sda - seen_csda
    if missing_sda:
        value = next(iter(missing_sda))
        row = next(row for row in active
                   if row.get('inputs', {}).get('sda_i') == value)
        return (
            False,
            row.get('edge'),
            'raw sda_i value %r was never represented by the two-stage csda '
            'synchronization observable; no edge or fixed latency is assumed' % value
        )

    return (
        True,
        None,
        'all sampled raw scl_i and sda_i logic values were represented by '
        'cscl and csda without imposing an unstated edge, latency, or ordering'
    )

