def decide(trace):
    # These declared probes are the available observations for this clause,
    # but the obligation gives no testable condition on their values.
    observed = [
        (row['outputs'].get('cscl'), row['outputs'].get('csda'))
        for row in trace
    ]
    return (None, None, 'The obligation states only metastability-risk reduction; no observable condition on declared probes cscl or csda is licensed, and the two-stage capture itself belongs to REQ-0106.')

def decide(trace):
    if not trace:
        return (None, None, 'The capture state cscl was not reached; no capture-stage evidence is present')

    windows = [
        row for row in trace
        if row.get('outputs', {}).get('cscl') == 1
    ]
    if not windows:
        return (None, None, 'The capture state cscl was not reached in this trace')

    missing = [
        row for row in trace
        if 'csda' not in row.get('outputs', {})
    ]
    if missing:
        return (False, missing[0].get('edge'), 'The capture stage reached cscl but the paired captured bus signal csda was not observable')

    return (True, windows[0].get('edge'), 'The capture state cscl was reached and the paired captured bus signal csda was observable; no unstated capture latency or value encoding was required')

