from specflow.refmodel.temporal import TO_END, after, eventually, worst

def decide(trace):
    def out(row, name):
        return row['outputs'].get(name)

    verdicts = []
    for captured_scl in (0, 1):
        for captured_sda in (0, 1):
            def applies(row, scl=captured_scl, sda=captured_sda):
                return (
                    row['inputs'].get('ena') == 1
                    and out(row, 'cscl') == scl
                    and out(row, 'csda') == sda
                )

            windows = after(trace, applies, until=TO_END)
            verdicts.extend(
                eventually(
                    w,
                    lambda row, scl=captured_scl, sda=captured_sda: (
                        out(row, 'sscl') == scl
                        and out(row, 'ssda') == sda
                    ),
                    strong=True,
                    after_activation=False,
                )
                for w in windows
            )

    return worst(verdicts)

from specflow.refmodel.temporal import WHILE_ACTIVE, after, eventually, worst

def decide(trace):
    def applies(row):
        inputs = row['inputs']
        outputs = row['outputs']
        return (
            inputs.get('ena') == 1
            and outputs.get('cscl') == inputs.get('scl_i')
            and outputs.get('csda') == inputs.get('sda_i')
        )

    windows = after(trace, applies, until=WHILE_ACTIVE)
    verdicts = [
        eventually(
            w,
            lambda row: (
                row['outputs'].get('sscl') == row['inputs'].get('scl_i')
                and row['outputs'].get('ssda') == row['inputs'].get('sda_i')
            ),
            strong=False,
            after_activation=False,
        )
        for w in windows
    ]
    return worst(verdicts)

