def decide(trace):
    events = []
    for i, row in enumerate(trace):
        if row['inputs'].get('ena') != 1:
            continue
        if row['outputs'].get('filter_cnt') != 1:
            continue
        if i == 0 or trace[i - 1]['outputs'].get('filter_cnt') != 0:
            continue
        events.append(i)

    if len(events) < 2:
        return (None, None,
                'fewer than two filter_cnt sampling events; interval derived from '
                'the stated phrase "clk_cnt shifted by two bits (clk_cnt >> 2)" '
                'cannot be established')

    for first, second in zip(events, events[1:]):
        interval_rows = trace[first:second]
        if any(r['inputs'].get('ena') != 1 for r in interval_rows):
            continue
        values = [r['inputs'].get('clk_cnt') for r in interval_rows]
        if any(v != values[0] for v in values):
            continue

        elapsed = sum(r.get('held', 1) for r in interval_rows)
        expected = max(values[0] >> 2, 1)
        if elapsed != expected:
            return (False, trace[second].get('edge'),
                    f'filter_cnt sampling interval was {elapsed} enabled edges; '
                    f'expected max(clk_cnt >> 2, 1) = {expected}, from the stated '
                    'phrase "clk_cnt shifted by two bits (clk_cnt >> 2)"')

    checked = 0
    for first, second in zip(events, events[1:]):
        interval_rows = trace[first:second]
        if any(r['inputs'].get('ena') != 1 for r in interval_rows):
            continue
        values = [r['inputs'].get('clk_cnt') for r in interval_rows]
        if any(v != values[0] for v in values):
            continue
        checked += 1

    if checked == 0:
        return (None, None,
                'filter_cnt events were separated by disabled filter progression '
                'or changing clk_cnt, so no fixed interval could be decided')
    return (True, None,
            f'{checked} filter_cnt interval(s) matched max(clk_cnt >> 2, 1), '
            'with the interval derived from the stated phrase '
            '"clk_cnt shifted by two bits (clk_cnt >> 2)"')

def decide(trace):
    reloads = []

    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        previous_cnt = previous['outputs'].get('filter_cnt')
        current_cnt = current['outputs'].get('filter_cnt')
        clk_cnt = current['inputs'].get('clk_cnt')

        # A reload is the counter increasing; ordinary countdown states do not
        # expose the configured sampling interval.
        if (isinstance(previous_cnt, int) and isinstance(current_cnt, int)
                and isinstance(clk_cnt, int)
                and current_cnt > previous_cnt):
            reloads.append((current, current_cnt, clk_cnt >> 2))

    if not reloads:
        return (None, None, 'filter_cnt reload was not observed; the sampling interval was not exercised')

    for row, actual, expected in reloads:
        if actual != expected:
            return (
                False,
                row['edge'],
                f"filter_cnt reloaded to {actual}, expected clk_cnt >> 2 = {expected}"
            )

    return (
        True,
        reloads[-1][0]['edge'],
        'filter_cnt reload value matched clk_cnt >> 2 for every observed reload'
    )

def decide(trace):
    events = []
    for i, row in enumerate(trace):
        if row['inputs'].get('ena') != 1:
            continue
        if row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1:
            continue
        if row['outputs'].get('filter_cnt') != 1:
            continue
        if i == 0 or trace[i - 1]['outputs'].get('filter_cnt') != 0:
            continue
        events.append(i)

    observations = []
    for first, second in zip(events, events[1:]):
        rows = trace[first:second]
        if any(r['inputs'].get('ena') != 1 or
               r['inputs'].get('nReset') == 0 or
               r['inputs'].get('rst') == 1 for r in rows):
            continue
        values = [r['inputs'].get('clk_cnt') for r in rows]
        if not values or any(v != values[0] for v in values):
            continue
        observations.append((sum(r.get('held', 1) for r in rows), values[0], second))

    if not observations:
        return (None, None,
                'fewer than two comparable filter_cnt sampling events; the interval '
                'derived from the stated phrase "clk_cnt shifted by two bits '
                '(clk_cnt >> 2)" was not exercised')

    for interval, clk_cnt, second in observations:
        shifted = clk_cnt >> 2
        if shifted == 0:
            allowed = {1}
        else:
            allowed = {shifted, shifted + 1}
        if interval not in allowed:
            return (False, trace[second].get('edge'),
                    f'filter_cnt sampling interval was {interval} enabled edges for '
                    f'clk_cnt >> 2 = {shifted}; expected the shifted interval or its '
                    'single-edge counter reload/expiry convention, from the stated '
                    'phrase "clk_cnt shifted by two bits (clk_cnt >> 2)"')

    return (True, None,
            f'{len(observations)} filter_cnt sampling interval(s) followed '
            'clk_cnt >> 2, allowing the unspecified one-edge counter '
            'reload/expiry convention')

