from specflow.refmodel.temporal import TO_END, after


def decide(trace):
    def applies(row):
        values = row.get("outputs", {})
        return (row.get("inputs", {}).get("ena") == 1
                and values.get("filter_cnt") == 0)

    windows = after(trace, applies, until=TO_END)
    if not windows:
        return (None, None,
                "the filter counter never expired while filter progression was enabled")

    for window in windows:
        if not window.rows:
            continue
        row = window.rows[0]
        outputs = row.get("outputs", {})
        if outputs.get("fscl") != 1 or outputs.get("fsda") != 1:
            missing = []
            if outputs.get("fscl") != 1:
                missing.append("fSCL")
            if outputs.get("fsda") != 1:
                missing.append("fSDA")
            return (False, row["edge"],
                    "Whenever this counter expires, new synchronized samples "
                    "are shifted into the three-sample histories `fSCL` and `fSDA`; "
                    + " and ".join(missing) + " was not shifted")

    return (True, None,
            "each observed filter-counter expiration shifted new synchronized "
            "samples into both `fSCL` and `fSDA`")

from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst


def decide(trace):
    def activation(row):
        return (
            row['inputs'].get('ena') == 1
            and row['outputs'].get('filter_cnt') == 0
        )

    def samples_shifted(row):
        outputs = row['outputs']
        return (
            outputs.get('fscl') == outputs.get('cscl')
            and outputs.get('fsda') == outputs.get('csda')
        )

    windows = after(trace, activation, until=WHILE_ACTIVE)
    verdicts = [
        throughout(
            window,
            samples_shifted,
            after_activation=False,
        )
        for window in windows
    ]
    result = worst(verdicts)
    if result[0] is None:
        return (None, None, 'the filter counter never expired while filter progression was enabled')
    if result[0] is False:
        return (False, result[1], 'Whenever this counter expires, new synchronized samples are shifted into the three-sample histories `fSCL` and `fSDA`.')
    return (True, result[1], 'Whenever this counter expires, new synchronized samples are shifted into the three-sample histories `fSCL` and `fSDA`.')

