def decide(trace):
    history_scl = []
    history_sda = []
    checked = False

    def majority(values):
        return 1 if sum(values) >= 2 else 0

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            history_scl = []
            history_sda = []
            continue

        if inputs.get('ena') != 1:
            history_scl = []
            history_sda = []
            continue

        if outputs.get('filter_cnt') != 0 or outputs.get('cnt_zero') != 1:
            continue

        cscl = outputs.get('cscl')
        csda = outputs.get('csda')
        if cscl not in (0, 1) or csda not in (0, 1):
            continue

        history_scl.append(cscl)
        history_sda.append(csda)
        history_scl = history_scl[-3:]
        history_sda = history_sda[-3:]

        if len(history_scl) < 3:
            continue

        checked = True
        expected_scl = majority(history_scl)
        expected_sda = majority(history_sda)

        candidates = [i]
        if i + 1 < len(trace):
            candidates.append(i + 1)

        matched = False
        for j in candidates:
            candidate = trace[j].get('outputs', {})
            if (candidate.get('sscl') == expected_scl and
                    candidate.get('ssda') == expected_sda):
                matched = True
                break

        if not matched:
            return (
                False,
                row.get('edge'),
                'filtered sscl/ssda did not equal the majority of the three '
                'most recent synchronized cscl/csda samples'
            )

    if not checked:
        return (None, None, 'no counter-expiry supplied three synchronized samples')

    return (True, None, 'sscl and ssda matched the majority of their three-sample histories')

