def decide(trace):
    # sscl and ssda are declared observable probes, but the obligation
    # assigns them a role rather than stating a separately checkable effect.
    _observed = [
        (row["outputs"].get("sscl"), row["outputs"].get("ssda"))
        for row in trace
    ]
    return (None, None, 'The obligation defines the role of declared probes sscl and ssda but states no independently testable effect; majority computation belongs to REQ-0111.')

def decide(trace):
    # sscl and ssda are the declared observable probes for this definition.
    # The obligation does not specify a separately testable value or timing
    # property for them; majority filtering is covered by REQ-0111.
    for row in trace:
        row['outputs'].get('sscl')
        row['outputs'].get('ssda')
    return (None, None, 'REQ-0112 defines sscl and ssda as stable internal bus versions but states no independently testable output obligation; majority filtering belongs to REQ-0111')

def decide(trace):
    active = [
        r for r in trace
        if r.get('outputs', {}).get('sscl') == 1
    ]
    if not active:
        return (None, None, 'sscl never became high; the filtered-SCL situation did not occur')

    for row in active:
        outputs = row.get('outputs', {})
        if 'sscl' not in outputs or 'ssda' not in outputs:
            return (False, row.get('edge'), 'filtered internal signals sscl and ssda were not both available')
        if outputs['sscl'] not in (0, 1) or outputs['ssda'] not in (0, 1):
            return (False, row.get('edge'), 'filtered internal signals sscl and ssda must be one-bit sampled values')

    return (True, None, 'sscl was reached and both filtered internal signals sscl and ssda were available throughout the observed sscl situation')

