def decide(trace):
    def value(row, name):
        return row['outputs'].get(name)

    checks = []
    exercised = False

    for source, delayed in (("sscl", "dscl"), ("ssda", "dsda")):
        for i in range(1, len(trace)):
            previous = value(trace[i - 1], source)
            current = value(trace[i], source)
            if previous == current:
                continue

            exercised = True
            found = False
            for j in range(i + 1, len(trace)):
                if value(trace[j], delayed) == current and value(trace[j - 1], delayed) != current:
                    found = True
                    break

            if not found:
                edge = trace[i].get('edge')
                return (
                    False,
                    edge,
                    f"{delayed} did not make the filtered {source} transition "
                    f"to {current} in a later distinct state; the requirement "
                    "does not specify an exact delay"
                )

            checks.append(trace[j].get('edge'))

    if not exercised:
        return (None, None, "no filtered SCL or SDA transition occurred; delayed behaviour was not exercised")

    return (
        True,
        checks[-1] if checks else None,
        "each observed filtered SCL/SDA transition was followed by the corresponding delayed transition without imposing a fixed edge count"
    )

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    checks = []

    for filtered, delayed, label in (
        ("sscl", "dscl", "dSCL"),
        ("ssda", "dsda", "dSDA"),
    ):
        changed = edges(trace, filtered, "change")
        if not changed:
            continue

        for edge in changed:
            windows = after(
                trace,
                lambda r, e=edge: r["edge"] == e,
                until=TO_END,
            )
            for window in windows:
                first = window.rows[0]
                target = first["outputs"][filtered]
                delayed_at_change = first["outputs"][delayed]

                if delayed_at_change == target:
                    checks.append((
                        False,
                        first["edge"],
                        f"{label} changed to the new {filtered} value on the same state; it must be delayed"
                    ))
                    continue

                checks.append(eventually(
                    window,
                    lambda r, p=delayed, v=target: r["outputs"][p] == v,
                    strong=True,
                    after_activation=True,
                ))

    return worst(checks)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    pending = []
    exercised = False
    matched = []

    for i, row in enumerate(trace):
        # Reset or arbitration loss ends the operating situation for this
        # observation; no delayed response is owed after that point.
        if row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1 or out(row, 'al') == 1:
            pending = []
            continue

        if i > 0:
            previous = trace[i - 1]
            for source, delayed in (('sscl', 'dscl'), ('ssda', 'dsda')):
                old_value = out(previous, source)
                new_value = out(row, source)
                if old_value != new_value:
                    exercised = True
                    pending.append((source, delayed, new_value, i))

        remaining = []
        for source, delayed, expected, opened in pending:
            if out(row, delayed) == expected:
                matched.append(row.get('edge'))
            else:
                remaining.append((source, delayed, expected, opened))
        pending = remaining

    if not exercised:
        return (None, None, 'no filtered SCL or SDA transition occurred; delayed behaviour was not exercised')

    if not matched:
        return (None, None, 'no un-aborted later state showed a corresponding delayed filtered value')

    return (
        True,
        matched[-1],
        'dSCL and dSDA each reached corresponding filtered values without imposing an exact delay'
    )

