def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, edges, throughout

    def event_windows(direction):
        changes = edges(trace, "ssda", direction)

        def applies(row):
            outputs = row["outputs"]
            return (
                row["inputs"].get("ena") == 1
                and row["edge"] in changes
                and outputs.get("sscl") == 1
                and outputs.get("ssda") != outputs.get("dsda")
            )

        return after(trace, applies, until=WHILE_ACTIVE)

    start_windows = event_windows("fall")
    stop_windows = event_windows("rise")

    def check(windows, expected, description):
        results = []
        for w in windows:
            results.append(
                throughout(
                    w,
                    lambda row: row["outputs"].get("busy") == expected,
                    after_activation=False,
                )
            )
        for result in results:
            if result[0] is False:
                return (False, result[1],
                        f"{description}: busy did not have the required value {expected}")
        return None

    bad = check(start_windows, 1, "filtered SDA high-to-low event")
    if bad is not None:
        return bad
    bad = check(stop_windows, 0, "filtered SDA low-to-high event")
    if bad is not None:
        return bad

    if not start_windows or not stop_windows:
        return (None, None,
                "both filtered START and STOP comparison events were not observed")

    return (True, None,
            "busy matched both filtered SDA comparison events: rise-to-high START and rise-to-low STOP")

def decide(trace):
    seen = set()
    unknown = False

    def direction(row):
        out = row['outputs']
        if out['sscl'] != 1 or out['ssda'] == out['dsda']:
            return None
        if out['ssda'] == 0 and out['dsda'] == 1:
            return 'start'
        if out['ssda'] == 1 and out['dsda'] == 0:
            return 'stop'
        return None

    for i, row in enumerate(trace):
        if row['inputs'].get('ena') != 1:
            continue

        kind = direction(row)
        if kind is None:
            continue

        previous_kind = None
        if i > 0 and trace[i - 1]['inputs'].get('ena') == 1:
            previous_kind = direction(trace[i - 1])
        if previous_kind == kind:
            continue

        seen.add(kind)
        if i == 0:
            unknown = True
            continue

        previous_busy = trace[i - 1]['outputs']['busy']
        current_busy = row['outputs']['busy']
        expected = 1 if kind == 'start' else 0
        if current_busy != expected or previous_busy == current_busy:
            event = 'filtered SDA high-to-low START' if kind == 'start' else 'filtered SDA low-to-high STOP'
            return (False, row['edge'],
                    f'{event} detected by ssda/dsda while sscl was high, but busy did not make the required transition')

    if not seen:
        return (None, None, 'no enabled filtered SDA transition relative to dsda while sscl was high')
    if unknown or seen != {'start', 'stop'}:
        return (None, None, 'only one direction of the routed busy observation was exercised')

    return (True, None,
            'filtered SDA transitions relative to dsda produced both the required busy rise and busy fall')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    ssda_falls = edges(trace, "ssda", "fall")
    ssda_rises = edges(trace, "ssda", "rise")
    busy_rises = edges(trace, "busy", "rise")
    busy_falls = edges(trace, "busy", "fall")

    def comparison_event(edge_set, current, delayed, target_busy_edge):
        def applies(row):
            outputs = row["outputs"]
            return (
                row["inputs"].get("ena") == 1
                and row["edge"] in edge_set
                and outputs.get("sscl") == 1
                and outputs.get(current) != outputs.get(delayed)
                and outputs.get("write_sequence") != 1
            )

        windows = after(trace, applies, until=TO_END)
        return [
            eventually(
                w,
                lambda r: r["edge"] in target_busy_edge,
                after_activation=False,
                strong=False,
            )
            for w in windows
        ]

    start_checks = comparison_event(
        ssda_falls, "ssda", "dsda", busy_rises
    )
    stop_checks = comparison_event(
        ssda_rises, "ssda", "dsda", busy_falls
    )

    checks = start_checks + stop_checks
    if not checks:
        return (
            None,
            None,
            "no enabled non-WRITE filtered SDA comparison event while filtered SCL was high",
        )
    return worst(checks)

