def decide(trace):
    from specflow.refmodel.temporal import edges

    falling_ssda = edges(trace, "ssda", "fall")
    activations = []
    for row in trace:
        if row["edge"] not in falling_ssda:
            continue
        if row["outputs"].get("sscl") != 1:
            continue
        if row["inputs"].get("ena") != 1:
            continue
        if row["inputs"].get("scl_i") != 1:
            continue
        if row["inputs"].get("sda_i") != 0:
            continue
        activations.append(row)

    if not activations:
        return (None, None, "filtered SDA did not fall while filtered SCL was high in the qualified enabled situation")

    for row in activations:
        if row["outputs"].get("sta_condition") != 1:
            return (False, row["edge"], "filtered SDA fell while filtered SCL was high, but sta_condition was not asserted")

    return (True, activations[-1]["edge"], f"sta_condition asserted for all {len(activations)} qualified filtered START transition(s)")

