def decide(trace):
    from specflow.refmodel.temporal import after, worst

    def out(row, port):
        return row['outputs'].get(port)

    def probe_is(port, value):
        return lambda row: out(row, port) == value

    # The declared probes are the filtered START/STOP detection events.
    start_activation = lambda row: (
        row['inputs'].get('ena') == 1 and out(row, 'sta_condition') == 1
    )
    stop_activation = lambda row: (
        row['inputs'].get('ena') == 1 and out(row, 'sto_condition') == 1
    )

    start_windows = after(
        trace,
        start_activation,
        until=probe_is('sto_condition', 1),
    )
    stop_windows = after(
        trace,
        stop_activation,
        until=probe_is('sta_condition', 1),
    )

    verdicts = []

    for window in start_windows:
        if not window.rows:
            verdicts.append((None, window.edge, 'START window contained no state'))
            continue
        row = window.rows[0]
        if out(row, 'busy') != 1:
            verdicts.append((
                False,
                row['edge'],
                'busy was not set after an I2C START condition was detected',
            ))
        else:
            verdicts.append((
                True,
                row['edge'],
                'busy is set after an I2C START condition was detected',
            ))

    for window in stop_windows:
        if not window.rows:
            verdicts.append((None, window.edge, 'STOP window contained no state'))
            continue
        row = window.rows[0]
        if out(row, 'busy') != 0:
            verdicts.append((
                False,
                row['edge'],
                'busy was not cleared after an I2C STOP condition was detected',
            ))
        else:
            verdicts.append((
                True,
                row['edge'],
                'busy is cleared after an I2C STOP condition was detected',
            ))

    return worst(verdicts)

def decide(trace):
    events = []

    for i, row in enumerate(trace):
        if row['inputs'].get('ena') != 1:
            continue

        previous = trace[i - 1]['outputs'] if i > 0 else {}
        current = row['outputs']

        sta = current.get('sta_condition') == 1
        sto = current.get('sto_condition') == 1
        previous_sta = previous.get('sta_condition') == 1
        previous_sto = previous.get('sto_condition') == 1

        if sta and not previous_sta:
            events.append(('START', row))
        if sto and not previous_sto:
            events.append(('STOP', row))

    if not events:
        return (None, None, 'no filtered START or STOP condition was detected')

    for kind, row in events:
        expected = 1 if kind == 'START' else 0
        actual = row['outputs'].get('busy')
        if actual != expected:
            return (
                False,
                row['edge'],
                f'busy was {actual} when the detected {kind} condition required busy == {expected}'
            )

    return (
        True,
        events[-1][1]['edge'],
        'busy was set on each detected START and cleared on each detected STOP'
    )

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst

    def value(row, port):
        return row['outputs'].get(port)

    def is_value(port, expected):
        return lambda row: value(row, port) == expected

    start = lambda row: (
        row['inputs'].get('ena') == 1
        and value(row, 'sta_condition') == 1
    )
    stop = lambda row: (
        row['inputs'].get('ena') == 1
        and value(row, 'sto_condition') == 1
    )

    # The opposite filtered condition ends the status interval governed by
    # this condition; the probes are declared ports for this requirement.
    start_windows = after(
        trace,
        start,
        until=is_value('sto_condition', 1),
    )
    stop_windows = after(
        trace,
        stop,
        until=is_value('sta_condition', 1),
    )

    follows = False
    verdicts = []

    for window in start_windows:
        verdicts.append(
            throughout(
                window,
                lambda row: value(row, 'busy') == 1,
                after_activation=follows,
            )
        )

    for window in stop_windows:
        verdicts.append(
            throughout(
                window,
                lambda row: value(row, 'busy') == 0,
                after_activation=follows,
            )
        )

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, worst

    def out(row, port):
        return row['outputs'].get(port)

    # The normalized activation says ena qualifies the detected condition;
    # the declared condition probes are the design-driven trigger.
    start = lambda row: (
        row['inputs'].get('ena') == 1
        and row['inputs'].get('sda_i') == 0
        and out(row, 'sta_condition') == 1
    )
    stop = lambda row: (
        row['inputs'].get('ena') == 1
        and row['inputs'].get('sda_i') == 1
        and out(row, 'sto_condition') == 1
    )

    # A START governs the status until a STOP is detected.  The STOP
    # condition itself is checked by the separate STOP obligation.
    start_windows = after(
        trace,
        start,
        until=lambda row: out(row, 'sto_condition') == 1,
    )

    # A STOP's cleared status may be observed at any later distinct state;
    # no cycle latency is specified.
    stop_windows = after(trace, stop, until=TO_END)

    verdicts = []
    for window in start_windows:
        verdicts.append(
            eventually(
                window,
                lambda row: out(row, 'busy') == 1,
                strong=True,
                after_activation=False,
            )
        )

    for window in stop_windows:
        verdicts.append(
            eventually(
                window,
                lambda row: out(row, 'busy') == 0,
                strong=True,
                after_activation=False,
            )
        )

    return worst(verdicts)

