from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def active(row):
        return any(out(row, p) == 1 for p in (
            'start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence'))

    def enabled(row):
        return (row.get('inputs', {}).get('ena') == 1
                and row.get('inputs', {}).get('nReset') == 1
                and row.get('inputs', {}).get('rst') == 0
                and out(row, 'al') == 0
                and active(row))

    def stretching_or_sync(row):
        return (enabled(row)
                and out(row, 'scl_oen') == 1
                and (out(row, 'slave_wait') == 1 or out(row, 'scl_sync') == 1))

    def accommodated(row):
        return (enabled(row)
                and out(row, 'scl_oen') == 1
                and out(row, 'sscl') == 1
                and out(row, 'slave_wait') == 0
                and out(row, 'scl_sync') == 0)

    held_windows = after(
        trace,
        stretching_or_sync,
        until=lambda r: not stretching_or_sync(r))

    release_indices = []
    for i in range(1, len(trace)):
        if stretching_or_sync(trace[i - 1]) and accommodated(trace[i]):
            release_indices.append(trace[i]['index'])

    release_windows = after(
        trace,
        lambda r: r['index'] in release_indices,
        until=TO_END)

    withheld = [
        throughout(
            w,
            lambda r: out(r, 'cmd_ack') == 0)
        for w in held_windows
    ]
    completed = [
        eventually(
            w,
            lambda r: out(r, 'cmd_ack') == 1,
            strong=True,
            after_activation=True)
        for w in release_windows
    ]

    return worst(withheld + completed)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def active(row):
        return any(out(row, p) == 1 for p in (
            'start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence'))

    def stretch_or_sync(row):
        return active(row) and out(row, 'scl_oen') == 1 and (
            out(row, 'sscl') == 0 or
            out(row, 'scl_sync') == 1 or
            out(row, 'filtered_scl_falling') == 1)

    special_events = []
    in_special = False
    for i, row in enumerate(trace):
        now = stretch_or_sync(row)
        if now and not in_special:
            special_events.append(i)
        in_special = now

    saw_special = bool(special_events)
    saw_normal = False
    saw_bad_ack = False
    saw_late_ack = False
    failure_edge = None

    for i, row in enumerate(trace):
        if out(row, 'cmd_ack') != 1:
            continue

        prior_special = any(j <= i and stretch_or_sync(trace[j]) for j in range(i + 1))
        if not prior_special:
            if any(active(trace[j]) for j in range(i + 1)):
                saw_normal = True
            continue

        event = max(j for j in special_events if j <= i)
        released_after = any(
            j > event and out(trace[j], 'sscl') == 1
            for j in range(event + 1, i + 1)
        )
        if not released_after:
            saw_bad_ack = True
            failure_edge = row.get('edge')
        else:
            saw_late_ack = True

    if saw_bad_ack:
        return (False, failure_edge, 'cmd_ack occurred before filtered SCL was released high during clock stretching or synchronization')
    if not saw_special or not saw_normal:
        return (None, None, 'the trace does not show both the stretching/synchronization case and the normal cmd_ack case needed to distinguish this routed requirement')
    if not saw_late_ack:
        return (None, None, 'clock stretching or synchronization occurred, but the trace ended before a post-release cmd_ack could be observed')
    return (True, None, 'cmd_ack was withheld during the stretching or synchronization condition and observed only after filtered SCL was high')

from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def active(row):
        return any(out(row, p) == 1 for p in (
            'start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence'))

    def owned_scl_high(row):
        return out(row, 'scl_oen') == 1

    def stretch_or_sync(row):
        if inp(row, 'ena') != 1 or not active(row) or not owned_scl_high(row):
            return False
        return (out(row, 'sscl') == 0 or
                out(row, 'scl_sync') == 1 or
                out(row, 'filtered_scl_falling') == 1)

    def accommodated(row):
        return (inp(row, 'ena') == 1 and active(row) and owned_scl_high(row)
                and out(row, 'sscl') == 1
                and out(row, 'scl_sync') == 0)

