def decide(trace):
    def qualified(row):
        out = row.get('outputs', {})
        inp = row.get('inputs', {})
        active = any(out.get(p) == 1 for p in (
            'start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence'))
        return (
            active
            and inp.get('ena') == 1
            and inp.get('nReset') != 0
            and inp.get('rst') != 1
            and out.get('slave_wait') != 1
            and out.get('scl_sync') != 1
        )

    transitions = []
    run_edges = 0
    previous = None
    previous_qualified = False

    for row in trace:
        if not qualified(row):
            run_edges = 0
            previous = None
            previous_qualified = False
            continue

        value = row.get('outputs', {}).get('scl_oen')
        held = row.get('held', 1)
        if previous_qualified and value != previous:
            transitions.append((row, run_edges))
            run_edges = held
        else:
            run_edges += held
        previous = value
        previous_qualified = True

    if not transitions:
        return (None, None, 'no qualifying scl_oen phase transition was observed')

    for row, elapsed in transitions:
        clk_cnt = row.get('inputs', {}).get('clk_cnt')
        if not isinstance(clk_cnt, int):
            return (None, row.get('edge'), 'clk_cnt was unavailable at the observed phase transition')
        if elapsed < clk_cnt:
            return (
                False,
                row.get('edge'),
                f"scl_oen changed after {elapsed} rising-edge states, before the clk_cnt value {clk_cnt} could be decremented"
            )

    return (
        True,
        transitions[-1][0].get('edge'),
        f"{len(transitions)} qualifying scl_oen phase transition(s) respected the clk_cnt-derived minimum"
    )

def decide(trace):
    active = []
    in_sequence = False
    start_edge = None

    for row in trace:
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1
        enabled = inputs.get('ena') == 1
        running = outputs.get('fsm_active') == 1
        excluded = reset or not enabled or outputs.get('slave_wait') == 1 or outputs.get('scl_sync') == 1

        if running and not excluded:
            if not in_sequence:
                in_sequence = True
                start_edge = row.get('edge')
            active.append(row)
        else:
            if in_sequence and not running:
                if not active:
                    return (False, start_edge, 'the active command sequence produced no observable timing phase')
                changed = any(
                    active[i]['outputs'].get('scl_oen') != active[i - 1]['outputs'].get('scl_oen')
                    for i in range(1, len(active))
                )
                if not changed:
                    return (False, active[-1].get('edge'), 'the active command sequence completed without an scl_oen phase transition')
                active = []
                in_sequence = False
                start_edge = None

    if not active:
        return (None, None, 'no uninterrupted enabled supported command sequence occurred')

    for i in range(1, len(active)):
        previous = active[i - 1]
        current = active[i]
        if previous['outputs'].get('scl_oen') == current['outputs'].get('scl_oen'):
            continue
        clk_cnt = previous.get('inputs', {}).get('clk_cnt')
        if not isinstance(clk_cnt, int):
            continue
        required_edges = max(1, clk_cnt)
        held_edges = previous.get('held', 1)
        if held_edges < required_edges:
            return (
                False,
                current.get('edge'),
                f"scl_oen phase lasted {held_edges} edges, but loading clk_cnt and decrementing on each clock requires at least {required_edges} edges"
            )

    changed = any(
        active[i]['outputs'].get('scl_oen') != active[i - 1]['outputs'].get('scl_oen')
        for i in range(1, len(active))
    )
    if not changed:
        return (None, None, 'the timing sequence remains active at the end of the trace; no phase completion was observed')

    return (True, None, 'scl_oen phase changes occurred only after intervals consistent with loading clk_cnt and decrementing once per rising clock')

