def decide(trace):
    qualifying = []
    i = 0
    while i < len(trace):
        row = trace[i]
        ena = row['inputs'].get('ena')
        if ena != 0 or (i > 0 and trace[i - 1]['inputs'].get('ena') == 0):
            i += 1
            continue

        # The disable must begin after an active command, not in idle or reset.
        k = i - 1
        active_before = False
        while k >= 0 and trace[k]['inputs'].get('ena') != 0:
            if trace[k]['outputs'].get('fsm_active') == 1:
                active_before = True
                break
            k -= 1
        if not active_before:
            i += 1
            continue

        end = i
        while end < len(trace) and trace[end]['inputs'].get('ena') == 0:
            if trace[end]['outputs'].get('cmd_ack') == 1:
                return (False, trace[end]['edge'],
                        'cmd_ack asserted while ena=0 during an active command')
            end += 1

        # Require observable evidence that this command later resumed and completed.
        resumed_ack = None
        for j in range(end, len(trace)):
            if trace[j]['outputs'].get('cmd_ack') == 1:
                resumed_ack = trace[j]
                break
        if resumed_ack is not None:
            qualifying.append((trace[i], resumed_ack))

        i = max(end, i + 1)

    if not qualifying:
        return (None, None,
                'no active-command ena disable with an observable completion after re-enable')

    first, ack = qualifying[0]
    return (True, ack['edge'],
            'cmd_ack stayed low while ena disabled, then completion occurred after ena was re-enabled')

