def decide(trace):
    # Values are transcribed from the specification's stated OpenCores
    # encodings: START=1, STOP=2, WRITE=4, READ=8, NOP=0.
    commands = {1: 'START', 2: 'STOP', 4: 'WRITE', 8: 'READ', 0: 'no operation'}
    activations = []

    def value(row, name):
        return row.get('outputs', {}).get(name,
               row.get('inputs', {}).get(name))

    def accepted(row):
        cmd = value(row, 'cmd')
        return (value(row, 'idle') == 1 and
                value(row, 'clk_en') == 1 and
                cmd in commands)

    for i, row in enumerate(trace):
        if not accepted(row):
            continue
        if i > 0 and accepted(trace[i - 1]):
            continue
        activations.append((i, value(row, 'cmd')))

    if not activations:
        return (None, None, 'no supported command was sampled while the FSM was idle')

    for start, cmd in activations:
        name = commands[cmd]
        start_scl = value(trace[start], 'scl_oen')

        if cmd == 0:
            # Keep this check within the idle/no-op extent.  A later command
            # or scenario must not be attributed to the no-op activation.
            previous = start_scl
            for j in range(start + 1, len(trace)):
                row = trace[j]
                if value(row, 'idle') != 1 or value(row, 'cmd') != 0:
                    break
                current = value(row, 'scl_oen')
                if previous != 0 and current == 0:
                    return (False, row.get('edge'),
                            'cmd=0 was decoded as no operation, but scl_oen began a command sequence')
                previous = current
            continue

        # A supported command must leave idle and produce the visible
        # command-specific SCL output-enable behavior.  Search states, not
        # clock edges, so unspecified latency remains open.
        became_active = False
        drove_low = None
        released_high = None
        previous = start_scl

        for j in range(start + 1, len(trace)):
            row = trace[j]
            idle = value(row, 'idle')
            current = value(row, 'scl_oen')

            if idle != 1:
                became_active = True

            if became_active and drove_low is None:
                if previous != 0 and current == 0:
                    drove_low = j
            elif became_active and drove_low is not None and released_high is None:
                if value(trace[drove_low], 'scl_oen') == 0 and current == 1:
                    released_high = j

            if became_active and idle == 1:
                break
            previous = current

        if not became_active or drove_low is None:
            return (False, trace[start].get('edge'),
                    f'cmd={name} was sampled in idle but no command-specific scl_oen drive-low state was reached')

        if cmd == 2 and released_high is None:
            return (False, trace[drove_low].get('edge'),
                    'cmd=STOP drove scl_oen low but did not subsequently release scl_oen high')

    return (True, None,
            'each sampled START, STOP, READ, or WRITE command reached its visible scl_oen sequence, and cmd=0 did not start one')

