    )

def decide(trace):
    commands = {
        1: ("START", "start_sequence"),
        2: ("STOP", "stop_sequence"),
        8: ("READ", "read_sequence"),
        4: ("WRITE", "write_sequence"),
        0: ("no operation", None),
    }
    sequence_probes = tuple(name for _, name in commands.values() if name is not None)

    def val(row, name):
        return row.get("outputs", {}).get(name,
               row.get("inputs", {}).get(name))

    def active(row):
        return val(row, "idle") == 1 and val(row, "cmd") in commands

    activations = []
    for i, row in enumerate(trace):
        if active(row) and (i == 0 or not active(trace[i - 1])):
            activations.append(i)

    if not activations:
        return (None, None, "no supported command was observed while the FSM was idle")

    for start in activations:
        row = trace[start]
        cmd = val(row, "cmd")
        name, selected_probe = commands[cmd]
        end = len(trace)
        for j in range(start + 1, len(trace)):
            if val(trace[j], "idle") != 1:
                end = j
                break

        if selected_probe is None:
            for j in range(start, end):
                if any(val(trace[j], p) == 1 for p in sequence_probes):
                    return (False, trace[j].get("edge"),
                            "cmd=0 was decoded as no operation, but a command sequence became active")
            continue

        for j in range(start + 1, end):
            if val(trace[j], selected_probe) == 1:
                break
            if any(val(trace[j], p) == 1 for p in sequence_probes if p != selected_probe):
                return (False, trace[j].get("edge"),
                        f"cmd={name} selected a different command sequence")
        else:
            if end < len(trace):
                return (False, trace[start].get("edge"),
                        f"cmd={name} was sampled in idle but its corresponding command sequence was not reached")
            return (None, None,
                    f"cmd={name} was sampled in idle, but the trace ended before its selected sequence was observable")

    return (True, None, "each observed idle command selected its corresponding sequence, and no-operation selected none")

