def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def is_idle_enabled(row):
        return (
            row.get('outputs', {}).get('idle') == 1
            and row.get('inputs', {}).get('ena') == 1
        )

    activations = []
    previous_qualifying = False
    previous_cmd = None

    for i, row in enumerate(trace):
        qualifying = is_idle_enabled(row)
        cmd = row.get('inputs', {}).get('cmd')

        # A changed command while the FSM is idle is a new command occurrence.
        # A held command returning to idle after completion is not reopened.
        new_occurrence = qualifying and (
            not previous_qualifying or cmd != previous_cmd
        )
        if new_occurrence:
            activations.append(i)

        previous_qualifying = qualifying
        previous_cmd = cmd

    if not activations:
        return (None, None, 'the idle-and-enabled command activation never occurred')

    for start in activations:
        start_row = trace[start]
        command = start_row.get('inputs', {}).get('cmd')
        transition = None

        for j in range(start + 1, len(trace)):
            row = trace[j]
            if row.get('inputs', {}).get('ena') != 1:
                break
            if row.get('inputs', {}).get('cmd') != command:
                break
            if row.get('outputs', {}).get('idle') != 1:
                transition = j
                break

        if transition is None:
            # The command remained unsupported or idle for the observed
            # transaction, so the required idle behaviour was maintained.
            continue

        row = trace[transition]
        entered = [
            port for port in sequence_ports
            if row.get('outputs', {}).get(port) == 1
        ]
        if len(entered) != 1:
            return (
                False,
                row.get('edge'),
                'the FSM left idle without entering exactly one corresponding '
                'START, STOP, READ, or WRITE command sequence'
            )

    return (
        True,
        None,
        'each observed idle-and-enabled command either remained in idle or '
        'entered exactly one declared command sequence'
    )

