        fell = previous_stop == 1 and not stop
        previous_stop = 1 if stop else 0

        if fell and row.get('inputs', {}).get('ena') == 1 \
                and out.get('scl_oen') == 1 \
                and out.get('sda_oen') == 1:
            completions.append(pos)

    if not completions:
        return (None, None, 'no completed STOP sequence was observed')

    for pos in completions:
        completion = trace[pos]
        completion_edge = completion.get('edge')
        prior_ack = 0
        if pos > 0:
            prior_ack = trace[pos - 1].get('outputs', {}).get('cmd_ack', 0)

        ack_row = None
        ack_edge = completion_edge
        ack_was_rising = False
        last_ack = prior_ack

        for later in trace[pos:]:
            ack = later.get('outputs', {}).get('cmd_ack', 0)
            if ack == 1 and last_ack != 1:
                ack_row = later
                ack_edge = later.get('edge')
                ack_was_rising = True
                break
            last_ack = ack

        if not ack_was_rising:
            return (False, completion_edge,
                    'the completed STOP command did not produce a cmd_ack pulse')

        ack_out = ack_row.get('outputs', {})
        if ack_out.get('idle') != 1:
            return (False, ack_edge,
                    'cmd_ack was not accompanied by the FSM being idle')
        if ack_row.get('held') != 1:
            return (False, ack_edge,
                    f'cmd_ack was held for {ack_row.get("held")} edges, expected one clock')

        ended = False
        for later in trace:
            if later is ack_row:
                ended = True
                continue
            if not ended:
                continue
            if later.get('outputs', {}).get('cmd_ack') == 1:
                return (False, later.get('edge'),
                        'cmd_ack remained high beyond its one-clock pulse')
            ended = False
            break

        if ended:
            return (None, ack_edge,
                    'the trace ended before the cmd_ack pulse was observed to end')

    return (True, None,
            f'{len(completions)} completed STOP sequence(s) returned to idle and pulsed cmd_ack')

def decide(trace):
    # A STOP completion is the SDA-release transition while SCL is already
    # released, immediately following the declared STOP sequence.
    completions = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        prev = trace[i - 1]
        if (prev['outputs'].get('sda_oen') != 1
                and row['outputs'].get('sda_oen') == 1
                and row['outputs'].get('scl_oen') == 1
                and prev['outputs'].get('stop_sequence') == 1
                and row['inputs'].get('ena') == 1):
            completions.append(i)

    if not completions:
        return (None, None, 'STOP completion was not exercised in this trace')

    for i in completions:
        row = trace[i]
        edge = row['edge']

        if row['outputs'].get('idle') != 1:
            return (False, edge, 'FSM did not return to idle after STOP completion')

        if row['outputs'].get('cmd_ack') != 1:
            return (False, edge, 'cmd_ack was not high at STOP completion')

        if i > 0 and trace[i - 1]['outputs'].get('cmd_ack') == 1:
            return (False, edge, 'cmd_ack was already high before STOP completion')

        remaining = row['held']
        j = i + 1
        while j < len(trace) and trace[j]['outputs'].get('cmd_ack') == 1:
            remaining += trace[j]['held']
            j += 1
        if remaining != 1:
            return (False, edge, f'cmd_ack pulse lasted {remaining} edges, expected exactly 1')

    return (True, None, f'{len(completions)} STOP completion(s) returned idle and pulsed cmd_ack')

