def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    in_read = False
    saw_filtered_rise = False
    completions = []
    reset_seen = False
    aborted = False

    for i, row in enumerate(trace):
        rst = row.get('inputs', {}).get('rst', 0) == 1
        nreset = row.get('inputs', {}).get('nReset', 1) == 0
        al = out(row, 'al') == 1
        read_seq = out(row, 'read_sequence') == 1
        filtered_rise = out(row, 'filtered_scl_rising') == 1

        if rst or nreset:
            reset_seen = True
            in_read = False
            saw_filtered_rise = False
            aborted = False
            continue

        if not in_read and read_seq:
            in_read = True
            saw_filtered_rise = False
            aborted = False

        if in_read and filtered_rise:
            saw_filtered_rise = True

        if in_read and al:
            aborted = True

        if in_read and not read_seq:
            if saw_filtered_rise and not aborted and not reset_seen:
                completions.append(i)
            in_read = False
            saw_filtered_rise = False
            aborted = False
            reset_seen = False

    if not completions:
        return (None, None, 'no completed READ bit cycle was observed')

    for start in completions:
        for j in range(start, len(trace)):
            row = trace[j]
            if row.get('inputs', {}).get('rst', 0) == 1 or row.get('inputs', {}).get('nReset', 1) == 0:
                break
            if out(row, 'al') == 1:
                break
            if out(row, 'read_sequence') == 1 and j > start:
                break
            if out(row, 'idle') == 1 and out(row, 'cmd_ack') == 1:
                return (True, row.get('edge'), 'after READ completion, idle is asserted and cmd_ack asserts')

        row = trace[start]
        return (False, row.get('edge'), 'after READ completion, the FSM did not reach idle with cmd_ack asserted')

    return (None, None, 'no completed READ bit cycle was observed')

