            saw_read_bit_rise = False
            aborted = False
            continue

        if read_sequence and not in_read:
            in_read = True
            saw_read_bit_rise = False
            aborted = arbitration_lost

        if in_read:
            if filtered_rise:
                saw_read_bit_rise = True
            if arbitration_lost:
