                values = row['outputs'] if port in row['outputs'] else row['inputs']
                if values.get(port) != value:
                    return False
            return True
        return predicate

    def any_condition(conditions):
        predicates = [holds(condition) for condition in conditions]
        return lambda row: any(predicate(row) for predicate in predicates)

    # Use the declared WRITE-state probe as the command signature; no
    # undocumented numeric command encoding is assumed.
    applies = lambda row: (
