def decide(trace):
    verdicts = []
    previous_active = False
    i = 0

    while i < len(trace):
        row = trace[i]
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        active = outputs.get('write_sequence') == 1 and inputs.get('ena') == 1

        # Open once per rising WRITE-sequence activation.  The probe is the
        # declared signature of the situation, avoiding an unstated cmd code.
        if active and not previous_active:
            din_value = inputs.get('din')
            start_edge = row.get('edge')
            j = i + 1
            outcome = None
            detail = None

            while j < len(trace):
                current = trace[j]
                current_outputs = current.get('outputs', {})
                current_inputs = current.get('inputs', {})

                if (current_inputs.get('nReset') == 0 or
                        current_inputs.get('rst') == 1 or
                        current_outputs.get('al') == 1):
                    detail = 'WRITE window aborted by reset or arbitration loss'
                    outcome = None
                    break

                if current_outputs.get('cmd_ack') == 1:
                    if outcome is None:
                        outcome = True
                    break

                expected = din_value
                actual = current_outputs.get('sda_oen')
                if din_value not in (0, 1):
                    detail = 'din was not a binary value during the WRITE activation'
                    outcome = None
                    break
                if actual != expected:
                    detail = (
                        f"sda_oen was {actual} for din={din_value}; "
                        "the obligation requires sda_oen == 0 for din=0 "
                        "and sda_oen == 1 for din=1"
                    )
                    outcome = False
                    break

                j += 1

            if outcome is False:
                verdicts.append((False, current.get('edge'), detail))
            elif outcome is True:
                verdicts.append((True, None, f'sda_oen matched din throughout the WRITE data-output phase opened at edge {start_edge}'))
            else:
                verdicts.append((None, None, detail or 'WRITE activation was not completed before the trace ended'))

        previous_active = active
        i += 1

