        aborts=aborted,
    )

    if not windows:
        return (None, None, 'WRITE sequence never began')

    verdicts = []

    for window in windows:
        rows = window.rows
        ack_pos = next(
            (i for i, row in enumerate(rows)
             if out(row, 'cmd_ack') == 1),
            None,
        )

        if ack_pos is None:
            if any(aborted(row) for row in rows):
                verdicts.append((None, window.edge,
