                             'WRITE completion did not return the FSM to idle'))
            continue
        if not (high_pos < low_pos <= idle_pos <= ack_pos):
            verdicts.append((False, ack_row.get('edge'),
                             'WRITE phases occurred in the wrong order'))
            continue

        pulse_result = pulse(
            window,
            'cmd_ack',
