def decide(trace):
    if not trace:
        return (None, None, 'no module-output observation occurred')

    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('scl_o') != 0:
            return (False, row.get('edge'), 'scl_o is not constant low as required')
        if outputs.get('sda_o') != 0:
            return (False, row.get('edge'), 'sda_o is not constant low as required')

    sequence_names = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')
    seen_sequence = False
    i = 0

    while i < len(trace):
        outputs = trace[i].get('outputs', {})
        active = [name for name in sequence_names if outputs.get(name) == 1]
        if not active:
            i += 1
            continue

        seen_sequence = True
