            row_outputs = trace[j].get('outputs', {})
            if not any(row_outputs.get(name) == 1 for name in sequence_names):
                break
            j += 1

        rows = trace[i:j]
        first_edge = rows[0].get('edge')
        scl_values = {r.get('outputs', {}).get('scl_oen') for r in rows}
        sda_values = {r.get('outputs', {}).get('sda_oen') for r in rows}

        if any(r.get('outputs', {}).get('start_sequence') == 1 or
               r.get('outputs', {}).get('stop_sequence') == 1 for r in rows):
            if not ({0, 1} <= scl_values):
                return (False, first_edge,
                        'START/STOP line-control sequence did not use both scl_oen drive (0) and release (1) modes')
            if not ({0, 1} <= sda_values):
                return (False, first_edge,
                        'START/STOP line-control sequence did not use both sda_oen drive (0) and release (1) modes')

        if any(r.get('outputs', {}).get('read_sequence') == 1 for r in rows):
            if not ({0, 1} <= scl_values):
                return (False, first_edge,
                        'READ line-control sequence did not use both scl_oen drive (0) and release (1) modes')
            if any(r.get('outputs', {}).get('sda_oen') != 1 for r in rows):
                return (False, first_edge,
                        'READ sequence did not keep SDA released with sda_oen equal to 1')

        if any(r.get('outputs', {}).get('write_sequence') == 1 for r in rows):
            if not ({0, 1} <= scl_values):
                return (False, first_edge,
                        'WRITE line-control sequence did not use both scl_oen drive (0) and release (1) modes')
