            saw_activation = True
            if outputs.get('scl_o') != 0:
                return (False, row['edge'], "scl_o was not low while scl_oen was low; requirement: 'When an output enable is low, the corresponding line is driven low.'")

        if sda_oen == 0:
            saw_activation = True
            if outputs.get('sda_o') != 0:
                return (False, row['edge'], "sda_o was not low while sda_oen was low; requirement: 'When an output enable is low, the corresponding line is driven low.'")

    if not saw_activation:
        return (None, None, "neither output enable was low; the requirement was not activated")

    return (True, None, "scl_o and sda_o were low whenever their corresponding output enables were low")

