def decide(trace):
    activated = []
    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('scl_oen') == 1 or outputs.get('sda_oen') == 1:
            activated.append(row)
    if not activated:
        return (None, None, 'scl_oen or sda_oen never became high; the activation did not occur')
    return (None, activated[0].get('edge'), 'the stated effect is produced by the external pull-up on input lines, which is not observable as DUT behavior')

def decide(trace):
    seen = []
    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('scl_oen') == 1:
            seen.append(('scl_oen', row))
        if outputs.get('sda_oen') == 1:
            seen.append(('sda_oen', row))
    if not seen:
        return (None, None, 'Neither declared release port scl_oen nor sda_oen became high; the activation did not occur')
    return (True, seen[0][1].get('edge'), 'Declared release port(s) scl_oen/sda_oen are high; the external pull-up effect is outside the DUT observables')

