from specflow.refmodel.temporal import TO_END, after, eventually, pulse, worst

def decide(trace):
    def holds(cond):
        def predicate(row):
            values = {}
            values.update(row.get('inputs', {}))
            values.update(row.get('outputs', {}))
            return all(values.get(port) == value for port, value in cond.items())
        return predicate

    command_values = {1, 2, 4, 8}

    def accepted_command(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (
            inputs.get('cmd') in command_values
            and inputs.get('ena') == 1
            and outputs.get('idle') == 1
        )

    def aborted(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (
            outputs.get('al') == 1
            or inputs.get('nReset') == 0
            or inputs.get('rst') == 1
        )

    windows = after(
        trace,
        accepted_command,
        until=holds({'cmd_ack': 1}),
        aborts=aborted,
    )

    follows = True
    verdicts = []
    for window in windows:
        verdicts.append(
            eventually(
                window,
                lambda row: row.get('outputs', {}).get('cmd_ack') == 1,
                strong=True,
                after_activation=follows,
            )
        )
        verdicts.append(
            pulse(
                window,
                'cmd_ack',
                width=1,
                active=1,
                after_activation=follows,
            )
        )

    result = worst(verdicts)
    ok, edge, detail = result
    if ok is False:
        detail = detail + "; required exactly one `clk` cycle at command completion"
    elif ok is True:
        detail = detail + "; `cmd_ack` was asserted for exactly one `clk` cycle at command completion"
    return (ok, edge, detail)

