def decide(trace):
    seq_ports = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')
    completed = []
    active = {}

    for i, row in enumerate(trace):
        outputs = row.get('outputs', {})
        if outputs.get('nReset', 1) == 0 or row.get('inputs', {}).get('rst', 0) == 1:
            active.clear()
            continue
        if outputs.get('al', 0) == 1:
            active.clear()
            continue

        for port in seq_ports:
            level = outputs.get(port, 0)
            if level and not active.get(port, False):
                active[port] = True
            elif not level and active.get(port, False):
                completed.append(i)
                active[port] = False

    if not completed:
        return (None, None, 'no START, STOP, READ, or WRITE sequence completed in this trace')

    for end_i in completed:
        ack_i = None
        next_start = len(trace)
        for j in range(end_i, len(trace)):
            outputs = trace[j].get('outputs', {})
            if outputs.get('nReset', 1) == 0 or trace[j].get('inputs', {}).get('rst', 0) == 1:
                break
            if outputs.get('al', 0) == 1:
                break
            if j > end_i and any(outputs.get(p, 0) == 1 for p in seq_ports):
                next_start = j
                break
            if outputs.get('cmd_ack', 0) == 1:
                ack_i = j
                break
        if ack_i is None or ack_i >= next_start:
            return (False, trace[end_i]['edge'], 'cmd_ack did not assert after the completed bit-level operation')
        held = trace[ack_i].get('held', 1)
        if held != 1:
            return (False, trace[ack_i]['edge'], f'cmd_ack held for {held} clock edges, expected exactly one')

    return (True, trace[completed[-1]]['edge'], 'each completed bit-level operation produced a one-clock cmd_ack pulse')

def decide(trace):
    # `cmd_ack` is the declared observable for this requirement.  The
    # obligation describes its acknowledge role, but does not independently
    # license checking the exact one-clock duration or terminal timing.
    saw_cmd_ack = any(r.get('outputs', {}).get('cmd_ack') == 1 for r in trace)
    if not saw_cmd_ack:
        return (None, None, 'cmd_ack was not observed; no acknowledge pulse occurred in this trace')
    return (None, None, 'cmd_ack was observed; exact one-clock completion checking belongs to REQ-0155')

def decide(trace):
    seq_ports = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')
    valid_cmds = (1, 2, 4, 8)
    active = None
    completions = []
    prev = None

    def reset_or_abort(row):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        return (inputs.get('nReset', 1) == 0 or
                inputs.get('rst', 0) == 1 or
                outputs.get('al', 0) == 1)

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        if reset_or_abort(row):
            active = None
            prev = row
            continue

        levels = {p: outputs.get(p, 0) for p in seq_ports}
        old_levels = ({p: prev.get('outputs', {}).get(p, 0) for p in seq_ports}
                      if prev is not None else
                      {p: 0 for p in seq_ports})

        rising = [p for p in seq_ports
                  if old_levels[p] == 0 and levels[p] == 1]
        falling = [p for p in seq_ports
                   if old_levels[p] == 1 and levels[p] == 0]

        if active is None and rising:
            if inputs.get('ena', 0) == 1 and inputs.get('cmd') in valid_cmds:
                active = rising[0]

        if active is not None and active in falling:
            completions.append(i)
            active = None

        prev = row

    if not completions:
        return (None, None, 'no non-aborted START, STOP, READ, or WRITE sequence completed')

    for end_i in completions:
        ack_rise = None
        boundary = len(trace)

        for j in range(end_i, len(trace)):
            row = trace[j]
            if reset_or_abort(row):
                boundary = j
                break
            if j > end_i:
                previous_outputs = trace[j - 1].get('outputs', {})
                current_outputs = row.get('outputs', {})
                if any(previous_outputs.get(p, 0) == 0 and
                       current_outputs.get(p, 0) == 1
                       for p in seq_ports):
                    boundary = j
                    break
            previous_ack = (trace[j - 1].get('outputs', {}).get('cmd_ack', 0)
                            if j > 0 else 0)
            current_ack = row.get('outputs', {}).get('cmd_ack', 0)
            if current_ack == 1 and previous_ack == 0:
                ack_rise = j
                break

        if ack_rise is None:
            if boundary < len(trace) and reset_or_abort(trace[boundary]):
                continue
            return (False, trace[end_i].get('edge'),
                    'cmd_ack did not assert after the completed bit-level operation')

        width = 0
        k = ack_rise
        while k < len(trace) and trace[k].get('outputs', {}).get('cmd_ack', 0) == 1:
            width += trace[k].get('held', 1)
            k += 1
        if width != 1:
            return (False, trace[ack_rise].get('edge'),
                    f'cmd_ack held for {width} clock edges, expected exactly one')

    return (True, trace[completions[-1]].get('edge'),
            'each non-aborted completed bit-level operation produced a one-clock cmd_ack pulse')

def decide(trace):
    seq_ports = ('start_sequence', 'stop_sequence', 'read_sequence', 'write_sequence')
    valid_cmds = (1, 2, 4, 8)

    def values(row):
        return row.get('outputs', {})

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset', 1) == 0 or inputs.get('rst', 0) == 1

    def arbitration_lost(row):
        return values(row).get('al', 0) == 1

    def level(row, port):
        return values(row).get(port, 0)

    active = None
    completions = []

    for i, row in enumerate(trace):
        if reset_active(row):
            active = None
            continue

        previous = trace[i - 1] if i else None
        inputs = row.get('inputs', {})

        for port in seq_ports:
            now = level(row, port)
            before = level(previous, port) if previous is not None else 0

            if active is None and before == 0 and now == 1:
                if inputs.get('ena') == 1 and inputs.get('cmd') in valid_cmds:
                    active = port

            if active == port and before == 1 and now == 0:
                if not arbitration_lost(row):
                    completions.append(i)
                active = None

    if not completions:
        return (None, None,
                'no completed START, STOP, READ, or WRITE sequence was observed')

    for end_i in completions:
        boundary = len(trace)
        ack_rise = None

        for j in range(end_i, len(trace)):
            row = trace[j]
            if reset_active(row) or arbitration_lost(row):
                boundary = j
                break

            if j > end_i:
                previous = trace[j - 1]
                if any(level(previous, p) == 0 and level(row, p) == 1
                       for p in seq_ports):
                    boundary = j
                    break

            current_ack = level(row, 'cmd_ack')
            previous_ack = level(trace[j - 1], 'cmd_ack') if j else 0
            if current_ack == 1 and previous_ack == 0:
                ack_rise = j
                break

        if ack_rise is None:
            if boundary < len(trace) and (reset_active(trace[boundary]) or
                                          arbitration_lost(trace[boundary])):
                continue
            return (False, trace[end_i].get('edge'),
                    'cmd_ack did not assert after the completed bit-level operation')

        width = 0
        k = ack_rise
        while k < len(trace) and level(trace[k], 'cmd_ack') == 1:
            width += trace[k].get('held', 1)
            k += 1

        if width != 1:
            return (False, trace[ack_rise].get('edge'),
                    f'cmd_ack acknowledge pulse lasted {width} clock edges; expected one clock edge')

    return (True, trace[completions[-1]].get('edge'),
            'each observed completed command produced a one-clock cmd_ack acknowledge pulse')
